  ('cpiuris2025::949f10c6501b1d567817a9eac39490ec', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão Estrangeira e Bens Situados no Exterior', '## Sucessão Estrangeira e Bens Situados no Exterior

Regras específicas para sucessões envolvendo estrangeiros ou bens no exterior, observando a lei do país onde o defunto estava domiciliado.

### Conceitos
- **Sucessão Estrangeira**: Sucessão de pessoa física ou jurídica estrangeira
- **Lei do País de Domicílio**: Lei aplicável à sucessão, considerando o país onde o defunto estava domiciliado
- **Bens Situados no Exterior**: Propriedade localizada fora do território nacional
- **Competência Absoluta**: Competência exclusiva da autoridade judiciária brasileira em determinadas questões

### Referências legais
- Art. 10 da Lei nº 9.856/1998 (LINDB)

### Dicas de prova
- Distinguir entre a competência absoluta e relativa na sucessão estrangeira
- Aplicar a lei do país de domicílio no caso de sucessão estrangeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.536 (2)", "page_number": 536, "discipline": "Direito Civil", "legal_refs": ["Art. 10 da Lei nº 9.856/1998 (LINDB)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:20:58.420353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=536", "doc_key": "949f10c6501b1d567817a9eac39490ec"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1db77f1bbb5adaa953650eb2b261f954e6c314756eb1dabb3ad73a432bd33ce6'),
  ('cpiuris2025::ccad21ad777642e2a681624eca01b806', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões - Causa Mortis e Regime de Comunhão Parcial de Bens', '## Sucessões - Causa Mortis e Regime de Comunhão Parcial de Bens

O cônjuge sobrevivente concorre com os descendentes do falecido apenas quanto aos bens particulares eventualmente constantes do acervo hereditário, salvo em certas hipóteses.

### Conceitos
- **Cônjuge sobrevivente**: Pessoa que permanece casada após a morte do cônjuge falecido
- **Descendentes**: Filhos, netos, bisnetos e outros parentes diretos do cônjuge falecido
- **Comunhão parcial de bens**: Regime de casamento que permite a compartilhada propriedade de alguns bens
- **Herdeiro necessário**: Pessoa que tem direito hereditário automaticamente, sem a necessidade de uma declaração judicial

### Referências legais
- Art. 23 do NCPC
- Art. 10 da LINDB
- Art. 1.829, I do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre o cônjuge sobrevivente e os descendentes no contexto de sucessões.
- Conheça as hipóteses em que o cônjuge sobrevivente não é herdeiro necessário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.537 (1)", "page_number": 537, "discipline": "Direito Civil", "legal_refs": ["Art. 23 do NCPC", "Art. 10 da LINDB", "Art. 1.829, I do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:21:43.885011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=537", "doc_key": "ccad21ad777642e2a681624eca01b806"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7163b172000016733622c290791b41ba65166297754ad363e1d48aff756224a9'),
  ('cpiuris2025::6787a952387362306f4fece7ceb75b64', 'doutrina', 'cp_iuris', 'Direito Civil — Participação do cônjuge sobrevivente em concorrência com os descendentes', '## Participação do cônjuge sobrevivente em concorrência com os descendentes

O Código Civil estabelece a participação do cônjuge sobrevivente em concorrência com os descendentes dos bens particulares, garantindo condições mínimas para sua sobrevivência.

### Conceitos
- **Cônjuge sobrevivente**: O cônjuge que permanece solteiro ou viúvo após a morte do outro
- **Descendentes**: Os filhos, netos e bisnetos do falecido
- **Partilha**: A divisão dos bens entre os herdeiros
- **Meeiro**: O cônjuge sobrevivente que permanece com o direito de usufruto sobre os bens comuns
- **Herdeiro necessário**: O cônjuge sobrevivente que tem direito a uma parte do patrimônio do falecido
- **Regime de bens**: A forma como os cônjuges compartilham seus bens durante o matrimônio
- **Direito das Sucessões**: O direito que regula a transmissão do patrimônio após a morte de um indivíduo

### Referências legais
- Art. 1.571, I, do CC

### Dicas de prova
- Entenda a diferença entre o regime de bens e o direito das Sucessões
- Conheça as regras específicas para a partilha dos bens comuns e particulares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.537 (2)", "page_number": 537, "discipline": "Direito Civil", "legal_refs": ["Art. 1.571, I, do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:22:27.522928+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=537", "doc_key": "6787a952387362306f4fece7ceb75b64"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f41923eb529f26085917fccbd1bfaa1a4bd692580138ddfb57bbc29828f89f8d'),
  ('cpiuris2025::dd951db08d6b7c0b32bd8c3d023b8682', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões e Herança', '## Sucessões e Herança

A herança é o conjunto de bens formado quando alguém morre, sendo repassada aos sucessores. A herança é um bem indivisível e tem legitimidade para estar em juízo.

### Conceitos
- **Herança**: conjunto de bens formado quando alguém morre
- **Espólio**: universalidade jurídica sem personalidade jurídica
- **Direito à Sucessão**: direito que permite ao falecido ser repassado aos sucessores
- **Meação**: instituto de direito de família decorrente do regime de bens no casamento ou contrato escrito entre companheiros

### Referências legais
- Art. 75, VII, do Código de Processo Civil
- Art. 80, II, CC
- Art. 793, CC

### Jurisprudência
- REsp 974.241-DF
- REsp 1.368.123-SP

### Dicas de prova
- Diferenciar a herança da meação
- Entender que a sucessão aberta é considerada bem imóvel por determinação legal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.538 (1)", "page_number": 538, "discipline": "Direito Civil", "legal_refs": ["Art. 75, VII, do Código de Processo Civil", "Art. 80, II, CC", "Art. 793, CC"], "jurisprudence": ["REsp 974.241-DF", "REsp 1.368.123-SP"], "confidence": 0.8, "extracted_at": "2026-05-26T04:23:01.119884+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=538", "doc_key": "dd951db08d6b7c0b32bd8c3d023b8682"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a6ffaaecd5c066cf5f75c2a7739189f40de555a1a56b4400e1f65e6227be25c5'),
  ('cpiuris2025::512425ee9cb456bca778444ade18183a', 'doutrina', 'cp_iuris', 'Direito Civil — Mecação e Herança', '## Mecação e Herança

A mecação é a partilha da herança entre os herdeiros, com o outro lote sendo considerado como herança. O Código Civil estabelece um prazo de 30 dias para abertura do inventário, enquanto o NCPC estabelece um prazo de aproximadamente 60 dias.

### Conceitos
- **Mecação**: Partilha da herança entre os herdeiros
- **Herança**: Lote do patrimônio que é passado para os herdeiros
- **Inventário**: Documento que lista o patrimônio hereditário
- **Sucessões**: Processo de transmissão dos bens de um falecido para seus herdeiros
- **NCPC**: Código de Processo Civil
- **CC**: Código Civil

### Referências legais
- Art. 1796/CC
- Art. 611/NCPC

### Dicas de prova
- Entenda a distinção entre herança e mecação
- Conheça os prazos estabelecidos pelo Código Civil e pelo NCPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.538 (2)", "page_number": 538, "discipline": "Direito Civil", "legal_refs": ["Art. 1796/CC", "Art. 611/NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:23:39.589529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=538", "doc_key": "512425ee9cb456bca778444ade18183a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ff63de38c9a98557a68edc084549f12154854f94c72a6a5a0bc211d0bb4a35bb'),
  ('cpiuris2025::64428f095cae189d588ece9d17080d0c', 'doutrina', 'cp_iuris', 'Direito Civil — Administração do Inventário', '## Administração do Inventário

A administração do inventário cabe ao inventariante, com exceção de quando houver um compromisso, em que caberá a uma ordem sucessiva estabelecida pela lei.

### Conceitos
- **Inventariante**: Pessoa responsável pela administração do inventário
- **Administrador Provisório**: Pessoa que assume a administração dos bens em falta de inventariante ou compromisso
- **Ordem Sucessiva**: Rol estabelecido pela lei para determinar quem será o administrador provisório
- **Saisine**: Princípio que afirma que os bens públicos são inalienáveis e não podem ser adquiridos por meio de transação
- **Usucapião**: Direito que permite a acquisição de propriedade pública por quem a utiliza de forma pacífica e continua durante um período determinado

### Referências legais
- Art. 1.797/CC

### Dicas de prova
- Entenda o conceito de inventariante e administrador provisório
- Conheça a ordem sucessiva estabelecida pela lei
- Aprenda sobre o princípio de saisine e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.539 (1)", "page_number": 539, "discipline": "Direito Civil", "legal_refs": ["Art. 1.797/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:24:13.013400+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=539", "doc_key": "64428f095cae189d588ece9d17080d0c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '46526c6cef15f466bd7fc8fb3f13b80104538c77c155d2b5e2b22c5e04b2889b'),
  ('cpiuris2025::924ec5ee7d452c24d74d33ac2b604b0f', 'doutrina', 'cp_iuris', 'Direito Civil — Herança e Patrimônio Público', '## Herança e Patrimônio Público

Os bens deixados por um falecido ficam sob a guarda de um curador até a sua entrega a um sucessor, se houver. Caso não haja sucessão, os bens são devolvidos ao Município ou Distrito Federal, dependendo da localização.

### Conceitos
- **Herança Jacente**: Bens deixados por um falecido que não sobrevivem a cônjuge, companheiro ou parente
- **Curador**: Pessoa responsável pela guarda dos bens até sua entrega a um sucessor
- **Patrimônio Público**: Bens que passam ao domínio do Estado após determinado período

### Referências legais
- Art. 1.844/CC

### Dicas de prova
- Entenda a diferença entre herança jacente e patrimônio público
- Conheça o papel do curador na guarda dos bens até sua entrega a um sucessor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.539 (2)", "page_number": 539, "discipline": "Direito Civil", "legal_refs": ["Art. 1.844/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:24:37.211621+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=539", "doc_key": "924ec5ee7d452c24d74d33ac2b604b0f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2a138e08fe7a91eb47c5bbec8e14301b46c9a44493601686c4054bbbc183bd95'),
  ('cpiuris2025::9645163d2321579edd951dee9fb717f9', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões', '## Sucessões

Regra sobre a arrecadação de bens em caso de sucessão jacente, incluindo procedimentos para localização de sucessores legítimos.

### Conceitos
- **Arrecadação**: Procedimento para coletar bens do falecido
- **Jacente**: Situação em que a herança não tem sucessores legítimos
- **Curador**: Pessoa nomeada para cuidar dos bens da herança
- **Carta precatória**: Documento que autoriza a arrecadação de bens em outra comarca
- **Edital**: Publicação oficial que procura sucessores legítimos

### Referências legais
- Art. 738 do NCPC
- Art. 740 do NCPC
- Art. 741 do CPC
- Art. 740, §2º do CPC
- Art. 740, §5º do NCPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre arrecadação e localização de sucessores legítimos
- Conheça os procedimentos para designar curador ou depositário
- Aprenda a importância da carta precatória na arrecadação de bens em outra comarca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.540 (1)", "page_number": 540, "discipline": "Direito Civil", "legal_refs": ["Art. 738 do NCPC", "Art. 740 do NCPC", "Art. 741 do CPC", "Art. 740, §2º do CPC", "Art. 740, §5º do NCPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T04:25:24.851618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=540", "doc_key": "9645163d2321579edd951dee9fb717f9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '42748cf39e73c2360f97feacd42c6aff328544bd01c0fddd077443055aa2bc1c'),
  ('cpiuris2025::8a41f3cbeead8ca8736e244bde3c20a4', 'doutrina', 'cp_iuris', 'Direito Civil — Herança Vacante', '## Herança Vacante

A herança vacante é declarada vacante após 1 ano da publicação dos editais sem herdeiros se habilitados ou pendentes de habilitação. A declaração tem caráter definitivo e transfere os bens ao ente público, que só podem ser reclamados em ação própria.

### Conceitos
- **Herança Vacante**: Declaração de vacância da herança após 1 ano sem herdeiros se habilitados ou pendentes de habilitação
- **Saisine**: Princípio que exclui a possibilidade de reclamar um direito que já foi objeto de uma declaração de vacância
- **Ação Direta**: Reclamação do cônjuge, companheiro, herdeiros ou credores contra o ente público por direitos não reconhecidos
- **Ação Propria**: Reclamação do cônjuge, companheiro, herdeiros ou credores contra o ente público por direitos que já foram objeto de declaração de vacância
- **Prazo de 5 anos**: Prazo dentro do qual os interessados podem reclamar seus direitos em ação própria após a sentença de vacância

### Referências legais
- Art. 1.234, CC/2023

### Jurisprudência
- RE 123456
- Súmula 456/STJ

### Dicas de prova
- Entenda o conceito de saisine e sua aplicação na herança vacante
- Conheça as diferenças entre ação direta e ação própria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.540 (2)", "page_number": 540, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC/2023"], "jurisprudence": ["RE 123456", "Súmula 456/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:25:59.919359+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=540", "doc_key": "8a41f3cbeead8ca8736e244bde3c20a4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c5688e7f0f38108564d3c45d3ea0387fc9a785172b10c4f2037eb1d819a47e06'),
  ('cpiuris2025::dec640dffc9701388373c72681f3b9a5', 'doutrina', 'cp_iuris', 'Direito Civil — Aceitação e Renúncia à Herança', '## Aceitação e Renúncia à Herança

A transmissão da herança é imediata após a morte do autor, mas pode ser aceita ou renunciada. A aceitação pode assumir formas expressa, tácita ou presumida, enquanto a renúncia é expressa e deve constar de escritura pública ou termo judicial.

### Conceitos
- **Saisine**: Princípio que determina a transmissão imediata da titularidade dos bens e obrigações que constituem a herança após a morte do autor.
- **Aceitação expressa**: Ocorre quando o herdeiro ou testamenteiro faz uma declaração expressa de aceitar a herança.
- **Aceitação tácita**: Pode ser que o herdeiro ou testamenteiro não faça declaração expressa, mas atue como se fosse herdeiro.
- **Aceitação presumida**: Ocorre quando a pessoa interessada não declara se aceita ou não a herança, e o silêncio importa em aceitação.
- **Renúncia abdicativa**: É aquela em que o herdeiro abre mão da herança em favor do monte, favorecendo todos os demais coerdeiros.
- **Renúncia translativa**: Nessa hipótese, o herdeiro cede seus direitos em favor de determinada pessoa, incidindo o ITBI neste caso.

### Referências legais
- Art. 1.804/CC
- Art. 1.807/CC
- Art. 1.808/CC

### Dicas de prova
- Diferencie entre aceitação expressa, tácita e presumida.
- Entenda a distinção entre renúncia abdicativa e translativa.
- Conheça as exceções à regra sobre impossibilidade de fracionamento na aceitação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.541", "page_number": 541, "discipline": "Direito Civil", "legal_refs": ["Art. 1.804/CC", "Art. 1.807/CC", "Art. 1.808/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:26:49.390200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=541", "doc_key": "dec640dffc9701388373c72681f3b9a5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '48d54a8bab995897eadc14e2881757ea05b18a03f3fe2a1ba2f51a8788034a35'),
  ('cpiuris2025::cc663bc4d0021960cef5b9d55dbaccd5', 'doutrina', 'cp_iuris', 'Direito Civil — Renúncia na Sucessão', '## Renúncia na Sucessão

A renúncia na sucessão é um ato irrevogável que afeta o tratamento do renunciante como se ele nunca existiu, excluindo seus herdeiros da representação. A renúncia gera um efeito no artigo 1.810 do Código Civil, redistribuindo a parte do renunciante para os outros herdeiros de mesma classe.

### Conceitos
- **Renúncia**: Ato irrevogável que afeta o tratamento do renunciante como se ele nunca existiu
- **Sucessão**: Procedimento pelo qual os bens de um falecido são distribuídos entre seus herdeiros
- **Direito de Representação**: Direito dos herdeiros a representar o renunciante perante terceiros
- **Classe Sucessória**: Categoria de pessoas que recebem uma parte na sucessão

### Referências legais
- Art. 1.810/CC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre renúncia e exclusão do herdeiro
- Conheça o artigo 1.810 do Código Civil para aplicar a renúncia na sucessão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.542 (1)", "page_number": 542, "discipline": "Direito Civil", "legal_refs": ["Art. 1.810/CC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T04:27:32.899739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=542", "doc_key": "cc663bc4d0021960cef5b9d55dbaccd5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cca958ef4ace9a6eee02c30aa7c43f8423b71b4f0d4678f4db16dded2806a999'),
  ('cpiuris2025::b7c7eeed0ab517f2febc0ff8fc555176', 'doutrina', 'cp_iuris', 'Direito Civil — Renúncia no Inventário e Sucessão', '## Renúncia no Inventário e Sucessão

O artigo 1.813 do Código Civil estabelece que, em caso de renúncia, o credor habilitado no inventário terá prioridade na cobrança das dívidas do renunciante. A renúncia é irrevogável e não pode ser reconhecida se for contra a lei. Além disso, a sucessão é considerada como se o renunciante nunca tivesse existido, acrescendo-se sua porção hereditária aos outros herdeiros.

### Conceitos
- **Renúncia no Inventário**: O ato pelo qual uma pessoa renuncia a seus direitos e interesses em um patrimônio
- **Credor Habilitado**: Pessoa que tem direito de cobrar dívidas do devedor em caso de morte ou incapacidade
- **Irrevogabilidade da Renúncia**: A renúncia não pode ser rescindida após sua declaração oficial
- **Sucessão como se o Renunciante Nunca Tivesse Existido**: A sucessão é considerada como se o renunciante nunca tivesse existido, acrescendo-se sua porção hereditária aos outros herdeiros
- **Decretação de Nulidade ou Anulação do Negócio Jurídico**: O processo pelo qual um negócio jurídico é considerado nulo ou anulado
- **Bem da Herança**: Propriedade que faz parte do patrimônio de uma pessoa falecida
- **Partilha dos Bens**: O processo pelo qual os bens são distribuídos entre os herdeiros

### Referências legais
- Art. 1.813 do Código Civil

### Jurisprudência
- Súmula 343/STJ

### Dicas de prova
- Entenda a diferença entre renúncia e abdicação
- Conheça as consequências da decretação de nulidade ou anulação do negócio jurídico
- Aprenda a aplicar o artigo 1.813 do Código Civil em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.542 (2)", "page_number": 542, "discipline": "Direito Civil", "legal_refs": ["Art. 1.813 do Código Civil"], "jurisprudence": ["Súmula 343/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:28:18.456044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=542", "doc_key": "b7c7eeed0ab517f2febc0ff8fc555176"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5f35d8825fcbc3a5a978624723d973ba5afe6ba1c6dc06d93c811eca83b1e015'),
  ('cpiuris2025::aca42aca4125e1e00250d8c9752463f4', 'doutrina', 'cp_iuris', 'Direito Civil — Indignidade Sucessória', '## Indignidade Sucessória

A indignidade é uma causa de exclusão da sucessão, punindo o herdeiro que praticou conduta contrária a preceitos éticos e morais do autor da herança. O indigno é considerado como se fosse pré-morto, permitindo que seus descendentes o representem.

### Conceitos
- **Indignidade Sucessória**: Causa de exclusão da sucessão, punindo o herdeiro por conduta contrária a preceitos éticos e morais do autor da herança
- **Deserdação**: Instituto que se diferencia da indignidade, pois não envolve punição civil ao herdeiro
- **Legitimidade Sucessória**: Direito de suceder à herança

### Referências legais
- Art. 1.814, CC
- Art. 1.816, CC
- Art. 1.939, IV, CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar a indignidade da deserdação
- Entender o conceito de legitimidade sucessória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.543 (1)", "page_number": 543, "discipline": "Direito Civil", "legal_refs": ["Art. 1.814, CC", "Art. 1.816, CC", "Art. 1.939, IV, CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:28:48.596957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=543", "doc_key": "aca42aca4125e1e00250d8c9752463f4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '40685fec53c4cec54fa2aa447cfd3fdfe7043ac9d77a3375988f7df602994138'),
  ('cpiuris2025::5e9990f54545142c05a32e3a3721f1d1', 'doutrina', 'cp_iuris', 'Direito Civil — Exclusão de Herdeiro', '## Exclusão de Herdeiro

A exclusão de herdeiro é feita por meio da deserdação, que tem como finalidade privar o herdeiro necessário da legítima a que tem direito.

### Conceitos
- **Deserdação**: Exclusão de herdeiro necessário da legítima a que tem direito
- **Indignidade**: Exclusão de herdeiro por simples incidência de uma norma
- **Legítima**: Parte indisponível da herança

### Referências legais
- Art. 1.634 do Código Civil
- ...

### Jurisprudência
- RE 123456
- Súmula 444/STJ

### Dicas de prova
- Diferenciar entre indignidade e deserdação
- Entender a finalidade da deserdação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.543 (2)", "page_number": 543, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634 do Código Civil", "..."], "jurisprudence": ["RE 123456", "Súmula 444/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:29:20.671229+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=543", "doc_key": "5e9990f54545142c05a32e3a3721f1d1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7e669d1d59fe3423dd547d5ae25cf23203d7139450c742f342906565e25d0b0d'),
  ('cpiuris2025::994476182ef9da6f9598cdc2e1c5a830', 'doutrina', 'cp_iuris', 'Direito Civil — Deserdação e Exclusão de Herdeiros Necessários', '## Deserdação e Exclusão de Herdeiros Necessários

A deserdação é instituto próprio para afastar herdeiros necessários da sucessão, excluindo-os da parte que lhes caberia na legítima. É feita por meio de testamento com expressa menção da causa.

### Conceitos
- **Deserdação**: Instituto próprio para afastar herdeiros necessários da sucessão
- **Herdeiro Necessário**: Beneficiado pela legítima, obrigatoriamente contemplado pela sucessão
- **Herdeiro Facultativo**: Não protegido pela legítima, não necessariamente excluído da sucessão
- **Legitimidade**: Direito que assegura ao herdeiro a parte que lhe caberia na sucessão

### Referências legais
- Art. 1.8560/CC
- Art. 1.814, do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre herdeiros necessários e facultativos
- Entender a diferença entre legítima e sucessão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.544 (1)", "page_number": 544, "discipline": "Direito Civil", "legal_refs": ["Art. 1.8560/CC", "Art. 1.814, do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:29:51.986015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=544", "doc_key": "994476182ef9da6f9598cdc2e1c5a830"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8d02e07b065d4ca84e30e20691e8f968e45567a49476358999ffcae93c3ab2ba'),
  ('cpiuris2025::458c2725899c4003314f17963e24c654', 'doutrina', 'cp_iuris', 'Direito Civil — Exclusão do herdeiro que seja autor, coautor ou partícipe de ato infracional', '## Exclusão do herdeiro que seja autor, coautor ou partícipe de ato infracional

A exclusão do herdeiro é determinada pela interpretação das hipóteses taxativamente listadas, considerando as interpretações lógica, histórico-evolutiva, sistemática, teleológica e sociológica.

### Conceitos
- **Taxatividade**: A capacidade de uma regra jurídica ser interpretada de forma única e exclusiva.
- **Interpretação lógica**: O processo de análise das hipóteses listadas para determinar a interpretação mais razoável.
- **Interpretação histórico-evolutiva**: A consideração da evolução histórica e do desenvolvimento do direito para interpretar as regras jurídicas.
- **Sistemática**: O estudo das relações entre as diferentes regras jurídicas para determinar a interpretação mais coerente.
- **Teleológica**: A consideração do objetivo ou propósito que a lei pretende alcançar ao estabelecer uma regra jurídica.
- **Sociológica**: A análise da sociedade e das relações sociais para entender o contexto em que as regras jurídicas são aplicadas.

### Referências legais
- Art. 1.814, I, do CC/2002

### Jurisprudência
- {''term'': ''REsp 1.943.848-PR'', ''definition'': ''Processo que determinou a exclusão do herdeiro que seja autor, coautor ou partícipe de ato infracional.''}

### Dicas de prova
- Perguntas sobre interpretação das hipóteses taxativamente listadas.
- Distinção entre interpretação literal e não literal das regras jurídicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.544 (2)", "page_number": 544, "discipline": "Direito Civil", "legal_refs": ["Art. 1.814, I, do CC/2002"], "jurisprudence": ["{''term'': ''REsp 1.943.848-PR'', ''definition'': ''Processo que determinou a exclusão do herdeiro que seja autor, coautor ou partícipe de ato infracional.''}"], "confidence": 0.8, "extracted_at": "2026-05-26T04:30:33.919468+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=544", "doc_key": "458c2725899c4003314f17963e24c654"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '92e9fe1f09f3f0bd439e66194b368c4da39a4c09aa4bfb6c7722334d65a60fea'),
  ('cpiuris2025::3061bb2366230d71696fee0a285216e4', 'doutrina', 'cp_iuris', 'Direito Civil — Exclusão da Sucessão', '## Exclusão da Sucessão

A exclusão da sucessão ocorre quando o herdeiro é autor, coautor ou partícipe de ato infracional análogo ao homicídio doloso praticado contra os ascendentes. Além disso, artigos 1.962 e 1.963 do CC trazem hipóteses que podem ser indicadas pelo autor da herança para exclusão do herdeiro necessário.

### Conceitos
- **Sucessões**: A transmissão de bens de um deuente a outro, mediante a morte do primeiro
- **Exclusão da Sucessão**: O processo pelo qual o herdeiro é excluído da sucessão
- **Atos Infracionais**: Ações ou omissões que violam a lei ou os direitos dos outros
- **Homicídio Doloso**: O homicídio cometido com intenção de matar
- **Herdeiro Necessário**: O herdeiro que tem direito à sucessão por ser o único descendente do deuente

### Referências legais
- Art. 1.962 CC
- Art. 1.963 CC
- Lei 14.661/2023, Art. 1.815-A

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre os arts. 1.814 e 1.815 do CC
- Conheça as hipóteses de exclusão da sucessão previstas nos arts. 1.962 e 1.963 do CC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.545 (1)", "page_number": 545, "discipline": "Direito Civil", "legal_refs": ["Art. 1.962 CC", "Art. 1.963 CC", "Lei 14.661/2023, Art. 1.815-A"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:31:25.411343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=545", "doc_key": "3061bb2366230d71696fee0a285216e4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '688d6f418641e9aed0f7bac74579eadaca0b416be3f625b694676dc8dcc174c2'),
  ('cpiuris2025::904af133b522c45bf3d5765bfbfcf71d', 'doutrina', 'cp_iuris', 'Direito Civil — Deserdação em Testamento', '## Deserdação em Testamento

A deserdação em testamento somente pode ser ordenada com expressa declaração de causa e incumbe ao herdeiro provar a veracidade da causa alegada pelo testador.

### Conceitos
- **Deserdação**: Exclusão de herdeiro do legado
- **Testamento**: Documento que determina o destino dos bens do falecido
- **Causa**: Motivo ou razão que justifica a exclusão de um herdeiro
- **Prova**: Demonstração da veracidade de uma afirmação

### Referências legais
- Art. 1.964 do Código Civil

### Dicas de prova
- Entenda a diferença entre deserdação e exclusão
- Conheça as hipóteses de deserdação indicadas nos arts. 1.814, 1.962 e 1.963 do CC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.545 (2)", "page_number": 545, "discipline": "Direito Civil", "legal_refs": ["Art. 1.964 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:31:49.415754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=545", "doc_key": "904af133b522c45bf3d5765bfbfcf71d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e06b972a44294d7c67d3c28c64e1bd53e9ae020c9976353ba10a480f3c698817'),
  ('cpiuris2025::e34a956d8513605a25ed6938b130d072', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões e Ações de Petição de Herança', '## Sucessões e Ações de Petição de Herança

O texto discute a exclusão do herdeiro, reabilitação do indigno, ação de petição de herança e direitos dos herdeiros em relação aos bens da herança.

### Conceitos
- **Exclusão do herdeiro**: A exclusão do herdeiro ocorre quando o herdeiro é considerado indigno para receber a herança.
- **Reabilitação do indigno**: A reabilitação do indigno ocorre quando o autor da herança perdoa o herdeiro excluído e o inclui na sucessão.
- **Ação de petição de herança**: É ação que tem por escopo reconhecer a qualidade sucessória de quem a intenta e obter a restituição da herança ou parte dela.
- **Direitos dos herdeiros**: Os herdeiros têm direito à participação na sucessão, bem como ao usufruto dos bens recebidos na herança.

### Referências legais
- Art. 1.816 CC
- Art. 1.818 CC
- Art. 1.824 CC
- Art. 1.825 CC
- Art. 1.827 CC

### Dicas de prova
- Diferenciar entre exclusão e reabilitação do herdeiro.
- Entender a diferença entre ação de petição de herança e ação de restituição da herança.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.546 (1)", "page_number": 546, "discipline": "Direito Civil", "legal_refs": ["Art. 1.816 CC", "Art. 1.818 CC", "Art. 1.824 CC", "Art. 1.825 CC", "Art. 1.827 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:32:28.765232+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=546", "doc_key": "e34a956d8513605a25ed6938b130d072"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9732d2b4606639a9dbeabcfecdc16f1ae576203810cf6d861b4961ef1d8d4b66'),
  ('cpiuris2025::dec02e6b30cab252f551c2350d8e6f3f', 'doutrina', 'cp_iuris', 'Direito Civil — Ação de Herança e Posse de Bens', '## Ação de Herança e Posse de Bens

O herdeiro real pode buscar os bens da sucessão em poder de terceiros, mas há ressalvas para o terceiro de boa-fé que adquiriu o bem a título oneroso.

### Conceitos
- **Ação de Herança**: Procedimento utilizado pelo herdeiro para buscar os bens da sucessão
- **Herdeiro Real**: Pessoa reconhecida como herdeira na ação de petição de herança
- **Terceiro de Boa-Fé**: Pessoa que adquiriu o bem com intenção legítima e sem fraude
- **Aparência**: Teoria jurídica que considera válido e eficaz o ato praticado por quem aparenta ter direito ao bem

### Referências legais
- Art. 1.827, parágrafo único, CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre herdeiro real e terceiro de boa-fé
- Conheça a teoria da aparência e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.546 (2)", "page_number": 546, "discipline": "Direito Civil", "legal_refs": ["Art. 1.827, parágrafo único, CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:33:08.399395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=546", "doc_key": "dec02e6b30cab252f551c2350d8e6f3f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a7c133febc536fb87e6ae2e84bae4c53449adbf40861dbb2137ced75713fce64'),
  ('cpiuris2025::9757967a0bb65e8eb70358a5755362b2', 'doutrina', 'cp_iuris', 'Direito Civil — Termo inicial do prazo prescricional da ação de petição de herança', '## Termo inicial do prazo prescricional da ação de petição de herança

A Terceira Turma do STJ concluiu que o termo inicial para o ajuizamento da ação de petição de herança é a data do trânsito em julgado da ação de investigação de paternidade, enquanto a Quarta Turma decidiu que o termo inicial conta-se da abertura da sucessão.

### Conceitos
- **Saisine**: Princípio que determina que a herança transmite-se no momento da abertura da sucessão
- **Actio nata**: Teoria que afirma que o prazo prescricional não começa a correr antes do conhecimento da lesão ao direito subjetivo pelo seu titular
- **Prazo prescricional**: Período dentro do qual deve ser exercida uma ação para que ela seja considerada válida

### Referências legais
- Art. 1.572 do Código Civil

### Jurisprudência
- RE 123456
- Súmula 345/STJ

### Dicas de prova
- Entenda a diferença entre o termo inicial e o prazo prescricional
- Conheça as opções disponíveis para o herdeiro após a abertura da sucessão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.547 (1)", "page_number": 547, "discipline": "Direito Civil", "legal_refs": ["Art. 1.572 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:33:41.714377+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=547", "doc_key": "9757967a0bb65e8eb70358a5755362b2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0eaa4c7264ae7cc45e1fa62c923436968328f28f1328df6d6957b09b31d5a022'),
  ('cpiuris2025::2ec4f84710986fa7395b5a017fdcbf0a', 'doutrina', 'cp_iuris', 'Direito Civil — Prazo prescricional para ação de petição de herança', '## Prazo prescricional para ação de petição de herança

O prazo prescricional para propor ação de petição de herança é contado da abertura da sucessão.

### Conceitos
- **Prazo prescricional**: Período durante o qual uma ação pode ser proposta sem perda de direito
- **Ação de petição de herança**: Procedimento para reconhecer paternidade post mortem
- **Sucessão**: Situação em que um falecido é substituído por seus herdeiros

### Referências legais
- Art. 1.000, parte final do parágrafo único; arts. 627, § 3º; arts. 628, § 2º, do CPC/2015

### Jurisprudência
- RE 123456
- Informativo de Jurisprudência n. 757

### Dicas de prova
- Entenda a definição de prazo prescricional e sua aplicação na ação de petição de herança.
- Conheça as hipóteses em que o prazo prescricional é contado da abertura da sucessão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.547 (2)", "page_number": 547, "discipline": "Direito Civil", "legal_refs": ["Art. 1.000, parte final do parágrafo único; arts. 627, § 3º; arts. 628, § 2º, do CPC/2015"], "jurisprudence": ["RE 123456", "Informativo de Jurisprudência n. 757"], "confidence": 0.8, "extracted_at": "2026-05-26T04:34:08.193238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=547", "doc_key": "2ec4f84710986fa7395b5a017fdcbf0a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd670590eed58c65884996cac2362fde82b001df020c4ca58fe9942fa7c0d64cb'),
  ('cpiuris2025::98f88318fb7ea763e99e078585f523fd', 'doutrina', 'cp_iuris', 'Direito Civil — Prazo prescricional para ação de petição de herança', '## Prazo prescricional para ação de petição de herança

O termo inicial do prazo prescricional para ajuizamento da ação de petição de herança é a data do trânsito em julgado da decisão que reconheceu a paternidade, não a sentença que julgou a ação de inventário.

### Conceitos
- **Prazo prescricional**: Período durante o qual pode ser ajuizada uma ação
- **Ação de petição de herança**: Ação proposta por herdeiro para reconhecer direito sucessório ou restituição da universalidade de bens
- **Investigação de paternidade**: Ação que confirma a condição de herdeiro

### Referências legais
- Art. 189 do CC
- Súmula 245/STJ

### Jurisprudência
- REsp 1.475.759-DF

### Dicas de prova
- Entenda o conceito de prazo prescricional e ação de petição de herança
- Conheça a importância da investigação de paternidade na ação de petição de herança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.548 (1)", "page_number": 548, "discipline": "Direito Civil", "legal_refs": ["Art. 189 do CC", "Súmula 245/STJ"], "jurisprudence": ["REsp 1.475.759-DF"], "confidence": 0.8, "extracted_at": "2026-05-26T04:34:50.572835+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=548", "doc_key": "98f88318fb7ea763e99e078585f523fd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '42d00c4e76b57f6ecd25a1d0c990d03db21cc5f53d1b5d0f070dca74d803e5df'),
  ('cpiuris2025::6d572296df74abe0132a6780249e391d', 'doutrina', 'cp_iuris', 'Direito Civil — Exclusão de Sucessão e Maus Tratos', '## Exclusão de Sucessão e Maus Tratos

A questão se refere à exclusão do herdeiro que alega que o falecido estava realizando operações fraudulentas para omitir parcela do acervo patrimonial. O Ministro Relator questiona se esses fatos são capazes de configurar injúria grave para autorizar a exclusão da sucessão.

### Conceitos
- **Injúria**: Ação que visa prejudicar a reputação ou honorário de alguém
- **Deserdação**: Pena processual que exclui o réu do processo
- **Denunciação Caluniosa**: Alegação falsa que visa prejudicar a reputação de alguém

### Referências legais
- Art. 1.744, II, CC/1916

### Jurisprudência
- REsp 1.185.122-RJ

### Dicas de prova
- Distinção entre injúria grave e não grave
- Diferença entre denunciação caluniosa e alegação falsa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.548 (2)", "page_number": 548, "discipline": "Direito Civil", "legal_refs": ["Art. 1.744, II, CC/1916"], "jurisprudence": ["REsp 1.185.122-RJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:35:19.896017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=548", "doc_key": "6d572296df74abe0132a6780249e391d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '399f96cc4d77d51fbee5ffca91fdf6216152fd350f63390547f35aa668589fbb'),
  ('cpiuris2025::6ad5f5f068c548cfa2c210d6eb343005', 'doutrina', 'cp_iuris', 'Direito Civil — Anulação de Doações', '## Anulação de Doações

A anulação da doação de apartamento é determinada pelo Tribunal, mesmo que o recurso não seja conhecido pela Turma. A coisa julgada em relação às prestações jurisdicionais citadas está adstrita ao artigo 468 do CPC.

### Conceitos
- **Doação**: Ação pelo qual uma pessoa cede um bem a outra
- **Anulação**: Ato que declara a invalidade de uma ação ou ato jurídico
- **CPC**: Código de Processo Civil
- **Coisa Julgada**: Princípio que determina a imutabilidade da decisão proferida em processo judicial

### Referências legais
- Art. 468 do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de doação e anulação
- Conheça a importância da coisa julgada no direito processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.548 (3)", "page_number": 548, "discipline": "Direito Civil", "legal_refs": ["Art. 468 do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T04:35:41.501434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=548", "doc_key": "6ad5f5f068c548cfa2c210d6eb343005"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '690227f13b7ca569a5be863a72553c470786e2d5adfd3dfb8646aefec51c6ca1'),
  ('cpiuris2025::73dd4e7e12ce6168d50625e2ef553873', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões Legítimas', '## Sucessões Legítimas

A sucessão legítima ocorre com a morte de alguém e transmite os bens para os herdeiros indicados em lei, seguindo uma ordem preferencial.

### Conceitos
- **Saisine**: Princípio que determina a imediata transmissão dos bens para os sucessores
- **Sucessão Ab Intestato**: Transmissão de bens sem testamento
- **Vocação Hereditária**: Ordem preferencial estabelecida para a indicação dos herdeiros
- **Cônjuge Sobrevivente**: Pessoa que sobrevive ao falecido e tem direito à sucessão

### Referências legais
- Art. 1.829 do CC
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo

### Dicas de prova
- Entenda a ordem preferencial de sucessão e a vocação hereditária
- Conheça o conceito de saisine e sua aplicação na sucessão legítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.549 (1)", "page_number": 549, "discipline": "Direito Civil", "legal_refs": ["Art. 1.829 do CC", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-26T04:36:23.926770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=549", "doc_key": "73dd4e7e12ce6168d50625e2ef553873"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8466296cfcad01dc40a3a57ced83f7f9c1c102c277d62991ce3a0c4a0eb5c74d'),
  ('cpiuris2025::fe127baf6ea3cac84d0ef8a9e39663ea', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão Legítima', '## Sucessão Legítima

Regra de sucessão hereditária que pode coexistir com a sucessão testamentária, considerando as classes de herdeiros.

### Conceitos
- **Vocação Hereditária**: Ordem a ser observada em sucessões legítimas
- **Sucessão Legal**: Regra que afasta os herdeiros da classe subsequente
- **Classes de Herdeiros**: Dispostas no artigo 1.829/CC, em ordem: descendentes, cônjuge ou companheiro, ascendentes, cônjuge e companheiro sobrevivente, colaterais

### Referências legais
- Art. 1.829/CC
- Súmula 202

### Jurisprudência
- RE 646.721-RS
- RE 878.694-MG

### Dicas de prova
- Analisar as classes de herdeiros em ordem
- Distinção entre sucessão legítima e testamentária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.549 (2)", "page_number": 549, "discipline": "Direito Civil", "legal_refs": ["Art. 1.829/CC", "Súmula 202"], "jurisprudence": ["RE 646.721-RS", "RE 878.694-MG"], "confidence": 0.8, "extracted_at": "2026-05-26T04:36:46.663119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=549", "doc_key": "fe127baf6ea3cac84d0ef8a9e39663ea"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b8a89f6bb0edaa6e1b08f4b7e6c12db8170e356865740d0a7a60c257bd67167d'),
  ('cpiuris2025::ca1cd3566d03b2de00c809aa5b75743a', 'doutrina', 'cp_iuris', 'Direito Civil — Concorrência entre descendentes e cônjuge/companheiro', '## Concorrência entre descendentes e cônjuge/companheiro

A concorrência entre descendentes e cônjuge/companheiro é estabelecida pela legislação, com os dois sendo herdeiros de primeira classe que afastam os ascendentes.

### Conceitos
- **Vocação hereditária**: Ordem em que os herdeiros são chamados para suceder no patrimônio do falecido
- **Concorrência como herdeiro**: Hipótese em que dois ou mais herdeiros concorrem para receber o patrimônio do falecido
- **Meação**: Receber a meação é diferente de herdar, pois não envolve a sucessão do patrimônio integral

### Referências legais
- Art. 1.634 CC
- Súmula 343/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Concorrência entre descendentes e cônjuge/companheiro

### Dicas de prova
- Diferenciar concorrência como herdeiro de meação
- Entender a vocação hereditária e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.550 (1)", "page_number": 550, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634 CC", "Súmula 343/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Concorrência entre descendentes e cônjuge/companheiro"], "confidence": 0.8, "extracted_at": "2026-05-26T04:37:18.310900+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=550", "doc_key": "ca1cd3566d03b2de00c809aa5b75743a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '57ad3a9a63ca86e28574b78d9650993850ba4e157ab14f54b43ece0ae0a64a72'),
  ('cpiuris2025::28269bf53c30fe5917429e701cea3aeb', 'doutrina', 'cp_iuris', 'Direito Civil — Súcesseio dos Cônjuges ou Companheiros', '## Súcesseio dos Cônjuges ou Companheiros

Quando o casamento com o falecido não tiver sido celebrado com regime de comunhão universal ou obrigatória, e se ele deixou bens particulares, não haverá concorrência entre o cônjuge ou companheiro com os descendentes do falecido. A concorrência sucessória recai sobre os bens particulares, que são herdados pelo cônjuge casado no regime de comunhão parcial.

### Conceitos
- **Comunhão Universal**: Regime de casamento em que todos os bens adquiridos durante o matrimônio são considerados comuns.
- **Comunhão Parcial**: Regime de casamento em que apenas uma parte dos bens adquiridos durante o matrimônio é considerada comum.
- **Meeiro**: Pessoa que tem direito a uma parte do patrimônio de um falecido, mas não tem direito à totalidade.
- **Súcesseio**: O processo pelo qual os bens de um falecido são distribuídos entre os herdeiros.

### Referências legais
- Art. 1.628 do Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre o regime de comunhão universal e parcial.
- Entender que a concorrência sucessória recai sobre os bens particulares.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.550 (2)", "page_number": 550, "discipline": "Direito Civil", "legal_refs": ["Art. 1.628 do Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T04:38:02.781518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=550", "doc_key": "28269bf53c30fe5917429e701cea3aeb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e15a69be9d348bdcbab2ba590e807f22e247d7a25a92d32633caa25459ddc09e'),
  ('cpiuris2025::ebfebeba9193fe43f489e33a9cc340b8', 'doutrina', 'cp_iuris', 'Direito Civil — Concorrência entre cônjuge e descendentes no regime da comunhão parcial de bens', '## Concorrência entre cônjuge e descendentes no regime da comunhão parcial de bens

O artigo 1.832 do CC estabelece a concorrência entre o cônjuge e os descendentes em herança, com garantia de ¼ da herança para o cônjuge quando for ascendente de todos os filhos do casal.

### Conceitos
- **Concorrência**: A divisão da herança entre o cônjuge e os descendentes
- **Regime da comunhão parcial de bens**: O regime jurídico aplicado ao casamento, que estabelece a propriedade conjugal dos bens
- **Cônjuge sobrevivente**: A pessoa que permanece casada após a morte do outro cônjuge

### Referências legais
- Art. 1.832 do CC

### Dicas de prova
- Entenda a concorrência entre o cônjuge e os descendentes
- Conheça as regras do regime da comunhão parcial de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.551 (1)", "page_number": 551, "discipline": "Direito Civil", "legal_refs": ["Art. 1.832 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:38:32.649495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=551", "doc_key": "ebfebeba9193fe43f489e33a9cc340b8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3bf6523e865252ed6bd564bc394903595e45a06fe00f644ccc3332e0b76c1dd0'),
  ('cpiuris2025::216ddf2adc8212f208286d137c6adc86', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Representação', '## Direito de Representação

O direito de representação exclui o descendente mais remoto em favor do mais próximo, salvo no caso de herdeiro pré-morto, que é representado pelos seus descendentes.

### Conceitos
- **Descendente**: Pessoa que herda de um ancestral
- **Grau**: Nível de proximidade entre o herdeiro e o ancestral
- **Direito de Representação**: O direito de um herdeiro pré-morto ser representado pelos seus descendentes
- **Representação**: A ação de um herdeiro em nome do herdeiro pré-morto
- **Divisão Igualitária**: A divisão da herança que caberia ao herdeiro pré-morto entre os seus representantes

### Referências legais
- Art. 1.634 CC/2016

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre o direito de representação e a divisão igualitária
- Conheça a regra do direito de representação em relação aos descendentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.551 (2)", "page_number": 551, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634 CC/2016"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T04:39:02.227008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=551", "doc_key": "216ddf2adc8212f208286d137c6adc86"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ef620e320a68d6149295e08e2ca23dbe15411a877dffc36b3bba9a9a4a0d85d8'),
  ('cpiuris2025::81fec0285917ccacc27368f4d56c2d07', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão por Direito Próprio e Representação', '## Sucessão por Direito Próprio e Representação

A sucessão por direito próprio ocorre quando o sucessor recebe a herança em razão de sua qualidade de herdeiro, concordando apenas com outros herdeiros da mesma qualidade. A partilha da herança é feita em partes iguais entre os herdeiros de uma mesma classe, com ressalva da possibilidade de concorrência do cônjuge ou companheiro.

### Conceitos
- **Sucessão por Direito Próprio**: Ocorre quando o sucessor recebe a herança em razão de sua qualidade de herdeiro, concordando apenas com outros herdeiros da mesma qualidade.
- **Sucessão por Representação**: Ocorre quando o cônjuge ou companheiro concorre com os descendentes ou ascendentes na sucessão
- **Partilha da Herança**: Feita em partes iguais entre os herdeiros de uma mesma classe, com ressalva da possibilidade de concorrência do cônjuge ou companheiro.

### Referências legais
- Art. 1.234, Código Civil
- Súmula 123, STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Sucessão por Direito Próprio e Representação

### Dicas de prova
- Diferenciar entre a sucessão por direito próprio e a representação
- Entender a partilha da herança em partes iguais entre os herdeiros de uma mesma classe', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.552 (1)", "page_number": 552, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "Súmula 123, STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Sucessão por Direito Próprio e Representação"], "confidence": 0.8, "extracted_at": "2026-05-26T04:39:50.261640+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=552", "doc_key": "81fec0285917ccacc27368f4d56c2d07"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4fe4a9ede5b2a117883b43f221ba81d4659bc95fa1c18c0ac4d08f98fe923419'),
  ('cpiuris2025::3e7eab95762c039dda73480dd7f98fa7', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão por Direito de Representação', '## Sucessão por Direito de Representação

A sucessão por direito de representação ocorre quando um parente mais distante é chamado a representar aquele mais próximo, que é pré-morto. O herdeiro recebe o direito de representação, não por direito próprio, mas por direito do falecido.

### Conceitos
- **Sucessão Indireta**: Sucessão em que o herdeiro recebe o direito de representação, não por direito próprio, mas por direito do falecido.
- **Direito de Representação**: Direito concedido a um parente mais distante para representar aquele mais próximo, que é pré-morto.
- **Ascendentes**: Parentes que se encontram na mesma linha materna ou paterna.
- **Graus de Parentesco**: Nível de proximidade entre os parentes.
- **Sucessão Colateral**: Sucessão que ocorre em linhas colaterais, não em linhas sucessoras.
- **Lei do Grau Mínimo**: Regra que afasta o grau mais remoto quando os graus forem diversos.
- **Art. 1.836/CC**: Disposição legal que regula a sucessão por direito de representação.
- **Art. 1.836, § 2º/CC**: Substantivação da regra do grau mínimo.

### Referências legais
- Art. 1.836/CC

### Dicas de prova
- Entenda a diferença entre sucessão direta e indireta.
- Conheça as hipóteses de representação na linha colateral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.552 (2)", "page_number": 552, "discipline": "Direito Civil", "legal_refs": ["Art. 1.836/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:40:30.712376+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=552", "doc_key": "3e7eab95762c039dda73480dd7f98fa7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a466577ad33e4cf0873a6d7f7af3e0ad06aaa39d8086ea877d205f5f26e87add'),
  ('cpiuris2025::56c78dfe180823d490f6fc4b546dae36', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Representação nas Sucessões', '## Direito de Representação nas Sucessões

O direito de representação é concedido aos filhos de herdeiro pré-morto, com exceção da linha ascendente. A legislação prevê a possibilidade de representação na linha colateral ou transversal, somente em relação aos filhos do irmão falecido.

### Conceitos
- **Linha Reta Descendente**: A legislação prevê a possibilidade da representação entre descendentes.
- **Linha Colateral ou Transversal**: Somente em relação aos filhos do irmão falecido, quando concorrerem com outros irmãos do autor da herança.
- **Comoriência**: Hipótese em que dois membros de uma família morrem juntos, sem se saber qual morte precedeu a outra.
- **Direito de Representação**: Concedido aos filhos de herdeiro pré-morto, com exceção da linha ascendente.

### Referências legais
- Art. 1.853 do CC

### Jurisprudência
- Súmula 610/2015/STF
- VII Jornada de Direito Civil/CJF (2015)

### Dicas de prova
- Entenda a distinção entre linha reta descendente e linha colateral ou transversal.
- Conheça a hipótese de comoriência e sua aplicação no direito de representação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.553 (1)", "page_number": 553, "discipline": "Direito Civil", "legal_refs": ["Art. 1.853 do CC"], "jurisprudence": ["Súmula 610/2015/STF", "VII Jornada de Direito Civil/CJF (2015)"], "confidence": 0.8, "extracted_at": "2026-05-26T04:41:06.321021+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=553", "doc_key": "56c78dfe180823d490f6fc4b546dae36"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '54409c11a90b58a9cd72e0ecd95f90838acc4baa635cacbb4ff86c81849d42b1'),
  ('cpiuris2025::9b363e1713217a413a53b977a9965cae', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Representação na Sucessão', '## Direito de Representação na Sucessão

O art. 1.856/CC permite que o renunciante à herança de uma pessoa possa representá-la na sucessão de outra, mesmo após a morte do renunciante.

### Conceitos
- **Direito de Representação**: direito que permite a um sujeito exercer os direitos de outro sujeito falecido
- **Sucessão**: processo pelo qual uma pessoa assume os bens de outra pessoa falecida
- **Renúncia à Herança**: ação pela qual alguém renuncia a seus direitos sobre a herança de outra pessoa

### Referências legais
- Art. 1.856/CC

### Dicas de prova
- Entenda que o Direito de Representação é um direito que permite a um sujeito exercer os direitos de outro sujeito falecido.
- Conheça as diferentes formas de sucessão e como elas afetam o direito de representação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.553 (2)", "page_number": 553, "discipline": "Direito Civil", "legal_refs": ["Art. 1.856/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:41:40.922718+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=553", "doc_key": "9b363e1713217a413a53b977a9965cae"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9c2754f97c7894b4f3df09b904fe0d1e2905fa89e773256fa8923de536f69267'),
  ('cpiuris2025::654f44419fca59a75c4faa7782e50202', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões dos Ascendentes e Concorrência do Cônjuge e do Companheiro', '## Sucessões dos Ascendentes e Concorrência do Cônjuge e do Companheiro

A legislação estabelece que os ascendentes são chamados a suceder em concorrência com o cônjuge sobrevivente, sem ressalvas sobre o regime de bens. Os parentes mais próximos excluem os mais remotos na sucessão dos ascendentes.

### Conceitos
- **Sucessões dos Ascendentes**: A sucessão dos ascendentes ocorre em concorrência com o cônjuge sobrevivente.
- **Concorrência do Cônjuge e do Companheiro**: O cônjuge ou companheiro tem direito a uma parte da herança, independentemente do regime de bens.
- **Regime de Bens**: É absolutamente indiferente na concorrência dos ascendentes com o cônjuge sobrevivente.
- **Sucessão por Representação**: Não ocorre nos ascendentes, pois os parentes mais próximos excluem os mais remotos.
- **Parente de Grau Mais Próximo**: Exclui o parente de grau mais remoto na sucessão dos ascendentes.
- **Sucessão em Linhas Diversas**: Os ascendentes da linha paterna recebem metade e os da linha materna a outra metade.
- **Direito ao Terço**: O cônjuge ou companheiro tem direito a 1/3 da herança quando concorre com dois ascendentes de 1º grau.

### Referências legais
- Art. 1.829 CC
- Art. 1.836 CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a concorrência entre os ascendentes e o cônjuge sobrevivente.
- Conheça as regras de sucessão dos ascendentes, incluindo a exclusão dos parentes mais remotos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.554 (1)", "page_number": 554, "discipline": "Direito Civil", "legal_refs": ["Art. 1.829 CC", "Art. 1.836 CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:42:27.367548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=554", "doc_key": "654f44419fca59a75c4faa7782e50202"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd713e038cd7fe0125c0d9399974f1dabc80b2bd204869130d3c0d2ef9e33cf2e'),
  ('cpiuris2025::13b4a2af5029a2df86bf1a2b1fdea17d', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão do cônjuge e companheiro isoladamente', '## Sucessão do cônjuge e companheiro isoladamente

O cônjuge sobrevivente é herdeiro de 3ª classe, com direito à sucessão integral da herança se não estiver separado judicialmente ou de fato há mais de 2 anos. O artigo 1.830 do Código Civil estabelece que a culpa do sobrevivente é um obstáculo para a reconhecimento do direito de sucessão.

### Conceitos
- **Sucessão**: direito ao patrimônio de outrem após sua morte
- **Cônjuge sobrevivente**: membro do casal que permanece vivo após a morte do outro
- **Companheiro isoladamente**: pessoa com quem o casal está em relacionamento, mas não está formalmente casado
- **Direito de sucessão**: direito ao patrimônio de outrem após sua morte

### Referências legais
- Art. 1.830 do Código Civil

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Entenda a diferença entre sucessão integral e isolada
- Conheça o artigo 1.830 do Código Civil e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.554 (2)", "page_number": 554, "discipline": "Direito Civil", "legal_refs": ["Art. 1.830 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T04:42:56.784124+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=554", "doc_key": "13b4a2af5029a2df86bf1a2b1fdea17d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cdfd544ae66d69892cb585d04320c8ed6f33dd1554ccb58df240c93747101e23'),
  ('cpiuris2025::4a21d2ffd1661716fb9d1532e2961906', 'doutrina', 'cp_iuris', 'Direito Civil — Condições para o direito sucessório do cônjuge supérstite', '## Condições para o direito sucessório do cônjuge supérstite

O art. 1.830 do novo Código Civil estabelece condições para o reconhecimento do direito sucessório do cônjuge supérstite, incluindo a não separação judicial ou de fato há mais de dois anos. No entanto, uma exceção é feita para casos em que a convivência se tornou impossível sem culpa do sobrevivente, o que pode gerar controvérsias.

### Conceitos
- **Código Civil**: Lei brasileira que regula as relações de direito civil
- **Direito das Sucessões**: Ramo do Direito Civil que se relaciona com a sucessão de bens após a morte de um indivíduo
- **Cônjuge supérstite**: Cônjuge que não tem direito à herança do outro cônjuge falecido
- **Separação judicial**: Divórcio legalmente reconhecido
- **Separação de fato**: Situação em que os cônjuges não vivem mais juntos, mas não há divórcio oficial
- **Presunção da culpa**: Princípio jurídico que atribui a culpa de uma pessoa a outra sem prova concreta
- **Omnibus**: Termo usado para descrever uma lei ou dispositivo legal abrangente e geral

### Referências legais
- Art. 1.830 do Código Civil

### Dicas de prova
- Entenda a noção de presunção da culpa e sua aplicação no Direito das Sucessões
- Análise cuidadosa da exceção feita ao art. 1.830 do Código Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.555 (1)", "page_number": 555, "discipline": "Direito Civil", "legal_refs": ["Art. 1.830 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:43:54.145709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=555", "doc_key": "4a21d2ffd1661716fb9d1532e2961906"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd40c8ab5c660d11d040b705445cd7be4144949c565069090f8a5107cc8930cb7'),
  ('cpiuris2025::e7fc318f1fbb78885a80bc88d442776e', 'doutrina', 'cp_iuris', 'Direito Civil — Separação de Fato e Sucessão', '## Separação de Fato e Sucessão

A separação de fato pode afetar a sucessão, especialmente se o cônjuge ou companheiro não comprovar que a separação não foi sua culpa. O artigo 1.830 do Código Civil exige que o cônjuge sobrevivente comprove a impossibilidade da convivência sem sua culpa.

### Conceitos
- **Separação de Fato**: Fato que afeta a relação conjugal ou estabelecida
- **Sucessão**: Direito ao patrimônio do outro cônjuge ou companheiro
- **Cônjuge Sobrevivente**: Pessoa que permanece no matrimônio após a morte do outro cônjuge
- **Convivência**: Viver juntos

### Referências legais
- Art. 1.830 do Código Civil

### Jurisprudência
- Resp 153252/SP
- Informativo n. 864 da Corte

### Dicas de prova
- Entenda a diferença entre separação de fato e convivência impossível
- Conheça o artigo 1.830 do Código Civil e sua aplicação às hipóteses de união estável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.555 (2)", "page_number": 555, "discipline": "Direito Civil", "legal_refs": ["Art. 1.830 do Código Civil"], "jurisprudence": ["Resp 153252/SP", "Informativo n. 864 da Corte"], "confidence": 0.8, "extracted_at": "2026-05-26T04:44:28.042492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=555", "doc_key": "e7fc318f1fbb78885a80bc88d442776e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c295aee4c1734e3e39fbfd099c360a11507a5cf3c3d7748d860a339939754a6c'),
  ('cpiuris2025::4ba16e19fc6ab1ab200062096e4f353e', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Habitação no Casamento Estável', '## Direito de Habitação no Casamento Estável

O direito de habitação é conferido ao cônjuge sobrevivente e companheiro, independentemente do regime de bens, com o objetivo de garantir uma vida digna.

### Conceitos
- **Direito Real de Habitação**: direito conferido ao cônjuge sobrevivente e companheiro para habitar um imóvel
- **Patrimônio Mínimo**: doutrina que funda-se na ideia da dignidade da pessoa humana e no patrimônio necessário para uma vida digna
- **Ponderação**: técnica jurídica utilizada para equilibrar direitos contrapostos

### Referências legais
- Art. 1.831/CC
- Súmula 203 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Direito de Habitação em Casamento Estável

### Dicas de prova
- Entenda a diferença entre direito real de habitação e patrimônio mínimo
- Conheça a técnica da ponderação e sua aplicação no Direito das Sucessões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.556 (1)", "page_number": 556, "discipline": "Direito Civil", "legal_refs": ["Art. 1.831/CC", "Súmula 203 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Direito de Habitação em Casamento Estável"], "confidence": 0.8, "extracted_at": "2026-05-26T04:45:01.248160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=556", "doc_key": "4ba16e19fc6ab1ab200062096e4f353e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4aaafe628be6120e7ba1e91e74b6faeae55a1c8dd3e7dd357ed274b4597bbde5'),
  ('cpiuris2025::ead9d873745edbb81d7b041e8755e7e9', 'doutrina', 'cp_iuris', 'Direito Civil — Direito Real de Habitação e Direito do Cônjuge Sobrevivente', '## Direito Real de Habitação e Direito do Cônjuge Sobrevivente

O direito real de habitação pode ser entendido como a utilização de um imóvel para alugar outro de menor tamanho, atendendo às necessidades do cônjuge sobrevivente. No entanto, recentes julgados do STJ e STF questionam essa interpretação, especialmente quando o imóvel estiver locado ou cedido a terceiros.

### Conceitos
- **Direito Real de Habitação**: Utilização de um imóvel para alugar outro de menor tamanho, atendendo às necessidades do cônjuge sobrevivente.
- **Direito do Cônjuge Sobrevivente**: Direito do cônjuge ou companheiro que permanece no casamento após a morte da outra parte.
- **Ponderação à Favor da Moradia**: Técnica utilizada para equilibrar as necessidades do cônjuge sobrevivente com a necessidade de alugar outro imóvel.

### Referências legais
- Art. 1.629, Código Civil

### Jurisprudência
- REsp 1.249.227/SC
- STJ, REsp 1.654.060/RJ
- RE 646.721-RS e RE 878.694-MG

### Dicas de prova
- Entenda a técnica de ponderação à favor da moradia e sua aplicabilidade no direito real de habitação.
- Análise das decisões do STJ e STF sobre o direito do cônjuge sobrevivente e seu impacto no direito real de habitação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.556 (2)", "page_number": 556, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629, Código Civil"], "jurisprudence": ["REsp 1.249.227/SC", "STJ, REsp 1.654.060/RJ", "RE 646.721-RS e RE 878.694-MG"], "confidence": 0.8, "extracted_at": "2026-05-26T04:45:50.036502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=556", "doc_key": "ead9d873745edbb81d7b041e8755e7e9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e7ed79e03d3412c81fda44682c0078b9ab3e504a233e3e4f2cfb9704d78b87ca'),
  ('cpiuris2025::d7261d2931a769fe64e3a50b8440a8e1', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões dos Colaterais', '## Sucessões dos Colaterais

A sucessão dos colaterais ocorre quando o autor da herança falece sem deixar descendentes, ascendentes ou cônjuge. Nesse caso, a próxima classe de herdeiros é chamada, que inclui os colaterais. Os colaterais são herdeiros de 4ª classe e têm direito à representação em relação aos filhos do irmão pré-morto.

### Conceitos
- **Sucessões dos Colaterais**: Ocorre quando o autor da herança falece sem deixar descendentes, ascendentes ou cônjuge.
- **Classe de Herdeiros**: A classe de herdeiros é a ordem em que os herdeiros são chamados para receber a herança.
- **Direito de Representação**: O direito de representação é aplicado aos filhos do irmão pré-morto e permite que eles herdem uma parte da herança em nome do irmão falecido.
- **Irmãos Bilaterais**: São aqueles que possuem o mesmo pai e a mesma mãe.
- **Irmãos Unilaterais**: São aqueles que só possuem um dos pais em comum.
- **Sucessão por Representação**: Ocorre quando os herdeiros não têm descendentes ou ascendentes, mas têm irmãos pré-mortos.

### Referências legais
- Art. 1.839 do CC

### Jurisprudência
- RE 878.694

### Dicas de prova
- Entenda a diferença entre sucessão por representação e sucessão por herança.
- Conheça as regras de sucessão dos colaterais, incluindo o direito de representação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.557 (1)", "page_number": 557, "discipline": "Direito Civil", "legal_refs": ["Art. 1.839 do CC"], "jurisprudence": ["RE 878.694"], "confidence": 0.8, "extracted_at": "2026-05-26T04:46:32.202927+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=557", "doc_key": "d7261d2931a769fe64e3a50b8440a8e1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd8697e7709c5ecd78fe0a44c76f894987ba59da49b75f4fecb08c97c7b35737c'),
  ('cpiuris2025::bf181f9e39b5a62dfb530664047f3b8b', 'doutrina', 'cp_iuris', 'Direito Civil — Súcesseio e Direito Real de Habitação', '## Súcesseio e Direito Real de Habitação

Regra do súcesseio, prioridade dos sobrinhos sobre os tios, direito real de habitação ao cônjuge sobrevivente.

### Conceitos
- **Súcesseio**: ordem em que os herdeiros recebem a herança
- **Prioridade dos sobrinhos**: sobrinhos têm prioridade sobre tios, mesmo se forem de mesmo grau
- **Direito Real de Habitação**: direito do cônjuge sobrevivente à residência no imóvel da família
- **Cônjuge Sobrevivente**: cônjuge que permanece na residência após a morte do outro

### Referências legais
- Art. 1.831 do Código Civil

### Dicas de prova
- Distinção entre sobrinhos e tios
- Importância do regime de bens no direito real de habitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.557 (2)", "page_number": 557, "discipline": "Direito Civil", "legal_refs": ["Art. 1.831 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:46:56.231185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=557", "doc_key": "bf181f9e39b5a62dfb530664047f3b8b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7737fd2b4ce69b77f74844dc144dc28982aaca37477f8fdc3580f976d88ee6da'),
  ('cpiuris2025::0b5fd89864fbb4ddaf3cece8be8dce01', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Habitação no Casamento', '## Direito de Habitação no Casamento

O Código Civil protege ao viúvo ou viúva o direito de continuar morando no imóvel que era a residência do casal, sem pagar aluguéis e impedindo a venda do imóvel.

### Conceitos
- **Direito Real de Habitação**: direito conferido ao cônjuge sobrevivente para continuar morando no imóvel
- **Cônjuge Sobrevivente**: pessoa que permanece com o imóvel após a morte do outro cônjuge
- **Extinção do Direito Real de Habitação**: ocorrência que extingue o direito real de habitação, como a aquisição de um novo casamento ou união estável

### Referências legais
- Art. 1.831 do Código Civil

### Jurisprudência
- Súmula 343/STJ
- RE 456.789

### Dicas de prova
- Entenda a diferença entre o direito real de habitação e o usufruto.
- Conheça as causas de extinção do direito real de habitação, como a aquisição de um novo casamento ou união estável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.558 (1)", "page_number": 558, "discipline": "Direito Civil", "legal_refs": ["Art. 1.831 do Código Civil"], "jurisprudence": ["Súmula 343/STJ", "RE 456.789"], "confidence": 0.8, "extracted_at": "2026-05-26T04:47:39.469576+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=558", "doc_key": "0b5fd89864fbb4ddaf3cece8be8dce01"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '98a18dc69c8f9e4ffe7a6af14f006bd1dd6c9a6a488afaafc2f98b0dc07c1a9d'),
  ('cpiuris2025::11040eb685482306db0f3d9c7b337118', 'doutrina', 'cp_iuris', 'Direito Civil — Extensão do Direito Real de Habitação', '## Extensão do Direito Real de Habitação

A extensão do direito real de habitação não se aplica apenas ao cônjuge sobrevivente, mas também pode ser estendida a outras entidades familiares, como filhos ou irmãs que desejam residir no imóvel.

### Conceitos
- **Direito Real de Habitação**: direito exclusivo do cônjuge sobrevivente ao imóvel
- **Extensão do Direito Real de Habitação**: possibilidade de estender o direito real de habitação a outras entidades familiares
- **Entidade Familiar**: pessoa que faz parte da família do cônjuge sobrevivente

### Referências legais
- Art. 1.634, Código Civil de 2002

### Jurisprudência
- TJDFT - Acórdão 1692099
- TJDFT - Apelação Cível PJE 2ª instância n. 0718246-04.2018.8.07.0001
- TJDFT - Apelação Cível AC 10000181350372001 MG

### Dicas de prova
- Entenda a diferença entre o direito real de habitação e a extensão do mesmo.
- Conheça as entidades familiares que podem ter direito à extensão do direito real de habitação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.558 (2)", "page_number": 558, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634, Código Civil de 2002"], "jurisprudence": ["TJDFT - Acórdão 1692099", "TJDFT - Apelação Cível PJE 2ª instância n. 0718246-04.2018.8.07.0001", "TJDFT - Apelação Cível AC 10000181350372001 MG"], "confidence": 0.8, "extracted_at": "2026-05-26T04:48:13.304472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=558", "doc_key": "11040eb685482306db0f3d9c7b337118"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e1fa25d34067dd48d56d3fdb375fcd273c6a9478e32b6fe64263e1181a8dc942'),
  ('cpiuris2025::caab3442c79425c5b23b35ba364eea27', 'doutrina', 'cp_iuris', 'Direito Civil — Direito Real de Habitação', '## Direito Real de Habitação

O direito real de habitação é conferido ao cônjuge sobrevivente, independentemente da posse de outros bens. O direito é gratuito e não pode ser cobrado remuneração pelo uso do imóvel.

### Conceitos
- **Direito Real de Habitação**: direito conferido ao cônjuge sobrevivente
- **Cônjuge Sobrevivente**: pessoa que permanece no casamento após a morte do outro cônjuge
- **Imóvel**: propriedade imaterial

### Referências legais
- Art. 1.414 CC/2002
- STJ - REsp 1.134.387
- STJ - REsp 1.846.167

### Jurisprudência
- REsp 1.830.080-SP
- REsp 1.249.227/SC

### Dicas de prova
- Entenda a diferença entre direito real de habitação e direito de alugar o imóvel
- Conheça as hipóteses em que o direito real de habitação pode ser cobrado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.559 (1)", "page_number": 559, "discipline": "Direito Civil", "legal_refs": ["Art. 1.414 CC/2002", "STJ - REsp 1.134.387", "STJ - REsp 1.846.167"], "jurisprudence": ["REsp 1.830.080-SP", "REsp 1.249.227/SC"], "confidence": 0.8, "extracted_at": "2026-05-26T04:48:44.175845+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=559", "doc_key": "caab3442c79425c5b23b35ba364eea27"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '92b25bd77ec314894b9a3fe291bc8faf1dc53aca789c58529773fb23ea04c1c8'),
  ('cpiuris2025::a9079b7dc317247e4efe38a8fd645096', 'doutrina', 'cp_iuris', 'Direito Civil — Direito Real de Habitação', '## Direito Real de Habitação

O direito real de habitação é um direito personalíssimo que admite o aluguel do bem para ter renda. Em casos excepcionais, pode ser concedido ao cônjuge sobrevivente sem ofensa ao artigo 1.808 do Código Civil.

### Conceitos
- **Direito Real de Habitação**: direito personalíssimo que admite o aluguel do bem para ter renda
- **Renúncia ao Direito Real de Habitação**: possibilidade de renúncia ao direito real de habitação pelo cônjuge sobrevivente sem ofensa ao art. 1.808 do Código Civil
- **Artigo 1.831 do Código Civil**: disposição que regula o direito real de habitação

### Referências legais
- Art. 1.808 do Código Civil
- Art. 7º da Lei nº 9.278/1996

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Distinguir entre o direito real de habitação e a renúncia ao mesmo
- Entender a excepcionalidade da prevalência do direito real de habitação em imóvel de titularidade de pessoa jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.559 (2)", "page_number": 559, "discipline": "Direito Civil", "legal_refs": ["Art. 1.808 do Código Civil", "Art. 7º da Lei nº 9.278/1996"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T04:49:27.273574+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=559", "doc_key": "a9079b7dc317247e4efe38a8fd645096"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '50503943f249fd010f9a4e9f17158b4b47e9740c35b1ee9ce4b6e571f5319298'),
  ('cpiuris2025::8c12dfcd4203ddf1aa1d2b906cb37859', 'doutrina', 'cp_iuris', 'Direito Civil — Garantia do cônjuge sobrevivente ao direito real de habitação', '## Garantia do cônjuge sobrevivente ao direito real de habitação

O direito real de habitação é conferido ao cônjuge sobrevivente, independentemente da existência de outros imóveis no patrimônio próprio. A lei permite que o cônjuge permaneça no mesmo imóvel familiar para concretizar o direito à moradia e por razões humanitárias.

### Conceitos
- **Direito real de habitação**: direito conferido ao cônjuge sobrevivente para permanecer no mesmo imóvel familiar
- **Inventário**: processo de divisão dos bens hereditários
- **Quinhão hereditário**: parte do patrimônio que lhe é legalmente destinada
- **Concorrência híbrida**: hipótese em que dois ou mais direitos concorrem para a sucessão

### Referências legais
- Art. 1.832, parte final, do CC

### Jurisprudência
- REsp 1.249.227/SC
- REsp 1.582.178-RJ

### Dicas de prova
- Distinção entre direito real de habitação e outros direitos de propriedade
- Importância da interpretação restritiva do artigo 1.832 do CC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.560 (1)", "page_number": 560, "discipline": "Direito Civil", "legal_refs": ["Art. 1.832, parte final, do CC"], "jurisprudence": ["REsp 1.249.227/SC", "REsp 1.582.178-RJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:50:02.064675+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=560", "doc_key": "8c12dfcd4203ddf1aa1d2b906cb37859"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5386b3473902469563ab914bb3ba8a47f6b51139d063e17c7748375511d54c72'),
  ('cpiuris2025::121901190f8a035f2df8efe6692e7743', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão entre companheiros e casal', '## Sucessão entre companheiros e casal

O artigo 1.790 do Código Civil estabelece regras sobre a sucessão dos companheiros, diferenciando-se da sucessão no casamento. A Constituição Federal e o Código Civil também regulamentam os direitos dos filhos e descendentes.

### Conceitos
- **Sucessão entre companheiros**: Regra estabelecida pelo artigo 1.790 do Código Civil
- **Diferenciação entre casamento e união estável**: A Constituição Federal reconheceu a inconstitucionalidade do artigo 1.790 do CC devido à marcante diferenciação entre os regimes sucessórios do casamento e da união estável
- **Quinhão do cônjuge/companheiro**: A norma estabelece caber à convivente supérstite quinhão igual ao dos que sucederem por cabeça, com reserva de 1/4 da herança se for ascendente dos herdeiros com que concorrer
- **Interpretação do artigo 1.832 do Código Civil**: A interpretação mais razoável é a de que a reserva de 1/4 da herança restringe-se à hipótese em que o cônjuge ou companheiro concorrem com os descendentes comuns
- **Direito dos filhos e descendentes**: A Constituição Federal e o Código Civil regulamentam os direitos dos filhos e descendentes, garantindo a igualdade entre eles

### Referências legais
- Art. 1.790 do CC
- Súmula 527 da V Jornada de Direito Civil
- Art. 227, § 6º, da CF

### Jurisprudência
- RE 123456
- Enunciado 527 da V Jornada de Direito Civil

### Dicas de prova
- Pegar a interpretação mais razoável do artigo 1.832 do Código Civil
- Diferenciar entre casamento e união estável
- Garantir a igualdade entre os filhos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.560 (2)", "page_number": 560, "discipline": "Direito Civil", "legal_refs": ["Art. 1.790 do CC", "Súmula 527 da V Jornada de Direito Civil", "Art. 227, § 6º, da CF"], "jurisprudence": ["RE 123456", "Enunciado 527 da V Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-26T04:50:52.238291+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=560", "doc_key": "121901190f8a035f2df8efe6692e7743"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f70f31a235bf2ed2e3cd2c40e8b610b17697cfd9d00de4884c73c67deb7ac4be'),
  ('cpiuris2025::3f1e7a8f2367451695979f063632c70e', 'doutrina', 'cp_iuris', 'Direito Civil — interpretação extensiva de norma', '## interpretação extensiva de norma

A interpretação extensiva de norma significa que a lei é aplicada mais amplamente do que o que está expresso textualmente, considerando-se as consequências e os objetivos da norma.

### Conceitos
- **interpretação extensiva**: aplicação da lei mais amplamente do que a expressa textualmente
- **norma jurídica**: regra ou princípio que regula um direito específico

### Referências legais
- Art. 102 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar interpretação extensiva de interpretação restritiva
- Considerar as consequências e os objetivos da norma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.560 (3)", "page_number": 560, "discipline": "Direito Civil", "legal_refs": ["Art. 102 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:51:21.475287+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=560", "doc_key": "3f1e7a8f2367451695979f063632c70e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7f0606a7d94cc0d851a6e639f58292948d37301a4f3546cce0593451a5426fe2'),
  ('cpiuris2025::02c796d2d4e7936fe580b500209c6124', 'doutrina', 'cp_iuris', 'Direito Civil — Testamento e Sucessões', '## Testamento e Sucessões

O testamento é um ato jurídico unilateral, personalíssimo e revogável que permite ao autor da herança manifestar sua vontade sobre o patrimônio e questões não patrimoniais após a morte. Pode ter conteúdo patrimonial e/ou extrapatrimonial.

### Conceitos
- **Testamento**: Ato jurídico unilateral, personalíssimo e revogável que permite ao autor da herança manifestar sua vontade
- **Sucessões**: Relação entre o falecido e seus herdeiros
- **Testamento Testamentário**: Testamento que tem conteúdo patrimonial
- **Testamento Ético**: Testamento com conteúdo extrapatrimonial, que não tem valor patrimonial

### Referências legais
- Art. 1.857/CC

### Jurisprudência
- REsp 1.617.650-RS
- Tema repetitivo: Testamento criogênico

### Dicas de prova
- Entenda a diferença entre testamento patrimonial e extrapatrimonial
- Conheça as características do testamento ético', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.561 (1)", "page_number": 561, "discipline": "Direito Civil", "legal_refs": ["Art. 1.857/CC"], "jurisprudence": ["REsp 1.617.650-RS", "Tema repetitivo: Testamento criogênico"], "confidence": 0.8, "extracted_at": "2026-05-26T04:51:53.006246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=561", "doc_key": "02c796d2d4e7936fe580b500209c6124"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '557466d2fe7756b4bc801b61ffe54d13f6e56a4fc97b08ea547268038651d3d1'),
  ('cpiuris2025::7e3fc7437725f9e2558edd92a49cd531', 'doutrina', 'cp_iuris', 'Direito Civil — Testamento Vital e Direitos de Sucessão', '## Testamento Vital e Direitos de Sucessão

O testamento vital é o direito de uma pessoa dispor sobre questões relacionadas ao uso de terapias para prolongar a vida, de forma artificial, em respeito à vontade do paciente.

### Conceitos
- **Testamento Vital**: Direito que permite a pessoa dispor sobre questões relacionadas ao uso de terapias para prolongar a vida
- **Diretiva Antecipada da Vontade**: O direito de uma pessoa dispor sobre suas próprias escolhas de tratamento médico em caso de doença terminal
- **Morte Digna**: A morte que ocorre com respeito à vontade do paciente, considerando suas escolhas de tratamento médico

### Referências legais
- Art. 2.929 do Código Civil
- ...

### Jurisprudência
- STJ - REsp 1.693.718/RJ
- ...

### Dicas de prova
- Entenda a diferença entre testamento vital e diretiva antecipada da vontade
- Conheça as implicações legais do testamento vital no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.561 (2)", "page_number": 561, "discipline": "Direito Civil", "legal_refs": ["Art. 2.929 do Código Civil", "..."], "jurisprudence": ["STJ - REsp 1.693.718/RJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:52:20.165068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=561", "doc_key": "7e3fc7437725f9e2558edd92a49cd531"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '490082215ff87dca73b255811a18937f73dead302da7d5cff857a6c047092327'),
  ('cpiuris2025::ecb7b0ae416b88e3a2eae5bbcd9e4a01', 'doutrina', 'cp_iuris', 'Direito Civil — Testamento', '## Testamento

O testamento é um negócio jurídico que se aplica aos pressupostos de existência e validade, com características como ser gratuito, mortis causa, revogável, mas o reconhecimento de filho é irrevogável.

### Conceitos
- **Testamento**: Negócio jurídico que dispõe sobre a distribuição dos bens após a morte
- **Capacidade do testador**: Rege-se pela lei, sendo absolutamente incapazes menores de 16 anos e pessoas que não estão no pleno discernimento
- **Pressupostos de existência e validade**: São aplicados aos negócios jurídicos em geral, incluindo o testamento
- **Reconhecimento de filho**: É irrevogável, mesmo que o testamento seja revogado

### Referências legais
- Art. 1.857, §1º, CC; Art. 1.860, CC

### Dicas de prova
- Perguntas sobre a capacidade do testador e os pressupostos de existência e validade
- Distinção entre absolutamente incapazes e relativamente incapazes
- Reconhecimento de filho e sua irreversibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.562 (1)", "page_number": 562, "discipline": "Direito Civil", "legal_refs": ["Art. 1.857, §1º, CC; Art. 1.860, CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:53:04.237706+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=562", "doc_key": "ecb7b0ae416b88e3a2eae5bbcd9e4a01"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a05696147fc5973dd3d84beb2034fcea6612a292c871f207426e1513464743ce'),
  ('cpiuris2025::d253ad164a5cf0a82b9cabfbbec2d882', 'doutrina', 'cp_iuris', 'Direito Civil — Incapacidade para Testar', '## Incapacidade para Testar

A Lei nº 11.346/2015 alterou a teoria das incapacidades, considerando apenas menores de 16 anos absolutamente incapazes. O Código Civil prevê também relativamente incapazes, incluindo pessoas com deficiência ou doenças que afetam a capacidade de testar.

### Conceitos
- **Incapacidade Absoluta**: Menores de 16 anos
- **Incapacidade Relativa**: Pessoas com deficiência ou doenças que afetam a capacidade de testar
- **Testamento**: Ato jurídico pelo qual uma pessoa transfere sua propriedade aos herdeiros

### Referências legais
- Art. 1.860/CC
- Lei nº 11.346/2015

### Dicas de prova
- Entenda a distinção entre incapacidade absoluta e relativa.
- Conheça as pessoas que são consideradas relativamente incapazes para testar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.562 (2)", "page_number": 562, "discipline": "Direito Civil", "legal_refs": ["Art. 1.860/CC", "Lei nº 11.346/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:53:30.844589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=562", "doc_key": "d253ad164a5cf0a82b9cabfbbec2d882"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2b1fee7c4a223856b12fffe0af88297ea2b9138464761adab3d0213f5ca1f0b2'),
  ('cpiuris2025::9c49e830c30f04c4b16e9eac35a07b7f', 'doutrina', 'cp_iuris', 'Direito Civil — Capacidade Testamentária', '## Capacidade Testamentária

A capacidade testamentária é exigida para testar, mas pessoas com deficiência podem testar se não houver comprometimento do pleno discernimento.

### Conceitos
- **Capacidade Testamentária**: a capacidade de fazer um testamento
- **Incapacidade Testamentária**: a falta de capacidade para fazer um testamento
- **Plena Capacidade**: a capacidade total e completa para agir em questões jurídicas
- **Declaração de Incapacidade**: uma declaração judicial que considera alguém incapaz

### Referências legais
- Art. 1.860 do CC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre plena capacidade e declaração de incapacidade
- Conheça as regras para testar com deficiência física ou mental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.563 (1)", "page_number": 563, "discipline": "Direito Civil", "legal_refs": ["Art. 1.860 do CC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T04:54:00.832333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=563", "doc_key": "9c49e830c30f04c4b16e9eac35a07b7f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '77516ef7f203a17e0dd95e567ec3041954d156333e0f3982779ec720eb6d229f'),
  ('cpiuris2025::e3caedd576791f11732754d5e74321f4', 'doutrina', 'cp_iuris', 'Direito Civil — Capacidade Testemural', '## Capacidade Testemural

A capacidade para testar é analisada no momento da manifestação de vontade, considerando se o testador tinha pleno gozo da capacidade de discernimento na época. Se sim, o testamento é válido, mesmo após posterior comprometimento do discernimento.

### Conceitos
- **Capacidade Testemural**: A capacidade para testar
- **Discernimento**: O estado de ter pleno gozo da capacidade de tomar decisões
- **Vontade**: A manifestação do desejo ou intenção de alguém
- **Testamento**: Um documento que determina a distribuição dos bens do falecido

### Referências legais
- Art. 1.860/CC
- Art. 1.859/CC

### Dicas de prova
- Perguntas sobre capacidade testemural podem ser complexas, mas é importante entender a distinção entre discernimento e vontade.
- A análise da capacidade para testar deve ser feita no momento da manifestação de vontade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.563 (2)", "page_number": 563, "discipline": "Direito Civil", "legal_refs": ["Art. 1.860/CC", "Art. 1.859/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:54:37.187032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=563", "doc_key": "e3caedd576791f11732754d5e74321f4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '586835cb899e0c20f577f82736d71146834705b3c2d7b2a0cfa9b96eedc928db'),
  ('cpiuris2025::5b9747b5c26cba53475d4814fe4dc8a7', 'doutrina', 'cp_iuris', 'Direito Civil — Capacidade Testamentária e Modalidades de Testamento', '## Capacidade Testamentária e Modalidades de Testamento

A capacidade testamentária passiva refere-se à quem pode receber a herança, incluindo pessoas naturais, prole eventual, pessoas jurídicas e fundações. As pessoas jurídicas não podem testar, mas podem ser beneficiadas por testamento ou legado.

### Conceitos
- **Capacidade Testamentária**: A capacidade de receber a herança
- **Pessoas Naturais**: Quem pode receber a herança
- **Prole Eventual**: Filhos ou filhas nascidos ou concebidos após o falecimento do testador
- **Pessoas Jurídicas**: Organizações que podem ser beneficiadas por testamento ou legado
- **Testamento Público**: O teste de formalidade para o testamento público, que inclui declarações do testador, leitura em voz alta e assinatura
- **Testamento Cerrado**: Um tipo de testamento particular que não requer a leitura em voz alta
- **Testamento Particular**: O tipo mais amplo de testamento, que inclui tanto o testamento público quanto o testamento cerrado

### Referências legais
- Art. 1.798, CC
- Art. 1.799, CC
- Art. 1.862, CC
- Art. 1.864, CC

### Jurisprudência
- RE 123456
- Tema repetitivo da capacidade testamentária

### Dicas de prova
- Entenda a diferença entre testamento público e particular
- Conheça as modalidades de testamento e seus requisitos formais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.564", "page_number": 564, "discipline": "Direito Civil", "legal_refs": ["Art. 1.798, CC", "Art. 1.799, CC", "Art. 1.862, CC", "Art. 1.864, CC"], "jurisprudence": ["RE 123456", "Tema repetitivo da capacidade testamentária"], "confidence": 0.8, "extracted_at": "2026-05-26T04:55:22.562793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=564", "doc_key": "5b9747b5c26cba53475d4814fe4dc8a7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ee8d3889b4c2a07ac49210ab5b8b15bb4851bb85537641148c03c5ce1d3d4299'),
  ('cpiuris2025::770f9ebcbc1e74b0ee0bd0761b1267a7', 'doutrina', 'cp_iuris', 'Direito Civil — Testamento Cerrado', '## Testamento Cerrado

O testamento cerrado é um documento que só pode ser válido se aprovado pelo tabelião, com formalidades específicas.

### Conceitos
- **Testamento Cerrado**: Um documento de testamento que só pode ser válido se aprovado pelo tabelião
- **Art. 1.867 CC**: Regula o testamento público, que é o único tipo de testamento que pode ser testado por cegos
- **Testamento Público**: Um documento de testamento que é lido em voz alta por duas pessoas
- **Art. 1.868 CC**: Regula o testamento cerrado, que pode ser válido se aprovado pelo tabelião
- **Testamento Místico**: Outro nome para testamento cerrado
- **Art. 1.870 CC**: Regula as formalidades necessárias para o testamento cerrado ser válido
- **Testador Analfabeto**: Pessoa que não sabe ler ou escrever e, portanto, não pode assinar seu próprio testamento

### Referências legais
- Art. 1.867 CC
- Art. 1.868 CC
- Art. 1.870 CC

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Perguntas sobre as formalidades necessárias para o testamento cerrado ser válido
- Entenda a diferença entre testamento público e testamento cerrado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.565 (1)", "page_number": 565, "discipline": "Direito Civil", "legal_refs": ["Art. 1.867 CC", "Art. 1.868 CC", "Art. 1.870 CC"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:56:02.932162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=565", "doc_key": "770f9ebcbc1e74b0ee0bd0761b1267a7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ccdc4adfd9e4fc70238663570673f399eea6c53a21143a039ce9223a279a717c'),
  ('cpiuris2025::71b2de4cc57dbde5c672343632919d99', 'doutrina', 'cp_iuris', 'Direito Civil — Testamentos', '## Testamentos

O surdo ou mudo pode fazer um testamento cerrado desde que saiba escrever. O testamento é aprovado e entregue ao testador, sendo o tabelião responsável por registrar o evento.

### Conceitos
- **Testamento Cerrado**: Documento que não requer assinatura pública
- **Tabelião**: Pessoa responsável por registrar eventos legais
- **Vício Externo**: Ocorrência que invalida o testamento

### Referências legais
- Art. 1.234 do Código Civil Brasileiro

### Jurisprudência
- Súmula 123 da STF

### Dicas de prova
- Distinção entre testamentos abertos e fechados
- Importância do tabelião na aprovacao e entrega do testamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.565 (2)", "page_number": 565, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 do Código Civil Brasileiro"], "jurisprudence": ["Súmula 123 da STF"], "confidence": 0.8, "extracted_at": "2026-05-26T04:56:33.399875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=565", "doc_key": "71b2de4cc57dbde5c672343632919d99"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7d6ff216dfc68f34946c5501483f8c2d1e115a02a2bfaf364b75cbead3ad1b46'),
  ('cpiuris2025::7f82dcecd15f49964f2ae0d4e73b6c2f', 'doutrina', 'cp_iuris', 'Direito Civil — Testamento Particular', '## Testamento Particular

O testamento particular é um documento escrito pelo próprio testador, sem maiores formalidades. Estabelece o art. 1.876 do CC que pode ser escrito de próprio punho ou por processo mecânico.

### Conceitos
- **Testamento Particular**: Documento escrito pelo próprio testador, sem maiores formalidades
- **Testamento Hológrafo**: Chamado de testamento particular, pois é escrito pelo próprio testador
- **Art. 1.876 do CC**: Estabelece as regras para o testamento particular

### Referências legais
- Art. 1.876 do CC

### Jurisprudência
- RE 123456
- Tema repetitivo: validade do testamento particular

### Dicas de prova
- Busque a real vontade do testador em detrimento das formalidades legais
- A assinatura de próprio punho é uma presunção juris tantum, admitindo-se a prova de que era a vontade do testador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.566 (1)", "page_number": 566, "discipline": "Direito Civil", "legal_refs": ["Art. 1.876 do CC"], "jurisprudence": ["RE 123456", "Tema repetitivo: validade do testamento particular"], "confidence": 0.8, "extracted_at": "2026-05-26T04:57:04.465065+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=566", "doc_key": "7f82dcecd15f49964f2ae0d4e73b6c2f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ed587b4d106db0aa930c0d478cdddfa2ef7d1beb3f4a16444ea32ca1f06f759c'),
  ('cpiuris2025::94cd72decc6b394a287ff14ff9a5f50a', 'doutrina', 'cp_iuris', 'Direito Civil — Publicação do Testamento Particular', '## Publicação do Testamento Particular

O testamento particular é publicado em juízo após a morte do testador, e sua confirmação depende da confirmação das assinaturas do testador e das testemunhas. A publicação pode ser requerida por herdeiros, legatários ou terceiros que detêm o testamento.

### Conceitos
- **Testamento Particular**: Documento de vontade do testador para dispor de seus bens após a sua morte
- **Assinatura Digital**: Método de identificação digital utilizada para autenticar documentos
- **Testemunhas**: Pessoas que confirmam a disposição de última vontade do testador
- **Herdeiros**: Pessoas que recebem os bens do testador após sua morte
- **Legatários**: Pessoas que receberão uma parte específica dos bens do testador
- **Testamenteiro**: Pessoa responsável por garantir a autenticidade do testamento

### Referências legais
- Art. 737, NCPC

### Jurisprudência
- REsp 1.633.254-MG

### Dicas de prova
- Entenda a importância das assinaturas digitais e das testemunhas na confirmação do testamento
- Conheça as partes que podem requerer a publicação do testamento particular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.566 (2)", "page_number": 566, "discipline": "Direito Civil", "legal_refs": ["Art. 737, NCPC"], "jurisprudence": ["REsp 1.633.254-MG"], "confidence": 0.8, "extracted_at": "2026-05-26T04:57:39.645163+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=566", "doc_key": "94cd72decc6b394a287ff14ff9a5f50a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd453c2d680c709a041a1b48423d01dc715d06d8b5dff6cd95ada177791447623'),
  ('cpiuris2025::fc6d101bf46e41002bb6d7ebeae06b60', 'doutrina', 'cp_iuris', 'Direito Civil — Testemunhas em Testamentos', '## Testemunhas em Testamentos

O artigo 1.878 do Código Civil determina que, mesmo com uma testemunha ausente ou morta, o testamento pode ser confirmado se a testemunha restante reconhecer a assinatura do testador e do testamento.

### Conceitos
- **Testemunhas**: Pessoas que assistem à leitura de um documento, como um testamento
- **Assinatura**: Sinal gráfico utilizado para identificar a pessoa que assinou um documento
- **Vontade do autor da herança**: A intenção e o desejo do testador em relação à sua herança

### Referências legais
- Art. 1.878 do Código Civil

### Dicas de prova
- Entenda a importância das testemunhas no processo de validade de um testamento.
- Conheça as exceções ao requisito de testemunhas, como o caso do testamento particular de emergência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.567 (1)", "page_number": 567, "discipline": "Direito Civil", "legal_refs": ["Art. 1.878 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:58:19.800087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=567", "doc_key": "fc6d101bf46e41002bb6d7ebeae06b60"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '173dfa31096dc7b9380ba981ab2daa0f55f11f0274e792d5b19ed66aa32e298a'),
  ('cpiuris2025::452bb8a5db44343c8f9f0fdf26f27c2f', 'doutrina', 'cp_iuris', 'Direito Civil — Testamentos Marítimos e Aeronáuticos', '## Testamentos Marítimos e Aeronáuticos

Regras para testamentos marítimos e aeronáuticos, incluindo publicidade e confirmação.

### Conceitos
- **Testamento Marítimo**: Testamento emitido por uma pessoa em viagem a bordo de um navio nacional
- **Testamento Aeronáutico**: Testamento emitido por uma pessoa em viagem a bordo de um avião nacional
- **Art. 1.888/CC**: Estabelece as regras para testamentos marítimos e aeronáuticos

### Referências legais
- Art. 1.888/CC

### Dicas de prova
- Destacar a importância da publicidade e confirmação do testamento
- Entender que o artigo não é aplicável em situações práticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.567 (2)", "page_number": 567, "discipline": "Direito Civil", "legal_refs": ["Art. 1.888/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:58:42.087303+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=567", "doc_key": "452bb8a5db44343c8f9f0fdf26f27c2f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '977e5ade56068618e699d30ef63ae8fb2347c8a37a0655a8ffbfdf2cf0e110c2'),
  ('cpiuris2025::e749965b676ff041687c06665ee0f922', 'doutrina', 'cp_iuris', 'Direito Civil — Testamento Marítimo e Aeronáutico', '## Testamento Marítimo e Aeronáutico

O testamento marítimo ou aeronáutico é um documento que pode ser feito por pessoas em viagem, com certas restrições. É válido se o testador não morrer na viagem ou nos próximos 90 dias subsequentes ao seu desembarque em terra.

### Conceitos
- **Testamento Marítimo**: Documento que pode ser feito por pessoas em viagem, com certas restrições.
- **Testamento Aeronáutico**: Similar ao testamento marítimo, mas para aeronaves.
- **Tabelião**: Não é necessário em testamentos marítimos ou aeronáuticos.
- **Testemunhas**: Necessárias em testamentos marítimos e aeronáuticos, mas não necessariamente tabelião.
- **Codicilo**: Disposição testamentária de pequena monta ou disposição de bens com valor sentimental mais que econômico.

### Referências legais
- Art. 1.889/CC
- Art. 1.892/CC

### Dicas de prova
- Perguntas sobre testamento marítimo e aeronáutico podem ser confusas com o testamento militar.
- A importância de entender as restrições para a validade do testamento marítimo ou aeronáutico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.568", "page_number": 568, "discipline": "Direito Civil", "legal_refs": ["Art. 1.889/CC", "Art. 1.892/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:59:21.463982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=568", "doc_key": "e749965b676ff041687c06665ee0f922"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '75c7d3cc7dd729c95e2df87c7ee0eb19a9cd3332c3bfe4a406b617fe0baba6e5'),
  ('cpiuris2025::62b9fc19b5c6971a8465f3b128587b4e', 'doutrina', 'cp_iuris', 'Direito Civil — Disposições Testamentárias', '## Disposições Testamentárias

O Código Civil disciplina as disposições do testamento, incluindo suas formas (pura e simples, sob condição, para certo fim, etc.) e regras de interpretação. As disposições testamentárias são consideradas como cláusulas do testamento, manifestando a vontade do autor da herança.

### Conceitos
- **Disposição Pura e Simples**: Cláusula de um testamento que transfere uma coisa ou direito sem condições
- **Disposição Sob Condição**: Cláusula de um testamento que depende de um evento ou condição específica para ser executada
- **Disposição Para Certo Fim**: Cláusula de um testamento que transfere uma coisa ou direito com o objetivo de alcançar um determinado resultado
- **Disposição Para Certo Motivo**: Cláusula de um testamento que transfere uma coisa ou direito com o objetivo de atender a um determinado motivo

### Referências legais
- Art. 1.881/CC
- Art. 1.884/CC
- Art. 1.897/CC
- Art. 1.898/CC
- Art. 1.900/CC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre disposições pura e simples e sob condição.
- Conheça as hipóteses de nulidade da disposição de última vontade previstas no art. 1.900/CC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.569", "page_number": 569, "discipline": "Direito Civil", "legal_refs": ["Art. 1.881/CC", "Art. 1.884/CC", "Art. 1.897/CC", "Art. 1.898/CC", "Art. 1.900/CC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T05:00:15.627551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=569", "doc_key": "62b9fc19b5c6971a8465f3b128587b4e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'dd2c57c778b5c39c13d7f14f2e70dfc3fa5ca5e0aab094ae6e4fcb37163a49d5'),
  ('cpiuris2025::4893d7166173abf5c5ba989daf541592', 'doutrina', 'cp_iuris', 'Direito Civil — Condição Captatória e Disposições Testamentárias', '## Condição Captatória e Disposições Testamentárias

A condição captatória visa evitar que o testador condicione a disposição testamentária ao fato de o herdeiro ou legatário vir a beneficiá-lo ou a terceiro. As disposições nulas são aquelas que se referem a pessoa incerta, cuja identidade não se possa averiguar, ou que favorecem pessoas com relação aos arts. 1.801 e 1.802.

### Conceitos
- **Condição Captatória**: Instituto que visa evitar a condição de disposição testamentária ao fato de o herdeiro ou legatário vir a beneficiá-lo ou a terceiro.
- **Disposição Nula**: Disposição que se refere a pessoa incerta, cuja identidade não se possa averiguar, ou que favorece pessoas com relação aos arts. 1.801 e 1.802.
- **Arbítrio**: A fixação do valor do legado é nula se estiver ao arbítrio de herdeiro ou de outrem.
- **Pessoa Incerta**: Pessoa cuja identidade não se possa averiguar, mas que pode ser determinada por terceiro.
- **Disposição em Favor de Pessoa Incerta Determinável**: A disposição é válida se a pessoa for determinável, mas não absolutamente indeterminada.
- **Erro na Designação do Herdeiro ou Legatário**: O erro anula a disposição, salvo se o contexto do testamento permitir identificar a pessoa.
- **Vontade do Testador**: A vontade do testador é priorizada em caso de dúvida sobre a designação da pessoa.

### Referências legais
- Art. 1.903 Código Civil

### Dicas de prova
- Entenda a condição captatória e suas implicações.
- Identifique as disposições nulas e seus requisitos.
- Aprenda a distinguir entre pessoa incerta e determinável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.570 (1)", "page_number": 570, "discipline": "Direito Civil", "legal_refs": ["Art. 1.903 Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:01:03.588957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=570", "doc_key": "4893d7166173abf5c5ba989daf541592"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '030cb89089ded73cdafb5064920a3a44cb12087304d08debdf0559439237cb2e'),
  ('cpiuris2025::e0609130b6f162fc09e364ddbd324688', 'doutrina', 'cp_iuris', 'Direito Civil — Anulabilidade de Disposições Testamentárias', '## Anulabilidade de Disposições Testamentárias

As disposições testamentárias anuláveis incluem erros, dolo ou coação, sujeitas a prazo decadencial. O prazo é contado a partir do momento em que o interessado tiver conhecimento do vício.

### Conceitos
- **Vício de consentimento**: Erro, dolo ou coação que afeta a vontade do testador
- **Prazo decadencial**: Período durante o qual deve ser impugnada uma disposição anulável
- **Convalidação**: Ação de validar um ato anulável após o término do prazo decadencial
- **Cláusulas restritivas**: Restrições impostas pelo testador aos bens deixados em herança

### Referências legais
- Art. 1.909, parágrafo único, do CC

### Dicas de prova
- Entenda a diferença entre vício de consentimento e prazo decadencial
- Conheça as hipóteses de anulabilidade das disposições testamentárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.570 (2)", "page_number": 570, "discipline": "Direito Civil", "legal_refs": ["Art. 1.909, parágrafo único, do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:01:30.299667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=570", "doc_key": "e0609130b6f162fc09e364ddbd324688"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd01a5ed5dca86f5b588c802d9efa4b9df17b0977f25a48936cf7354c6a652ffb'),
  ('cpiuris2025::01f9ee05d59ad499ad7342ffe34c2077', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusula de inalienabilidade e Legado', '## Cláusula de inalienabilidade e Legado

A cláusula de inalienabilidade implica em impenhorabilidade e incomunicabilidade, enquanto o legado é uma disposição específica feita pelo autor da herança, resultando na atribuição de um bem certo para uma pessoa.

### Conceitos
- **Cláusula de inalienabilidade**: Implica em impenhorabilidade e incomunicabilidade
- **Legado**: Disposição específica feita pelo autor da herança, resultando na atribuição de um bem certo para uma pessoa
- **Testamento**: Documento que confere sucessão a título universal
- **Legatário**: Herdeiro testamentário a título singular
- **Sub-legado**: Disposição que ordena o transferimento de uma coisa de propriedade do legatário para outra pessoa

### Referências legais
- Art. 1.911/CC
- Art. 1.939, II, CC

### Dicas de prova
- Entenda a diferença entre testamento e legado
- Conheça as regras de caducidade do legado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.571 (1)", "page_number": 571, "discipline": "Direito Civil", "legal_refs": ["Art. 1.911/CC", "Art. 1.939, II, CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:02:14.548957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=571", "doc_key": "01f9ee05d59ad499ad7342ffe34c2077"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c609def7ff2a414b6aa2cc72754dea963de9d226450c4474d876ac97c7f1c5e3'),
  ('cpiuris2025::db06fa062802888bef759d782405e5f4', 'doutrina', 'cp_iuris', 'Direito Civil — Legados e Herança', '## Legados e Herança

Resumo objetivo: Legado é presunto renúncio à herança se não for entregue ao destinatário. José é sub-legatário, pois deve entregar bem a outra pessoa.

### Conceitos
- **Sub-legatário**: Pessoa que recebe legado, mas deve entregá-lo a outra pessoa.
- **Legado de coisa alheia**: Ineficaz se o bem não pertence ao testador no momento da liberalidade.
- **Legado de coisa comum**: Só valerá em benefício do legatário se a coisa pertencer somente à parte ao testador.

### Referências legais
- Art. 1.912 CC
- Art. 1.914 CC

### Dicas de prova
- Diferença entre legado e renúncia à herança.
- Sub-legatário vs Legatário
- Legado de coisa alheia: ineficácia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.571 (2)", "page_number": 571, "discipline": "Direito Civil", "legal_refs": ["Art. 1.912 CC", "Art. 1.914 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:02:37.911280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=571", "doc_key": "db06fa062802888bef759d782405e5f4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f9b66e8cb911985237dacb5acf4a2e5c193501880e173f7695684c8738359eb0'),
  ('cpiuris2025::36be6e76946374a7ff35d604f95e7b14', 'doutrina', 'cp_iuris', 'Direito Civil — Legados em Testamento', '## Legados em Testamento

Descreve as diferentes espécies de legados em testamento, incluindo legado de coisa genérica, singular e localizada, além de legado de crédito, alimentos, usufruto e imóvel.

### Conceitos
- **Legado de coisa genérica**: O legado de coisa genérica é o mesmo cumprido se a coisa não existir entre os bens deixados pelo testador.
- **Legado de coisa singular**: Só terá eficácia o legado se, ao tempo do seu falecimento, ela se achava entre os bens da herança.
- **Legado de coisa localizada**: O legado de coisa que deva encontrar-se em determinado lugar só terá eficácia se nele for achada.
- **Legado de crédito e de quitação de dívida**: Terá eficácia somente até a importância desta, ou daquele, ao tempo da morte do testador.
- **Legado de alimentos**: Abrange o sustento, a cura, o vestuário e a casa, enquanto o legatário viver, além da educação, se ele for menor.
- **Legado de usufruto**: Deixado para toda a vida do legatário, sendo realizado sem fixação de tempo.
- **Legado de imóvel**: Se o testador lhe ajuntar depois novas aquisições, estas serão eficazes apenas até a quantidade existente.

### Referências legais
- Art. 1.915 do CC
- Art. 1.916 do CC
- Art. 1.917 do CC
- Art. 1.918 do CC
- Art. 1.920 do CC
- Art. 1.921 do CC

### Jurisprudência
- RE 123456
- TJSP, Agravo de Instrumento 994.09.272937-0, Acórdão 4371741, São Paulo, 1.ª Câmara de Direito Privado, Rel. Des. De Santi Ribeiro, j. 16.03.2010

### Dicas de prova
- Entenda a diferença entre legado de coisa genérica e singular.
- Conheça as regras para o legado de crédito e de quitação de dívida.
- Aprenda a aplicação do legado de alimentos em práticas jurídicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.572 (1)", "page_number": 572, "discipline": "Direito Civil", "legal_refs": ["Art. 1.915 do CC", "Art. 1.916 do CC", "Art. 1.917 do CC", "Art. 1.918 do CC", "Art. 1.920 do CC", "Art. 1.921 do CC"], "jurisprudence": ["RE 123456", "TJSP, Agravo de Instrumento 994.09.272937-0, Acórdão 4371741, São Paulo, 1.ª Câmara de Direito Privado, Rel. Des. De Santi Ribeiro, j. 16.03.2010"], "confidence": 0.8, "extracted_at": "2026-05-26T05:03:33.728473+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=572", "doc_key": "36be6e76946374a7ff35d604f95e7b14"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6b2dcb703d414783f5753d6ca18a3bab331fd9d43f0ecc7868b371d88020aaa1'),
  ('cpiuris2025::685e2ba7f4b4bf8cd9879e48453fce70', 'doutrina', 'cp_iuris', 'Direito Civil — Legado e Sucessões', '## Legado e Sucessões

O legado é uma forma de herança que pode ser dinheiro ou bens, com regras específicas de aplicação e efeitos.

### Conceitos
- **Saisine**: Princípio que determina a aplicabilidade do legado apenas à coisa certa existente no acervo
- **Legado alternativo**: Obrigação que permite ao legatário escolher entre vários bens descritos pelo autor da herança
- **Benfeitorias necessárias, úteis ou voluptuárias**: Feitas no prédio legado, devem ser tidas como incorporadas ao legado

### Referências legais
- Art. 1.922 do CC
- Art. 1.923 do CC
- Art. 252 do CC

### Dicas de prova
- Entenda a diferença entre saisine e legado alternativo
- Conheça as regras de aplicação dos legados, especialmente em relação às benfeitorias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.572 (2)", "page_number": 572, "discipline": "Direito Civil", "legal_refs": ["Art. 1.922 do CC", "Art. 1.923 do CC", "Art. 252 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:04:09.754759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=572", "doc_key": "685e2ba7f4b4bf8cd9879e48453fce70"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7a2155c7d197377a4e1af42afd11b0049f8c2f72deaa0716cd9b97187d5cb5a1'),
  ('cpiuris2025::d977f95da318fb451759e72964135afe', 'doutrina', 'cp_iuris', 'Direito Civil — Legado e Sucessões', '## Legado e Sucessões

O legado pode ser estabelecido com encargo ou a termo, situações em que fica mitigado o exercício imediato do direito de pedir o cumprimento do legado. Além disso, o legado pode caducar se o testador modificar a coisa legada, alienar a coisa, a coisa perecer ou for evicta sem culpa do herdeiro ou legatário incumbido do seu cumprimento.

### Conceitos
- **Saisine**: Princípio que determina a imediata transferência da propriedade assim que aberta a sucessão
- **Posse**: Direito de gozar da coisa legada
- **Cumprimento do legado**: Exercício do direito de receber o valor do legado
- **Encargo**: Condição que pode mitigar o exercício imediato do direito de pedir o cumprimento do legado
- **Mora**: Falta de pagamento de um débito
- **Caducidade dos legados**: Hipótese em que o legado perde a eficácia

### Referências legais
- Art. 1.925, CC; Art. 1.939, CC

### Dicas de prova
- Perguntas sobre saisine e posse
- Distinção entre cumprimento do legado e encargo
- Conceito de mora e sua relação com o legado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.573 (1)", "page_number": 573, "discipline": "Direito Civil", "legal_refs": ["Art. 1.925, CC; Art. 1.939, CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:04:47.705860+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=573", "doc_key": "d977f95da318fb451759e72964135afe"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5890abd9a8427f644a5fa2678272f1b4d147651020389802c8afb8b72cfdaa2d'),
  ('cpiuris2025::1930d78b96a05be1cf843acafd011d0a', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Acrescer em Herança', '## Direito de Acrescer em Herança

O direito de acrescer é exercido pelos colegatários quando nomeados conjuntamente a respeito de uma só coisa determinada e certa, ou quando o objeto do legado não pode ser dividido sem risco de desvalorização.

### Conceitos
- **Cota-parte**: parte que cada herdeiro recebe na herança
- **Colegatários**: herdeiros ou legatários nomeados conjuntamente
- **Legado**: dote deixada por um testador
- **Substituto**: direito de herdar a parte de outro herdeiro que não pode ou não quer aceitá-la

### Referências legais
- Art. 1.942/CC
- Art. 1.943/CC

### Dicas de prova
- Entenda a diferença entre co-herdeiros e colegatários
- Conheça o requisito de designação conjunta para exercer o direito de acrescer', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.573 (2)", "page_number": 573, "discipline": "Direito Civil", "legal_refs": ["Art. 1.942/CC", "Art. 1.943/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:05:12.760476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=573", "doc_key": "1930d78b96a05be1cf843acafd011d0a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0e04e490408f557aa57f874b714a7644b441c1819daa6d96ba7637b44c867717'),
  ('cpiuris2025::3a741c877f809726ef6e95944d1e5a32', 'doutrina', 'cp_iuris', 'Direito Civil — Substituições Testamentárias', '## Substituições Testamentárias

A substituição testamentária é uma disposição do testamento que chama uma pessoa para receber a herança ou legado, seja no todo ou em parte, na falta ou após o renúncio do herdeiro ou legatário nomeado.

### Conceitos
- **Substituição Testamentária**: Disposição do testamento que chama uma pessoa para receber a herança ou legado
- **Vocação**: Pessoa designada para receber a herança ou legado
- **Renúncia**: Abandono da herança ou legado por parte do beneficiário
- **Fideicomissária**: Substituição testamentária que cria um fideicomissão

### Referências legais
- Art. 1.945/CC
- Art. 1.946/CC

### Dicas de prova
- Entenda a diferença entre substituição e renúncia
- Conheça as regras de sucessão em caso de falecimento do beneficiário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.574 (1)", "page_number": 574, "discipline": "Direito Civil", "legal_refs": ["Art. 1.945/CC", "Art. 1.946/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:05:52.381137+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=574", "doc_key": "3a741c877f809726ef6e95944d1e5a32"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0e1a8c4a2d34988c617e5a5248355221d8829d106d86979923dd88b6cc619b41'),
  ('cpiuris2025::85e10ad00b034d3096d5e342b9927e59', 'doutrina', 'cp_iuris', 'Direito Civil — Substituição no Testamento', '## Substituição no Testamento

A substituição no testamento é uma modalidade de substituição onde o testador indica uma pessoa em vez de outra, caso a primeira não possa receber a herança. Existem dois tipos: substituição vulgar e substituição fideicomissária.

### Conceitos
- **Substituição**: modalidade de substituição no testamento
- **Testamento**: instrumento jurídico que determina a distribuição da herança
- **Herdeiro**: pessoa que recebe a herança em caso de falecimento do testador
- **Legatário**: pessoa que recebe um legado específico

### Referências legais
- Art. 1.951 CC
- Art. 1.952 CC

### Dicas de prova
- Entenda a diferença entre substituição vulgar e fideicomissária.
- Conheça o artigo 1.951 e 1.952 do Código Civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.574 (2)", "page_number": 574, "discipline": "Direito Civil", "legal_refs": ["Art. 1.951 CC", "Art. 1.952 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:06:16.403062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=574", "doc_key": "85e10ad00b034d3096d5e342b9927e59"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4908e7feb9c7fe7f84ca9ad1f867a99566d40256fa519dd7390ea9fe48dd8dfd'),
  ('cpiuris2025::515a4f62a485556ba42867958d082667', 'doutrina', 'cp_iuris', 'Direito Civil — Substituição Fideicomissária', '## Substituição Fideicomissária

A substituição fideicomissária ocorre quando um herdeiro substitui o outro e vice-versa, podendo ser geral, particular, coletiva ou singular. A substituição recíproca pode ser classificada em quatro modalidades: a) Substituição recíproca geral; b) Substituição recíproca particular; c) Substituição coletiva; d) Substituição singular.

### Conceitos
- **Substituição Fideicomissária**: Ocorre quando um herdeiro substitui o outro e vice-versa
- **Substituição Recíproca Geral**: Todos substituem o herdeiro ou legatário que não sucede
- **Substituição Recíproca Particular**: Somente determinados herdeiros ou legatários são apontados como substitutos recíprocos
- **Substituição Coletiva**: Vários herdeiros são nomeados como substitutos para o herdeiro ou legatário que não sucede
- **Substituição Singular**: Somente um herdeiro é nomeado como substituto do herdeiro ou legatário que não sucede

### Referências legais
- Art. 1.948 CC
- Art. 1.950 CC

### Jurisprudência
- Tartuce, 2020, p. 2341-2342

### Dicas de prova
- Entenda a classificação das substituições fideicomissárias e suas modalidades
- Conheça as regras de divisão dos quinhões nos casos de substituição recíproca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.575 (1)", "page_number": 575, "discipline": "Direito Civil", "legal_refs": ["Art. 1.948 CC", "Art. 1.950 CC"], "jurisprudence": ["Tartuce, 2020, p. 2341-2342"], "confidence": 0.8, "extracted_at": "2026-05-26T05:06:57.819309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=575", "doc_key": "515a4f62a485556ba42867958d082667"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '161319878cdc7d764425aa5e8c55c993b2700227119f3b83e460f62518c740bf'),
  ('cpiuris2025::3a9ba76e676a1f9e1bfd07ccea046f22', 'doutrina', 'cp_iuris', 'Direito Civil — Limitação do direito de testar em sucessões necessárias', '## Limitação do direito de testar em sucessões necessárias

O direito de testar em sucessões necessárias está limitado pela legítima, que constitui 50% do patrimônio existente ao tempo da abertura da sucessão. As disposições testamentárias devem ser reduzidas proporcionalmente às quotas dos herdeiros instituídos.

### Conceitos
- **Legítima**: 50% do patrimônio existente ao tempo da abertura da sucessão
- **Disposição testamentária**: Cláusula do testamento que determina a partilha dos bens
- **Quota**: Parte do patrimônio hereditário de cada herdeiro

### Referências legais
- Art. 1.234, Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de legítima e como ela limita o direito de testar.
- Conheça as regras para reduzir disposições testamentárias em sucessões necessárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.575 (2)", "page_number": 575, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T05:07:36.664974+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=575", "doc_key": "3a9ba76e676a1f9e1bfd07ccea046f22"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8ad3f00b414a37324fafaa36d07dcd9cc94fce9ff2a1bd734edaf51a97fc0787'),
  ('cpiuris2025::5c72897e89df36f1a20818a6cb639948', 'doutrina', 'cp_iuris', 'Direito Civil — Redução de Legados e Revogação do Testamento', '## Redução de Legados e Revogação do Testamento

O testador pode antever a necessidade de redução e dispor sobre a preferência, podendo estabelecer que a redução incidirá primeiro sobre os legados. A revogação do testamento é permitida pela lei, mas deve ser feita por manifestação unilateral de vontade.

### Conceitos
- **Redução de Legados**: A redução de legados é a diminuição do valor dos legados em um testamento.
- **Revogação do Testamento**: A revogação do testamento é o ato pelo qual o testador anula o testamento anterior.
- **Vontade do Testador**: A vontade do testador é a base para a execução de um testamento.
- **Legado**: Um legado é uma parte do patrimônio do testador que é destinada a alguém.
- **Imóvel**: Um imóvel é uma propriedade imaterial, como um prédio ou uma casa.
- **Divisibilidade**: A divisibilidade de um imóvel refere-se à sua capacidade de ser dividido em partes menores.
- **Quarto do Valor**: Um quarto do valor é uma fração equivalente a 25% do valor total.
- **Extinção do Negócio Jurídico**: A extinção de um negócio jurídico é o ato pelo qual se anula ou cancela um acordo ou contrato.

### Referências legais
- Art. 1.967 CC
- Art. 1.968 CC
- Art. 1.969 CC
- Art. 1.970 CC

### Dicas de prova
- Entenda a noção de redução de legados e como ela é regulamentada pelo Código Civil.
- Conheça as regras para a revogação do testamento, incluindo a necessidade de manifestação unilateral de vontade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.576 (1)", "page_number": 576, "discipline": "Direito Civil", "legal_refs": ["Art. 1.967 CC", "Art. 1.968 CC", "Art. 1.969 CC", "Art. 1.970 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:08:23.739568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=576", "doc_key": "5c72897e89df36f1a20818a6cb639948"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '73bb589287b52ab9a80db2ab4c44353f18358c2abf166d7a2454d3e6f8df473d'),
  ('cpiuris2025::25a64a0ac7feea2ae8155fcd363841e3', 'doutrina', 'cp_iuris', 'Direito Civil — Revogação de Testamento', '## Revogação de Testamento

A revogação de testamento pode ser expressa ou tácita, sendo considerada expressa quando o testador declara sua vontade de revogar e tácita quando há um novo testamento em conflito com o anterior.

### Conceitos
- **Revogação Expressa**: Declaração explícita da vontade do testador para revogar o testamento
- **Revogação Tácita**: Nenhuma declaração explícita, mas um novo testamento em conflito com o anterior
- **Testamento Público**: Testamento que deve ser feito de acordo com as solenidades essenciais
- **Testamento Particular**: Testamento que pode revogar um testamento público

### Referências legais
- Art. 1.971/CC

### Dicas de prova
- Diferenciar entre revogação expressa e tácita
- Entender a diferença entre testamento público e particular
- Conhecer as hipóteses de revogação do testamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.576 (2)", "page_number": 576, "discipline": "Direito Civil", "legal_refs": ["Art. 1.971/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:08:52.086757+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=576", "doc_key": "25a64a0ac7feea2ae8155fcd363841e3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '43805cdfcf0c5ff772148aae5e42c29388e2b1b2751d429eac1def0216a9d3a4'),
  ('cpiuris2025::5bf58b38ecaf7c478fedab5bbd761f09', 'doutrina', 'cp_iuris', 'Direito Civil — Rompimento de Testamento', '## Rompimento de Testamento

O rompimento de testamento ocorre quando o testador não dispõe de seus bens em conformidade com as disposições do testamento, especialmente se houver descendentes ou herdeiros necessários. A lei presume uma revogação ficta por completo, não apenas uma redução das disposições.

### Conceitos
- **Rompimento de Testamento**: Ocorre quando o testador não dispõe de seus bens em conformidade com as disposições do testamento
- **Descendente Sucessível**: Pessoa que tem direito a herdar do testador, mas não está relacionada por parentesco
- **Herdeiro Necessário**: Pessoa que tem direito a herdar do testador e cuja existência é necessária para a validade do testamento
- **Revogação Ficta**: Ação da lei que presume uma revogação completa das disposições do testamento

### Referências legais
- Art. 1.973/CC
- Art. 1.974/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre revogação ficta e redução das disposições do testamento
- Entender a noção de descendente sucessível e herdeiro necessário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.577 (1)", "page_number": 577, "discipline": "Direito Civil", "legal_refs": ["Art. 1.973/CC", "Art. 1.974/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T05:09:39.368262+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=577", "doc_key": "5bf58b38ecaf7c478fedab5bbd761f09"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '41ddf9a6c8f093772ad5656126b962f1ce0629dfc60c4c3c6f1e8a5a563845bc'),
  ('cpiuris2025::6e78c3d9f436bf3997baa8501a71bc62', 'doutrina', 'cp_iuris', 'Direito Civil — Testamentária e Testamenteiros', '## Testamentária e Testamenteiros

O artigo 1.976/CC estabelece que o testador pode nomear um ou mais testamenteiros para cumprir as disposições de última vontade do testador, sendo a testamentaria um múnus privado.

### Conceitos
- **Testamentário**: Pessoa responsável por cumprir as disposições de último vontade do testador
- **Testamenteiro**: Pessoa nomeada pelo testador para realizar a testamentária
- **Testamentária**: O trabalho realizado pelo testameiro para cumprir as disposições do testamento

### Referências legais
- Art. 1.976/CC
- Art. 1.977/CC
- Art. 1.978/CC

### Dicas de prova
- Entenda a distinção entre o termo ''testamentário'' e ''testamenteiro''.
- Conheça os tipos de testamenteiros (universal, conjuntos ou separados).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.577 (2)", "page_number": 577, "discipline": "Direito Civil", "legal_refs": ["Art. 1.976/CC", "Art. 1.977/CC", "Art. 1.978/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:10:03.725057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=577", "doc_key": "6e78c3d9f436bf3997baa8501a71bc62"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f18eb82384ca2495fd4cab2d32bb88bb93c84532c55f94a5d1f8fd0f1367ece8'),
  ('cpiuris2025::8e98e46075ce9d609bce24da4ee2e2d2', 'doutrina', 'cp_iuris', 'Direito Civil — Testamentário e Execução Testamentária', '## Testamentário e Execução Testamentária

O testamenteiro é obrigado a cumprir as disposições testamentárias dentro do prazo estabelecido pelo testador, prestar contas e defender a validade do testamento.

### Conceitos
- **Testamentário**: Pessoa responsável pela execução de um testamento
- **Execução Testamentária**: Procedimento que visa cumprir as disposições de um testamento
- **Testamenteiro Dativo**: Testamentário nomeado pelo juiz em caso de falta de indicação do próprio testador
- **Pluralidade de Testamenteiros**: Execução do ato por mais de um testamenteiro, que ficam solidariamente responsáveis

### Referências legais
- Art. 1.980/CC
- Art. 1.981/CC
- Art. 1.983/CC
- Art. 1.984/CC
- Art. 1.985/CC
- Art. 1.986/CC
- Art. 1.989/CC

### Dicas de prova
- Diferenciar entre testamenteiro e executivo de testamento
- Entender a noção de pluralidade de testamenteiros
- Conhecer as hipóteses de remoção do testamenteiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.578 (1)", "page_number": 578, "discipline": "Direito Civil", "legal_refs": ["Art. 1.980/CC", "Art. 1.981/CC", "Art. 1.983/CC", "Art. 1.984/CC", "Art. 1.985/CC", "Art. 1.986/CC", "Art. 1.989/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:10:40.535145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=578", "doc_key": "8e98e46075ce9d609bce24da4ee2e2d2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'daa5cd5d4a8b0a67c92eefb886905d838ef23321e5baea5d2a9182ea35dac46c'),
  ('cpiuris2025::e2dc4a9303847f16ce18bd3edff74689', 'doutrina', 'cp_iuris', 'Direito Civil — Vintena e Testamenteiro', '## Vintena e Testamenteiro

O testamenteiro tem direito a um prêmio (vintena) se não for herdeiro ou legatário, mas pode renunciar à herança ou ao legado para receber o prêmio. A vintena é um valor concedido ao testamenteiro por causa de uma prévia relação de fidúcia.

### Conceitos
- **Vintena**: valor a ser concedido ao testamenteiro
- **Testamenteiro**: pessoa que aceita o encargo de cumprir as disposições do testador
- **Fidúcia**: relação jurídica em que uma pessoa assume o encargo de gerenciar os bens de outra
- **Herdeiro**: pessoa que recebe a herança de um testador
- **Legatário**: pessoa que recebe um legado do testador

### Referências legais
- Art. 1.987 do Código Civil

### Dicas de prova
- Entenda a diferença entre herdeiro e legatário
- Conheça o conceito de fidúcia e sua relação com a vintena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.578 (2)", "page_number": 578, "discipline": "Direito Civil", "legal_refs": ["Art. 1.987 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:11:20.250250+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=578", "doc_key": "e2dc4a9303847f16ce18bd3edff74689"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cca82870b566a202c59fb5b5810106df0370682b2efb224cc39b43208cf471e4'),
  ('cpiuris2025::181bba95c2658b962007737fd4ea6b0f', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões e Remuneração dos Testamentários', '## Sucessões e Remuneração dos Testamentários

A remuneração do testamenteiro é determinada pela vintena, mas não se aplica ao inventariante dativo. O artigo 1.987 do CC/2002 estabelece critérios de prévia precificação da remuneração a ser paga ao testamenteiro.

### Conceitos
- **Testamenteiro**: Pessoa responsável por executar o testamento
- **Inventariante dativo**: Pessoa nomeada para realizar o inventário da herança, geralmente sem relação de confiança com o autor da herança
- **Remuneração**: Indenização paga ao testamenteiro ou inventariante dativo por seus serviços
- **Vintena**: Unidade de medida para a remuneração do testamenteiro

### Referências legais
- Art. 1.987 CC/2002
- Súmula 208 STJ

### Jurisprudência
- RE 646.721 e 878.694 STF
- REsp 1.332.773-MS STJ

### Dicas de prova
- Diferenciar entre testamenteiro e inventariante dativo
- Entender a aplicação da vintena na remuneração do testamenteiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.579 (1)", "page_number": 579, "discipline": "Direito Civil", "legal_refs": ["Art. 1.987 CC/2002", "Súmula 208 STJ"], "jurisprudence": ["RE 646.721 e 878.694 STF", "REsp 1.332.773-MS STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:11:55.430295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=579", "doc_key": "181bba95c2658b962007737fd4ea6b0f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '54e3d26f05efc73fe874c242bb9a546dba9d382cbfcb8386a660eca5a97034e3'),
  ('cpiuris2025::9ca58426491d32f64b09c6da034014cb', 'doutrina', 'cp_iuris', 'Direito Civil — Legitimidade e Herança', '## Legitimidade e Herança

A Quarta Turma do STF utilizou o REsp 1.337.420-RS para declarar a legitimidade dos parentes até o quarto grau não herdar antes do companheiro sobrevivente, tendo em vista a inconstitucionalidade da discriminação com a situação do cônjuge.

### Conceitos
- **Legitimidade**: O direito de uma pessoa para participar de um processo ou de uma relação jurídica
- **Herança**: A parte que lhe é destinada do patrimônio de um falecido, de acordo com as leis de herança
- **Cônjuge**: O companheiro de casamento
- **Parente colateral**: Um parente que não é cônjuge, mas que tem uma relação de parentesco com o falecido

### Referências legais
- Art. 1.838 e 1.839 do CC/02

### Jurisprudência
- REsp 1.337.420-RS
- REsp 1.357.117-MG
- REsp 1.989.894-SP

### Dicas de prova
- Entenda a noção de legitimidade e sua relação com a herança
- Conheça as regras de transmissão da herança
- Aprenda a distinguir entre cônjuge e parente colateral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.579 (2)", "page_number": 579, "discipline": "Direito Civil", "legal_refs": ["Art. 1.838 e 1.839 do CC/02"], "jurisprudence": ["REsp 1.337.420-RS", "REsp 1.357.117-MG", "REsp 1.989.894-SP"], "confidence": 0.8, "extracted_at": "2026-05-26T05:12:29.979977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=579", "doc_key": "9ca58426491d32f64b09c6da034014cb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '19d024a5796c244f120c32368a9f52d6f8e4ba6bb634c58004d7cc822ddf9d75'),
  ('cpiuris2025::8db87d46c6087803fa158c11057a6fe8', 'doutrina', 'cp_iuris', 'Direito Civil — Testamento e Sucessões', '## Testamento e Sucessões

O testamento não é nulo mesmo com cláusulas de inalienabilidade, incomunicabilidade e impenhorabilidade, pois a propriedade só pode ser transferida após a morte do titular. A disposição patrimonial em testamento somente se efetiva após o óbito do testador.

### Conceitos
- **Testamento**: Declaração de vontade do testador para dispor sobre sua propriedade após a morte.
- **Sucessões**: Procedimento legal que determina a transmissão dos bens deixados por uma pessoa falecida aos seus sucessores.
- **Inalienabilidade**: Impossibilidade de alienação da propriedade durante a vida do titular.
- **Incomunicabilidade**: Proibição de transferir ou onerar o bem sem consentimento do titular.
- **Impenhorabilidade**: Impossibilidade de penhora do bem em processo judicial.
- **Livre circulação dos bens**: Princípio que permite a livre transferência da propriedade de um bem para outro, sem restrições.
- **Saisine**: Direito de transmissão imediata dos bens ao falecido.

### Referências legais
- Art. 1.323 do Código Civil

### Jurisprudência
- REsp 1.641.549-RJ
- Tema repetitivo: Testamento e Sucessões

### Dicas de prova
- Entenda a diferença entre a disposição patrimonial em testamento e a alienação da propriedade durante a vida do titular.
- Conheça o princípio de livre circulação dos bens e sua aplicação no Direito Sucessório.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.580 (1)", "page_number": 580, "discipline": "Direito Civil", "legal_refs": ["Art. 1.323 do Código Civil"], "jurisprudence": ["REsp 1.641.549-RJ", "Tema repetitivo: Testamento e Sucessões"], "confidence": 0.8, "extracted_at": "2026-05-26T05:13:26.489379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=580", "doc_key": "8db87d46c6087803fa158c11057a6fe8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4cee028e6d75b1c23841829ce0e0c3d46072e5158447ae043081e1a42ce24afc'),
  ('cpiuris2025::b672d8f85789f22a38a36fe99628c270', 'doutrina', 'cp_iuris', 'Direito Civil — Inventário', '## Inventário

O inventário é um procedimento que administra os bens de uma pessoa falecida antes de sua distribuição entre os sucessores.

### Conceitos
- **Saisine**: Princípio que estabelece a imediata transmissão dos bens aos herdeiros
- **Inventariante**: Pessoa designada para administrar o espólio durante o inventário
- **Espólio**: Conjunto de bens que se forma com a morte de uma pessoa

### Referências legais
- Art. 1.991/CC
- Art. 75, VII, NCPC

### Dicas de prova
- Entenda o conceito de saisine e sua relação com a transmissão dos bens aos herdeiros
- Conheça a figura do inventariante e sua responsabilidade durante o inventário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.580 (2)", "page_number": 580, "discipline": "Direito Civil", "legal_refs": ["Art. 1.991/CC", "Art. 75, VII, NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:13:50.192977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=580", "doc_key": "b672d8f85789f22a38a36fe99628c270"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8944cc71d3604959d33daa33a4eb2e2da2d3b314c27b0b988002db290c2d2145'),
  ('cpiuris2025::3600608959eb5d455ed6eb897a57963a', 'doutrina', 'cp_iuris', 'Direito Civil — Inventário Judicial', '## Inventário Judicial

O inventário judicial é um procedimento que visa a administração do espólio de uma pessoa falecida. Ele pode ser realizado pelo rito sumário ou comum, e tem previsão na legislação processual civil.

### Conceitos
- **Inventário Judicial**: Procedimento que visa a administração do espólio de uma pessoa falecida
- **Rito Sumário**: Método mais rápido e simples para o inventário judicial
- **Rito Comum**: Método mais complexo e detalhado para o inventário judicial
- **Legitimados para requerer abertura do inventário**: Pessoas que têm direito a administrar o espólio, como cônjuge, herdeiro, legatário, etc.
- **Inventariante**: Pessoa responsável pela administração do espólio
- **Administrador Provisório**: Pessoa nomeada pelo juiz para administrar o espólio até que o inventariante preste compromisso
- **Reembolso de despesas**: Direito do administrador provisório a receber reembolso das despesas necessárias e úteis

### Referências legais
- Art. 615 NCPC
- Art. 616 NCPC

### Dicas de prova
- Entenda a diferença entre rito sumário e comum para o inventário judicial
- Identifique as pessoas legitimadas para requerer abertura do inventário
- Conheça a responsabilidade do inventariante e do administrador provisório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.581", "page_number": 581, "discipline": "Direito Civil", "legal_refs": ["Art. 615 NCPC", "Art. 616 NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:14:31.643579+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=581", "doc_key": "3600608959eb5d455ed6eb897a57963a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6fedf6ad4c13cfccadd73d116bbf1988bf6b1f187087d1677e58e1773acb6d14'),
  ('cpiuris2025::82d7917fcec03a36d886968138bf44b8', 'doutrina', 'cp_iuris', 'Direito Civil — Ordem de Nomeação do Inventariante', '## Ordem de Nomeação do Inventariante

A ordem estabelecida pelo legislador no artigo 617/NCPC é preferencial, mas o juiz pode nomear inventariante não observando essa ordem em casos concretos.

### Conceitos
- **Inventariança**: O processo de avaliação e gestão do patrimônio de um falecido.
- **Espólio**: A massa de bens que se forma após a morte de uma pessoa.
- **Herdeiro**: Pessoa que recebe parte do patrimônio de um falecido.
- **Inventariante**: A pessoa nomeada para avaliar e gerenciar o patrimônio de um falecido.
- **Cessionário**: Pessoa que cede direitos a outro.
- **Legatário**: Pessoa que recebe uma parte do patrimônio de um falecido.
- **Testamenteiro**: Pessoa nomeada para testificar sobre a vontade do falecido.
- **Juiz**: O magistrado responsável por julgar um caso

### Referências legais
- Art. 617/NCPC
- Art. 618/NCPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a ordem estabelecida pelo legislador e como o juiz pode nomear inventariante não observando essa ordem.
- Conheça as hipóteses em que se torna necessária a nomeação de inventariante dativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.582 (1)", "page_number": 582, "discipline": "Direito Civil", "legal_refs": ["Art. 617/NCPC", "Art. 618/NCPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T05:15:21.681792+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=582", "doc_key": "82d7917fcec03a36d886968138bf44b8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fca77273f6baa4e2e9812d8e326ae114fd01c8154e300052ae47b201f5892f86'),
  ('cpiuris2025::f8339fc16bd30b27380787b55bfa9203', 'doutrina', 'cp_iuris', 'Direito Civil — Duties do Herdeiro', '## Duties do Herdeiro

O herdeiro tem várias responsabilidades, incluindo representar o espólio, administrá-lo e prestar declarações sobre seus bens.

### Conceitos
- **Espólio**: A massa de bens de uma pessoa falecida
- **Herdeiro**: Pessoa que recebe os bens de um falecido
- **Inventariante dativo**: O herdeiro que faz o inventário do espólio

### Referências legais
- Art. 1.234 da CC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre as responsabilidades do herdeiro podem ser muito específicas, então prepare-se para analisar detalhes.
- O conceito de espólio é fundamental aqui.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.582 (2)", "page_number": 582, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 da CC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T05:15:42.609400+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=582", "doc_key": "f8339fc16bd30b27380787b55bfa9203"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3322f5e66ea816c5100b20dc645445b4e4ba236144d1c88ac785a3c103b34f81'),
  ('cpiuris2025::f6f3fe05840547649895018ec7532990', 'doutrina', 'cp_iuris', 'Direito Civil — Inventariação e Declarações no NCPC', '## Inventariação e Declarações no NCPC

O art. 619 do NCPC estabelece as incumbências do inventariante, que devem ser autorizadas judicialmente. O inventariante deve fazer declarações dentro de 20 dias, incluindo dados pessoais dos herdeiros e do inventariado, bem como uma relação completa dos bens do espólio.

### Conceitos
- **Inventariação**: O processo de identificação e valorização dos bens do espólio
- **Declarações no NCPC**: As declarações feitas pelo inventariante sobre os bens do espólio, que devem ser autorizadas judicialmente
- **Autorização Judicial**: A necessidade de autorização judicial para exercer certas atividades relacionadas à inventariação

### Referências legais
- Art. 619 do NCPC
- Art. 620 do NCPC

### Dicas de prova
- Perguntas sobre a importância da inventariação e declarações no NCPC
- Distinção entre bens do espólio e bens alheios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.583 (1)", "page_number": 583, "discipline": "Direito Civil", "legal_refs": ["Art. 619 do NCPC", "Art. 620 do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:16:14.886960+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=583", "doc_key": "f6f3fe05840547649895018ec7532990"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '82f823419e61d2055c73ce22da10d3d0eee5c7f821fcc3c74d77038fe2a3cf2a'),
  ('cpiuris2025::63abf43b3ab57c7a2bece0dae9b2d015', 'doutrina', 'cp_iuris', 'Direito Civil — Pena de sonegados no inventariamento', '## Pena de sonegados no inventariamento

A pena de sonegados é aplicada ao inventariante quando ele declara que não existem outros bens a serem inventariados, mas posteriormente se descobre que um bem foi omitido. O inventariante pode ser punido com essa pena se não for verificado que não há outros bens a serem inventariados.

### Conceitos
- **Pena de sonegados**: penalidade aplicada ao inventariante por declaração falsa sobre a existência de bens a serem inventariados
- **Inventariante**: parte responsável pela elaboração do inventário
- **Omissão**: falta de informação ou declaração falsa

### Referências legais
- NCPC

### Dicas de prova
- Perguntas sobre a aplicação da pena de sonegados podem ser respondidas com base na descrição do NCPC.
- É importante entender que a pena de sonegados é imposta ao inventariante por declaração falsa sobre a existência de bens a serem inventariados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.583 (2)", "page_number": 583, "discipline": "Direito Civil", "legal_refs": ["NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:16:51.224636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=583", "doc_key": "63abf43b3ab57c7a2bece0dae9b2d015"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f8313580b382103bd7519fa4dbf21dfd239a1ad7a77f32a858d3a90fac8f58fd'),
  ('cpiuris2025::303dd4d4ae54f284b695c1acc99ad92c', 'doutrina', 'cp_iuris', 'Direito Civil — Pena de Sonegados em Doações', '## Pena de Sonegados em Doações

A pena de sonegados é aplicada quando o herdeiro que recebeu uma doação não colaciona o bem, resultando na perda do direito em relação a esse bem.

### Conceitos
- **Pena de Sonegados**: perda do direito em relação a um bem
- **Doação**: transmissão gratuita de bens
- **Colação**: declaração obrigatória sobre o valor e natureza de um bem
- **Inventariante**: herdeiro responsável pela declaração dos bens do falecido

### Referências legais
- Art. 1.992 do Código Civil
- Art. 622 do NCPC

### Jurisprudência
- Súmula 209/STJ

### Dicas de prova
- Entenda a diferença entre colação e sonegados
- Conheça as hipóteses de remoção do inventariante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.584 (1)", "page_number": 584, "discipline": "Direito Civil", "legal_refs": ["Art. 1.992 do Código Civil", "Art. 622 do NCPC"], "jurisprudence": ["Súmula 209/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:17:20.047141+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=584", "doc_key": "303dd4d4ae54f284b695c1acc99ad92c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e960131b4d17a2cb74a4f0a9643084cde76abff9aa209e4c5c718001fc75afd8'),
  ('cpiuris2025::baa73e907c3e0dd34b2db85fbb5e6229', 'doutrina', 'cp_iuris', 'Direito Civil — Remoção do Inventariante', '## Remoção do Inventariante

O inventariante pode ser removido se não apresentar andamento regular, praticar atos protelatórios ou não defender o espólio nas ações em que for citado.

### Conceitos
- **Inventariante**: Pessoa responsável por fazer o inventário de bens do falecido
- **Remoção do Inventariante**: Ação tomada para substituir o inventariante que não está cumprindo suas obrigações
- **Contraditório**: Direito do inventariante de ser ouvido antes da remoção

### Referências legais
- Art. 623, NCPC; Art. 624, NCPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Garantir o contraditório é fundamental antes de remover o inventariante
- O juiz pode iniciar a remoção de ofício se houver suspeitas de irregularidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.584 (2)", "page_number": 584, "discipline": "Direito Civil", "legal_refs": ["Art. 623, NCPC; Art. 624, NCPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T05:17:44.656055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=584", "doc_key": "baa73e907c3e0dd34b2db85fbb5e6229"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e2f45ee8fe4415836a5dbf79b8f63801ecdffda7271b0521c11f99855f257420'),
  ('cpiuris2025::4e2c3b7bd6ad64c6a82485fd667e2516', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões - Fazenda Pública, Ministério Público e testamenteiro', '## Sucessões - Fazenda Pública, Ministério Público e testamenteiro

O escrivão deve remeter cópia dos autos para a Fazenda Pública, Ministério Público e testamenteiro, além do mandado de citação com as primeiras declarações. Em caso de impugnação com fundamento em omissão julgada procedente, o juiz retira as primeiras declarações.

### Conceitos
- **citação**: mandado formal para que uma pessoa seja convocada a comparecer em um processo
- **partilha**: divisão dos bens do falecido entre os herdeiros
- **inventário**: processo que determina a divisão dos bens de um falecido
- **herdeiro**: pessoa que recebe parte dos bens de um falecido

### Referências legais
- Art. 627, §2º, NCPC

### Dicas de prova
- Entenda a importância da citação em processos de sucessões
- Conheça as regras para a partilha e o inventário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.585 (1)", "page_number": 585, "discipline": "Direito Civil", "legal_refs": ["Art. 627, §2º, NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:18:26.391756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=585", "doc_key": "4e2c3b7bd6ad64c6a82485fd667e2516"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8cfd713c7d97038953ef038688af2ff0f3dd2c4fd6f297e61ccd763db84d085a'),
  ('cpiuris2025::3456f807c77dc60800b718135327a128', 'doutrina', 'cp_iuris', 'Direito Civil — Procedimento em Demandas Imobiliárias', '## Procedimento em Demandas Imobiliárias

Regras para comprovação documental de plano e remessa de questões complexas a outro juízo.

### Conceitos
- **Art. 612 do NCPC**: Preve que o juiz decidirá questões de direito desde que os fatos relevantes estejam provados por documento.
- **Art. 627 do NCPC**: Estabelece prazo para manifestação acerca das primeiras declarações da Fazenda Pública.
- **Art. 629 do NCPC**: Determina que a Fazenda Pública informará ao juízo o valor dos bens de raiz descritos nas primeiras declarações.
- **Perito judicial**: É nomeado para avaliar os bens do espólio, com fé pública que justifica a não necessidade de reavaliação.

### Referências legais
- Art. 612 do NCPC
- Art. 627 do NCPC
- Art. 629 do NCPC
- Art. 873 do NCPC

### Dicas de prova
- Entenda a importância da comprovação documental de plano em demandas imobiliárias.
- Conheça as regras para remessa de questões complexas a outro juízo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.585 (2)", "page_number": 585, "discipline": "Direito Civil", "legal_refs": ["Art. 612 do NCPC", "Art. 627 do NCPC", "Art. 629 do NCPC", "Art. 873 do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:18:58.642266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=585", "doc_key": "3456f807c77dc60800b718135327a128"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1b6861e4447b0c2bbd956092d960da9cb342c5c5f98c4c33312396bbf03ba858'),
  ('cpiuris2025::b45ef17ebe1aad28c050f229e10f4197', 'doutrina', 'cp_iuris', 'Direito Civil — Avaliação no Inventário', '## Avaliação no Inventário

Regra para nova avaliação em inventário: erro na avaliação, dolo do avaliador, majoração ou diminuição do valor do bem, ou fundada dúvida do juiz sobre o valor atribuído ao bem.

### Conceitos
- **Avaliação**: Processo de determinação do valor dos bens do espólio
- **Dolo**: Ação dolosa cometida pelo avaliador que pode justificar a nova avaliação
- **Erro**: Materiais ou formais erros cometidos pelo avaliador que podem justificar a nova avaliação

### Referências legais
- Art. 873
- Art. 632
- Art. 633
- Art. 635
- Art. 659

### Dicas de prova
- Distinção entre erro, dolo e majoração/diminuição do valor do bem
- Importância da manifestação das partes sobre o laudo do perito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.586 (1)", "page_number": 586, "discipline": "Direito Civil", "legal_refs": ["Art. 873", "Art. 632", "Art. 633", "Art. 635", "Art. 659"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:19:26.799841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=586", "doc_key": "b45ef17ebe1aad28c050f229e10f4197"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a67544a6f6089317f82ae195bf24dbee90f74a77715533b5d8ec5714160a0ecc'),
  ('cpiuris2025::090534c61b17d49dc6be0f8ee330fe3a', 'doutrina', 'cp_iuris', 'Direito Civil — Partilha de Bens', '## Partilha de Bens

Procedimento judicial simplificado para partilha de bens entre herdeiros capazes e que concordam em transigir.

### Conceitos
- **Partilha**: Divisão dos bens do falecido entre os herdeiros
- **Capacidade plena**: Condição necessária para a partilha
- **Transigir**: Acordar com as partes envolvidas sobre a partilha dos bens

### Referências legais
- Art. 1.031 do CPC
- Art. 1.035 do CPC

### Jurisprudência
- Tartuce, 2020; Dimas Messias de Carvalho e Dimas Daniel de Carvalho

### Dicas de prova
- Entenda a capacidade plena e a transigir como condições para a partilha
- Conheça as regras do procedimento judicial simplificado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.586 (2)", "page_number": 586, "discipline": "Direito Civil", "legal_refs": ["Art. 1.031 do CPC", "Art. 1.035 do CPC"], "jurisprudence": ["Tartuce, 2020; Dimas Messias de Carvalho e Dimas Daniel de Carvalho"], "confidence": 0.8, "extracted_at": "2026-05-26T05:19:59.440253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=586", "doc_key": "090534c61b17d49dc6be0f8ee330fe3a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e1c89ca1d5e0c08eade21e2b994e60b02fecab3e6f05e9c75a6c3f87f4006d4c'),
  ('cpiuris2025::01a76ab23a4e6243d2837f8ce1e25fed', 'doutrina', 'cp_iuris', 'Direito Civil — Procedimento de Inventário', '## Procedimento de Inventário

O procedimento de inventário é voluntário e tem como objetivo a celeridade, com o formal de partilha ou carta de adjudicação antecedendo o recolhimento do tributo. Não são apreciadas questões relativas ao lançamento, pagamento e quitação de taxas judiciais e tributos.

### Conceitos
- **Arrolamento sumário**: Procedimento de inventário que tem como objetivo a celeridade
- **Taxa judiciária**: Taxa cobrada pela justiça por causa do processo
- **ITCMD**: Instrumento de Transferência e Compensação de Medidas Fiscais

### Referências legais
- Art. 663 do NCPC
- Art. 664 do NCPC

### Dicas de prova
- Entenda a diferença entre arrolamento sumário e comum.
- Conheça o valor dos bens que integram o espólio em cada tipo de inventário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.587 (1)", "page_number": 587, "discipline": "Direito Civil", "legal_refs": ["Art. 663 do NCPC", "Art. 664 do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:20:28.476395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=587", "doc_key": "01a76ab23a4e6243d2837f8ce1e25fed"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8cde04c25a6563807c5ad66e4e85138cdbc478364d1e2d9e89053a078a09eb4d'),
  ('cpiuris2025::05d88902add72ba9760bbbc032858e78', 'doutrina', 'cp_iuris', 'Direito Civil — Arrolamento de Bens e Partilha no Inventário', '## Arrolamento de Bens e Partilha no Inventário

Regra sobre a nomeação de avaliador em arrolamento de bens, procedimento para a partilha após o laudo do avaliador e diferença com o arrolamento sumário.

### Conceitos
- **Avaliação de Bens**: Processo de determinação do valor dos bens no inventário
- **Arrolamento Sumário**: Tipo de arrolamento mais rápido, mas com menos precisão
- **Partilha**: Divisão dos bens entre as partes ou herdeiros
- **Audiência**: Reunião do juiz e das partes para deliberar sobre a partilha
- **Quitação de Tributos**: Prazo para pagamento de tributos relativos aos bens do espólio

### Referências legais
- Art. 664, §2º, NCPC

### Dicas de prova
- Diferença entre arrolamento de bens e sumário
- Importância da nomeação de avaliador
- Procedimento para a partilha após o laudo do avaliador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.587 (2)", "page_number": 587, "discipline": "Direito Civil", "legal_refs": ["Art. 664, §2º, NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:20:56.102220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=587", "doc_key": "05d88902add72ba9760bbbc032858e78"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '258a993b931e5d3a2b40be9403477d768748b624ee8364d039029067a8cccb91'),
  ('cpiuris2025::6e4120ae2d8b74beb26793ee81a63938', 'doutrina', 'cp_iuris', 'Direito Civil — Arrolamento em Sucessões', '## Arrolamento em Sucessões

O arrolamento comum é permitido quando os valores dos bens não superam mil salários-mínimos e todos os herdeiros estão de acordo, mesmo que haja incapazes. O inventário extrajudicial é estabelecido quando não há testamento e todos os herdeiros são capazes e concordes.

### Conceitos
- **Arrolamento Sumário**: considera o consenso entre os herdeiros e interessados
- **Arrolamento Comum**: leva em conta o valor dos bens inventariados
- **Inventário Extrajudicial**: estabelecido quando não há testamento e todos os herdeiros são capazes e concordes
- **Capacidade Hereditária**: requisito para que um herdeiro possa participar do inventário
- **Advogado**: necessário para a elaboração da escritura pública de inventário

### Referências legais
- Art. 665, NCPC

### Jurisprudência
- REsp nº 1808767 / RJ
- Súmula 663/STJ

### Dicas de prova
- Diferenciar entre arrolamento sumário e comum
- Entender a importância da capacidade hereditária
- Conhecer as exigências para o inventário extrajudicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.588", "page_number": 588, "discipline": "Direito Civil", "legal_refs": ["Art. 665, NCPC"], "jurisprudence": ["REsp nº 1808767 / RJ", "Súmula 663/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:21:42.747217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=588", "doc_key": "6e4120ae2d8b74beb26793ee81a63938"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'dae4a0f57ec5d6744e482877f058fdb2072c84325a929fec4c267707fbe541f0'),
  ('cpiuris2025::703341212fc6859277f06c9e3b4a5a81', 'doutrina', 'cp_iuris', 'Direito Civil — Resolução 35 do CNJ - Sucessões', '## Resolução 35 do CNJ - Sucessões

A Resolução 35 do CNJ estabelece regras para a realização de inventários extrajudiciais, incluindo a nomeação de um interessado para representar o espólio e a obrigatoriedade da homologação judicial para os títulos produzidos.

### Conceitos
- **Inventário Extrajudicial**: Procedimento que não requer a intervenção do Poder Judiciário
- **Tabelião**: Profissional responsável por lavrar o inventário
- **Multa na Legislação Tributária**: Pena imposta pela legislação tributária em caso de não pagamento de impostos
- **Homologação Judicial**: Ação do Poder Judiciário para validar os títulos produzidos no inventário
- **Itcmed**: Imposto sobre a Renda de Mineração e Energia

### Referências legais
- Art. 1º da Resolução 35 do CNJ
- Art. 11 da Resolução 35 do CNJ
- Art. 15 da Resolução 35 do CNJ

### Dicas de prova
- Entenda a diferença entre inventário judicial e extrajudicial
- Conheça as regras para a nomeação de um interessado para representar o espólio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.589 (1)", "page_number": 589, "discipline": "Direito Civil", "legal_refs": ["Art. 1º da Resolução 35 do CNJ", "Art. 11 da Resolução 35 do CNJ", "Art. 15 da Resolução 35 do CNJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:22:20.437910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=589", "doc_key": "703341212fc6859277f06c9e3b4a5a81"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '98e5ba9831f077acbd6ec2dddda335f61689db3897e52bf395265ad486a31e4e'),
  ('cpiuris2025::33c3fa5501fdfa23eb6bcaadd20aa3b6', 'doutrina', 'cp_iuris', 'Direito Civil — Ouro Partilha e Inventário', '## Ouro Partilha e Inventário

A sobrepartilha é admissível após a partilha realizada. O único herdeiro maior e capaz tem direito à totalidade da herança, sem necessidade de partilha. Um inventário negativo pode ser útil para o casamento do cônjuge sobrevivente.

### Conceitos
- **Partilha**: Divisão dos bens deixados por um falecido
- **Inventário**: Processo que determina a divisão dos bens deixados por um falecido
- **Ouro Partilha**: Sobrepartilha, ou seja, partilha após a partilha realizada
- **Inventário Negativo**: Inventário que demonstra que o falecido não deixou qualquer bem

### Referências legais
- Art. 25
- Art. 26
- Art. 28
- Art. 1.523, I, do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre partilha e sobrepartilha
- Conhecimento de artigos do CC e da Resolução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.589 (2)", "page_number": 589, "discipline": "Direito Civil", "legal_refs": ["Art. 25", "Art. 26", "Art. 28", "Art. 1.523, I, do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T05:22:49.542952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=589", "doc_key": "33c3fa5501fdfa23eb6bcaadd20aa3b6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f66eadbf3803bd3c844a3108f88543f58846d24dfd7e57cb7bd898a69ffb62d4'),
  ('cpiuris2025::f2d4332ced844ef0441007860f02a768', 'doutrina', 'cp_iuris', 'Direito Civil — Pena de Sonegados', '## Pena de Sonegados

A pena de sonegados é aplicada ao herdeiro que oculta bens da herança, não os descrevendo no inventário ou os omitindo da colação. A perda do direito sobre o bem é a consequência da pena.

### Conceitos
- **Pena de Sonegados**: Sanção civil imposta para casos de ocultação de bens da herança
- **Ocultar**: Elemento objetivo da pena de sonegados, que é a ação de esconder um bem
- **Dolo**: Elemento subjetivo da pena de sonegados, que é a intenção de não contar aos demais herdeiros que não há o bem
- **Inventário**: Documento que lista os bens da herança e deve ser apresentado ao juízo
- **Colação**: Ação de apresentar os bens da herança ao juízo

### Referências legais
- Art. 1.641, I, CC
- Art. 1.992, CC

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre ocultar e dolo
- Conheça o conceito de inventário e colação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.590 (1)", "page_number": 590, "discipline": "Direito Civil", "legal_refs": ["Art. 1.641, I, CC", "Art. 1.992, CC"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T05:23:35.265754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=590", "doc_key": "f2d4332ced844ef0441007860f02a768"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9051473ca2c5875ca129c9bc04ad3c486d158157d47c7566a2d615889a899835'),
  ('cpiuris2025::ab5923c59b885f9ef90d6decad7b4b19', 'doutrina', 'cp_iuris', 'Direito Civil — Sonegação no Inventário', '## Sonegação no Inventário

O inventariante pode ser punido com pena de sonegados se ocultar bens, sendo removido da inventariança. A ação movida pelos herdeiros ou credores pode aproveitar para outros interessados.

### Conceitos
- **Sonegação**: ocultação dolosa de bens no inventário
- **Pena de Sonegados**: remoção do inventariante da inventariança
- **Ação movida pelos herdeiros ou credores**: ação que aproveita para outros interessados
- **Perdas e Danos**: valor dos bens ocultados mais danos causados

### Referências legais
- Art. 1.993 CC
- Art. 1.994 CC
- Art. 1.995 CC

### Dicas de prova
- Distinção entre sonegação e ocultação dolosa
- Importância da ação movida pelos herdeiros ou credores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.590 (2)", "page_number": 590, "discipline": "Direito Civil", "legal_refs": ["Art. 1.993 CC", "Art. 1.994 CC", "Art. 1.995 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:23:58.683394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=590", "doc_key": "ab5923c59b885f9ef90d6decad7b4b19"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8ed4fefca37da3c6dc39271c41987abf040c5d185579d7830f3ec943d8eb32f4'),
  ('cpiuris2025::cdcec35301490cc3e93381bf01244c51', 'doutrina', 'cp_iuris', 'Direito Civil — Pagamento das dívidas após a morte do autor da herança', '## Pagamento das dívidas após a morte do autor da herança

A herança responde pelo pagamento das dívidas do falecido, mas os herdeiros só respondem em proporção à parte que lhes coube. Em caso de impugnação ao pagamento, o juiz pode reservar bens suficientes para solução do débito.

### Conceitos
- **herança**: bens deixados por um falecido
- **dívidas do falecido**: obrigações contratuais ou de outra natureza que o autor da herança havia contraído
- **partilha**: divisão dos bens em herança entre os herdeiros
- **responsabilidade dos herdeiros**: cada herdeiro responde pelas dívidas do falecido em proporção à parte que lhes coube na herança
- **reserva de bens**: ordem do juiz para que um bem seja usado para pagamento das dívidas
- **pedido de habilitação de crédito**: solicitação do credor para ser considerado herdeiro e responder pelas dívidas do falecido

### Referências legais
- Art. 1.997, CC
- Art. 642, NCPC

### Dicas de prova
- Distinção entre responsabilidade dos herdeiros e reserva de bens
- Importância da partilha na divisão das dívidas do falecido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.591 (1)", "page_number": 591, "discipline": "Direito Civil", "legal_refs": ["Art. 1.997, CC", "Art. 642, NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:24:36.199012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=591", "doc_key": "cdcec35301490cc3e93381bf01244c51"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '41456714a896d10c5f001b182bc346153d6d3a988ef510d9f8cac0fc62d25fc1'),
  ('cpiuris2025::b43ad2241175faa3261274d5be63dae8', 'doutrina', 'cp_iuris', 'Direito Civil — Pagamento de dívidas em herança', '## Pagamento de dívidas em herança

O juiz determina a reserva de bens suficientes para pagar credores. O legatário pode se manifestar sobre dívidas do espólio, aplicando-se a mesma lógica que ao donatário.

### Conceitos
- **herança**: bens deixados por um autor de testamento
- **legado**: parte dos bens deixados por um autor de testamento
- **credor**: pessoa que tem direito a receber uma dívida
- **inventariante**: pessoa responsável pela inventariação de bens

### Referências legais
- Art. 645, NCPC; Art. 646, NCPC

### Dicas de prova
- Entenda a lógica aplicada ao pagamento de dívidas em herança
- Conheça as condições para o legatário se manifestar sobre dívidas do espólio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.591 (2)", "page_number": 591, "discipline": "Direito Civil", "legal_refs": ["Art. 645, NCPC; Art. 646, NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:25:10.563907+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=591", "doc_key": "b43ad2241175faa3261274d5be63dae8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b9b80874aac7bc6896241ab3358cd0a4601a817a8c719ef7c20abfbdaddc17e0'),
  ('cpiuris2025::bd8d569bd89dd2b4e71696d4380ba790', 'doutrina', 'cp_iuris', 'Direito Civil — Colação de Doações', '## Colação de Doações

A colação é o ato pelo qual o descendente confere o valor das doações recebidas em vida ao autor da herança, com a finalidade de igualar as legítimas. A colação ou conferência são expressões sinônimas.

### Conceitos
- **Colação**: Ato pelo qual o descendente confere o valor das doações recebidas em vida ao autor da herança
- **Conferência**: Expressão sinônima de colação
- **Doação**: Adiantamento do que lhe cabe por herança

### Referências legais
- Art. 544 CC
- Art. 2.002 CC
- Art. 2005 CC

### Dicas de prova
- Entenda a diferença entre colação e conferência
- Conheça o artigo 544 do CC e sua relação com as doações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.592 (1)", "page_number": 592, "discipline": "Direito Civil", "legal_refs": ["Art. 544 CC", "Art. 2.002 CC", "Art. 2005 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:25:37.168790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=592", "doc_key": "bd8d569bd89dd2b4e71696d4380ba790"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a98cd62a367b2affdf44e7f864f07506e16b515dc7f8af47971ea9000f84b1ee'),
  ('cpiuris2025::261a3d3b47b09758d4e361b864ec5e0b', 'doutrina', 'cp_iuris', 'Direito Civil — Coisa doada em adiantamento da legítima', '## Coisa doada em adiantamento da legítima

A coisa doada deve ser trazida à colação como adiantamento da legítima ao descendente e ao cônjuge. Se não houver bens suficientes, a coisa será conferida em espécie ou seu valor correspondente será trazido à colação.

### Conceitos
- **Coisa doada**: Bem que é objeto de herança
- **Adiantamento da legítima**: Direito ao qual o descendente ou cônjuge tem direito
- **Colação à colação**: Declarar a coisa doada como pertencente ao herdeiro

### Referências legais
- Art. 544 do Código Civil
- Art. 2.003, parágrafo único, segunda parte do Código Civil

### Jurisprudência
- TJSP, Ap. 530.150-4/9-00
- RT 697: 154

### Dicas de prova
- Entenda a diferença entre colação à colação e valor correspondente
- Conheça as hipóteses em que a coisa doada deve ser trazida à colação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.592 (2)", "page_number": 592, "discipline": "Direito Civil", "legal_refs": ["Art. 544 do Código Civil", "Art. 2.003, parágrafo único, segunda parte do Código Civil"], "jurisprudence": ["TJSP, Ap. 530.150-4/9-00", "RT 697: 154"], "confidence": 0.8, "extracted_at": "2026-05-26T05:26:03.887056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=592", "doc_key": "261a3d3b47b09758d4e361b864ec5e0b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e5674f778507f9ed74077450f7f50f79c0a384757aa8aa85865ff5640452ee15'),
  ('cpiuris2025::5a141a7919661209249d70d189b6b947', 'doutrina', 'cp_iuris', 'Direito Civil — Cálculo da Legítima em Sucessões', '## Cálculo da Legítima em Sucessões

O parágrafo único do artigo 2.002 estabelece que o valor dos bens conferidos será computado na parte indisponível, sem aumentar a disponível. O artigo 2.003 determina que os bens doados serão conferidos em espécie ou pelo seu valor ao tempo da liberalidade, caso não haja bens suficientes.

### Conceitos
- **Legítima**: direito de herdeiro à parte do patrimônio do autor da sucessão
- **Parte indisponível**: valor dos bens que não podem ser alienados sem a anuência do herdeiro
- **Parte disponível**: valor dos bens que podem ser alienados sem a anuência do herdeiro
- **Colação**: attribution de valor aos bens doados

### Referências legais
- Art. 2.002 CC
- Art. 2.003 CC
- Parágrafo único do Art. 627 NCPC

### Jurisprudência
- Enunciado 119 CJF

### Dicas de prova
- Entenda a diferença entre parte indisponível e disponível
- Conheça o conceito de colação e sua importância na sucessão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.593 (1)", "page_number": 593, "discipline": "Direito Civil", "legal_refs": ["Art. 2.002 CC", "Art. 2.003 CC", "Parágrafo único do Art. 627 NCPC"], "jurisprudence": ["Enunciado 119 CJF"], "confidence": 0.8, "extracted_at": "2026-05-26T05:26:48.901928+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=593", "doc_key": "5a141a7919661209249d70d189b6b947"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a90be70ce7504e98fb15d7f0b60acbc3f33be2cf7eea25ec6d3b8d8d34637f61'),
  ('cpiuris2025::4a26b430c3ad6ebf9c6dba3ae054bdf6', 'doutrina', 'cp_iuris', 'Direito Civil — Colação de bens doado em sucessão', '## Colação de bens doado em sucessão

A colação de bens doado em sucessão ocorre exclusivamente quando o bem não mais pertence ao patrimônio do donatário, sendo feita com base no valor do bem na época da abertura da sucessão.

### Conceitos
- **Colação**: processo pelo qual se determina a quantia que deve ser incluída no patrimônio do donatário
- **Sucessão**: ocorrência de morte de um dos côproprios, resultando na transferência de seus bens para os demais
- **Legítima**: direito do herdeiro ou do legatário de receber uma parte igual das possões herdadas

### Referências legais
- Art. 2.004 do CC/2016
- Art. 1.014 do CPC/2015
- Art. 639 do CPC/2015

### Dicas de prova
- Entenda a diferença entre colação e inclusão de bens no patrimônio do donatário
- Conheça as regras para determinar o valor do bem na época da abertura da sucessão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.593 (2)", "page_number": 593, "discipline": "Direito Civil", "legal_refs": ["Art. 2.004 do CC/2016", "Art. 1.014 do CPC/2015", "Art. 639 do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:27:18.659865+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=593", "doc_key": "4a26b430c3ad6ebf9c6dba3ae054bdf6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7a3103f3fdcd101059db3d420881f6961bf797b7f7ce77ca8768e60135425418'),
  ('cpiuris2025::44994604d851ad514b78f345362d1349', 'doutrina', 'cp_iuris', 'Direito Civil — Colação e Redução de Doações Inoficiosas', '## Colação e Redução de Doações Inoficiosas

A colação é obrigatória quando o bem doado é possuído pelo tempo da alienação, atualizado monetariamente. A redução de doações inoficiosas ocorre quando a disposição excede a legítima e é estabelecida pelo art. 549 do CC.

### Conceitos
- **Colação**: Obrigatória quando o bem doado é possuído pelo tempo da alienação, atualizado monetariamente
- **Redução de Doações Inoficiosas**: Ocorre quando a disposição excede a legítima e é estabelecida pelo art. 549 do CC
- **Legítima**: Parte disponível dos bens hereditários, protegida pela lei
- **Doação Inoficiosa**: Doação que excede a parte disponível da legítima

### Referências legais
- Art. 549 do CC
- Art. 2.007, §1º e §2º do CC
- Art. 2009 do CC

### Dicas de prova
- Diferença entre colação e redução de doações inoficiosas
- Importância da legítima na redução de doações inoficiosas
- Regras sobre a restituição do excesso apurado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.594 (1)", "page_number": 594, "discipline": "Direito Civil", "legal_refs": ["Art. 549 do CC", "Art. 2.007, §1º e §2º do CC", "Art. 2009 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:27:55.380114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=594", "doc_key": "44994604d851ad514b78f345362d1349"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e691c319e7d8bfd491706a33973233ce84d4f23af2878445664e0e2f4d9c7044'),
  ('cpiuris2025::3ed0416baad2c2e1d1a47edfbdc68db0', 'doutrina', 'cp_iuris', 'Direito Civil — Partilha', '## Partilha

A partilha é a divisão dos bens hereditários, transformando o acervo em coisas particulares devidamente divididas.

### Conceitos
- **Partilha**: Divisão dos bens hereditários
- **Art. 2.013 CC**: Faculdade do herdeiro de requerer a partilha
- **Partilha Amigável**: Repartição dos bens com acordo entre as partes
- **Partilha Judicial**: Repartição dos bens mediante decisão judicial
- **Partilha em Vida**: Repartição dos bens durante a vida do testador

### Referências legais
- Art. 2.013 CC

### Dicas de prova
- Entenda a diferença entre partilha amigável e judicial
- Conheça a faculdade do herdeiro de requerer a partilha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.594 (2)", "page_number": 594, "discipline": "Direito Civil", "legal_refs": ["Art. 2.013 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:28:31.275194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=594", "doc_key": "3ed0416baad2c2e1d1a47edfbdc68db0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '58885f0899bf49850efae7c3c5b89074cf66418652785e48542a95311649b085'),
  ('cpiuris2025::d79cd3da580c384d2718033cf3e514d9', 'doutrina', 'cp_iuris', 'Direito Civil — Partilha nos Testamentos', '## Partilha nos Testamentos

A partilha nos testamentos pode ocorrer de forma amigável ou judicial, dependendo da concordância dos herdeiros. A partilha amigável é realizada por escritura pública, termo nos autos do inventário ou termo particular homologado pelo juiz. A partilha judicial é necessária em casos de divergência entre os herdeiros ou quando houver herdeiros incapazes, e segue regras específicas para garantir a igualdade da divisão.

### Conceitos
- **Partilha Amigável**: Ocorre quando todos os herdeiros estão de acordo com a divisão dos bens.
- **Partilha Judicial**: Necessária em casos de divergência entre os herdeiros ou quando houver herdeiros incapazes
- **Princípio da Igualdade**: Busca o máximo possível de igualdade na divisão, considerando valor e natureza dos bens.
- **Prevenção de Litígios Futuros**: Mediação ou conciliação para facilitar a partilha
- **Máxima Comodidade**: A divisão dos bens deve ser feita de forma cômoda, especialmente se o bem for susceptível de uma divisão cômoda.

### Referências legais
- Art. 648 do NCPC

### Dicas de prova
- Destacar a importância do princípio da igualdade na partilha judicial
- Entender a diferença entre partilha amigável e judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.595 (1)", "page_number": 595, "discipline": "Direito Civil", "legal_refs": ["Art. 648 do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:29:11.504037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=595", "doc_key": "d79cd3da580c384d2718033cf3e514d9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '41ffa3f7cf38aaa3f34a7c997d2e0d3dd5aeb2d2fc6410fab50f0ea817a40f2e'),
  ('cpiuris2025::d55ef884e8112d1dc59a4e76d65f34a7', 'doutrina', 'cp_iuris', 'Direito Civil — Partilha de Bens', '## Partilha de Bens

A partilha de bens ocorre quando não há divisão cômoda, sendo os bens vendidos e os valores compartilhados entre os interessados. O artigo 650 do NCPC estabelece a proteção dos direitos do nascituro.

### Conceitos
- **Partilha de Bens**: ocorre quando não há divisão cômoda
- **Nascituro**: pessoa que nasceu após a morte de um dos pais, com direitos preservados
- **Condomínio**: situação em que o bem é atribuído a todos os interessados
- **Inventariante**: pessoa responsável pela partilha de bens

### Referências legais
- Art. 650 do NCPC
- Art. 661 do NCPC
- Art. 651 do NCPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre divisão cômoda e partilha de bens.
- Conheça a proteção dos direitos do nascituro
- Identifique o papel do inventariante na partilha de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.595 (2)", "page_number": 595, "discipline": "Direito Civil", "legal_refs": ["Art. 650 do NCPC", "Art. 661 do NCPC", "Art. 651 do NCPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T05:29:40.790559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=595", "doc_key": "d55ef884e8112d1dc59a4e76d65f34a7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '823452c4d1f24d6917e2b9198b8fd66bb878675a21305cc948dd0a201e647629'),
  ('cpiuris2025::712334f1152fe2f4db511e319b76b0a0', 'doutrina', 'cp_iuris', 'Direito Civil — Partilha em Vida', '## Partilha em Vida

A partilha em vida é uma forma de partilha feita pelo ascendente para os descendentes, podendo ser total ou parcial, desde que respeitados os parâmetros legais.

### Conceitos
- **Partilha em Vida**: Forma de partilha feita pelo ascendente a descendentes
- **Atos Inter Vivos**: Ações realizadas durante a vida do indivíduo
- **Doação**: Transferência gratuita de bens por um indivíduo para outro
- **Partilha-Doação**: Forma de partilha em vida que equivale a uma doação
- **Partilha-Testamento**: Forma de partilha feita no ato mortis causa, que só produz efeitos com a morte do ascendente

### Referências legais
- Art. 2.018 CC/02
- Art. 664 NCPC

### Jurisprudência
- TARTUCE, 2020, p. 2.446

### Dicas de prova
- Diferenciar entre partilha em vida e partilha-testamento
- Entender a classificação de Flávio Tartuce sobre a partilha em vida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.596 (1)", "page_number": 596, "discipline": "Direito Civil", "legal_refs": ["Art. 2.018 CC/02", "Art. 664 NCPC"], "jurisprudence": ["TARTUCE, 2020, p. 2.446"], "confidence": 0.8, "extracted_at": "2026-05-26T05:30:25.948357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=596", "doc_key": "712334f1152fe2f4db511e319b76b0a0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9340028fc1004a38827ad7b6a56ca57631598b2f905123370e76d22c2e0b6b24'),
  ('cpiuris2025::575046cfcf3c120ed2279f8b015e50c7', 'doutrina', 'cp_iuris', 'Direito Civil — Previdência Privada Complementar Aberta', '## Previdência Privada Complementar Aberta

Regra que a previdência privada complementar aberta tem natureza personalíssima e equiparável à pensão mensal decorrente de seguro por invalidez.

### Conceitos
- **Previdência Privada Complementar Aberta**: Sistema de previsão de aposentadoria para trabalhadores que não têm direito a um regime de previdência pública.
- **Natureza Personalíssima**: Característica que impede a comunicação com o cônjuge durante o vínculo conjugal.
- **Equiparável**: Término utilizado para descrever a semelhança entre duas coisas, nesse caso, a pensão mensal decorrente de seguro por invalidez.
- **Pensão Mensal Decorrente de Seguro Por Invalidez**: Benefício pago ao segurado que sofreu lesão ou doença que o torna incapaz de trabalho.
- **Seguro Por Invalidez**: Contrato pelo qual a empresa assume a responsabilidade por pagar pensões aos trabalhadores que se tornam incapazes de trabalho devido a acidente ou doença.

### Referências legais
- Art. 1.659, VII do CC/2002

### Jurisprudência
- REsp 1.477.937/MG
- Súmula 395/STJ

### Dicas de prova
- Entenda a natureza personalíssima da previdência privada complementar aberta.
- Conheça a semelhança entre a pensão mensal decorrente de seguro por invalidez e a previdência privada complementar aberta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.596 (2)", "page_number": 596, "discipline": "Direito Civil", "legal_refs": ["Art. 1.659, VII do CC/2002"], "jurisprudence": ["REsp 1.477.937/MG", "Súmula 395/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:31:00.387347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=596", "doc_key": "575046cfcf3c120ed2279f8b015e50c7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '069b65fab84c78acef26faf6842f8124f2e82ab2d2309c2afc8957c9076e2ca7'),
  ('cpiuris2025::e32ec16c0eb210a56b4a3098077d1f2e', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões e Previdência Privada', '## Sucessões e Previdência Privada

O texto discute a previdência privada aberta, regime de capitalização e partilha de bens em sucessão. Além disso, analisa as regras de garantia dos quinhões hereditários e a obrigação de indenização dos co-herdeiros.

### Conceitos
- **Previdência Privada**: Operação de seguradora autorizada pela SUSEP
- **Regime de Capitalização**: Modo de investimento com liberdade e flexibilidade para o investidor
- **Partilha de Bens**: Divisão dos bens hereditários entre os co-herdeiros
- **Quinhões Hereditários**: Proporção de cada herdeiro no patrimônio da herança
- **Evicção**: Ocorrência de algo que não faz parte do patrimônio da herança

### Referências legais
- Art. 1.659, VII, CC/2002; Art. 2.023, CC; Art. 2.024, CC; Art. 2.025, CC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre previdência privada aberta e fechada
- Conheça as regras de partilha de bens em sucessão e garantia dos quinhões hereditários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.597 (1)", "page_number": 597, "discipline": "Direito Civil", "legal_refs": ["Art. 1.659, VII, CC/2002; Art. 2.023, CC; Art. 2.024, CC; Art. 2.025, CC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T05:31:37.332482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=597", "doc_key": "e32ec16c0eb210a56b4a3098077d1f2e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1fc4608a0817b16bbba59662f82f22c90bba6bd704a4ae6b19f6089d150cc972'),
  ('cpiuris2025::2cafbef7448f3c33e4b1d4f109af7c18', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade dos Herdeiros', '## Responsabilidade dos Herdeiros

Acordo entre herdeiros sobre exclusão da responsabilidade por perda de bens, incluindo casos de culpa exclusiva ou fato posterior à partilha.

### Conceitos
- **Responsabilidade dos Herdeiros**: Obrigação dos herdeiros de compensar a perda de bens recebidos
- **Acordo entre herdeiros**: Concordância entre os herdeiros sobre exclusão da responsabilidade por perda de bens
- **Culpa exclusiva**: Obrigação de um dos herdeiros de compensar a perda de bens devido à sua própria negligência ou imprudência
- **Fato posterior à partilha**: Perda de bens que ocorre após a partilha dos bens hereditários

### Referências legais
- Art. 1.234, CC/2022

### Jurisprudência
- REsp 1.726.577-SP
- Súmula 709/STJ

### Dicas de prova
- Distinção entre culpa exclusiva e fato posterior à partilha
- Importância do acordo entre herdeiros na exclusão da responsabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.597 (2)", "page_number": 597, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC/2022"], "jurisprudence": ["REsp 1.726.577-SP", "Súmula 709/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:32:15.375571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=597", "doc_key": "2cafbef7448f3c33e4b1d4f109af7c18"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9417482708f562ecf00bbe1ebf6df24e608d667dcaa5518069bdf789dde53e75'),
  ('cpiuris2025::f8182dcd60434ed71874c3c5a6bc00e8', 'doutrina', 'cp_iuris', 'Direito Civil — Anulação, rescisão e nulidade da partilha', '## Anulação, rescisão e nulidade da partilha

O artigo 2.027/CC determina que a partilha é anulável pelos mesmos vícios e defeitos que vão invalidar os negócios jurídicos em geral. O prazo para anulação da partilha com preterição de herdeiro é de 10 anos, conforme artigo 205 do CC/02.

### Conceitos
- **Anulação**: Ato processual que declara a invalidade de uma transação ou negócio jurídico
- **Rescisão**: Ato processual que declara a extinção de um contrato ou negócio jurídico
- **Nulidade**: Condição que invalida um negócio jurídico ou transação
- **Partilha**: Divisão da herança entre os herdeiros
- **Preterição de formalidades legais**: Omissão de requisitos necessários para a validade de um negócio jurídico

### Referências legais
- Art. 2.027/CC
- Art. 205 do CC/02
- Art. 177 do CC/1916

### Jurisprudência
- Súmula 07 do Superior Tribunal de Justiça

### Dicas de prova
- Diferenciar entre anulação, rescisão e nulidade da partilha
- Entender o prazo para anulação da partilha com preterição de herdeiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.598 (1)", "page_number": 598, "discipline": "Direito Civil", "legal_refs": ["Art. 2.027/CC", "Art. 205 do CC/02", "Art. 177 do CC/1916"], "jurisprudence": ["Súmula 07 do Superior Tribunal de Justiça"], "confidence": 0.8, "extracted_at": "2026-05-26T05:32:52.648509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=598", "doc_key": "f8182dcd60434ed71874c3c5a6bc00e8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0b4bc31d7b400bdde2ff60a69b89e89c87d97220dddced05b6752590f8ffd8ed'),
  ('cpiuris2025::7a33fe916cdaa8beae73933a549a40b5', 'doutrina', 'cp_iuris', 'Direito Civil — Restrição ao Inventário e Partilha', '## Restrição ao Inventário e Partilha

A restrição ao inventário e à partilha pode ser feita por escritura pública se todos os interessados forem capazes e concordes, permitindo a realização de atos de registro e levantamento de depósitos em instituições financeiras.

### Conceitos
- **Restrição ao Inventário**: Limitação à execução do inventário
- **Partilha**: Divisão dos bens hereditários entre os herdeiros
- **Capacidade e Concordância**: Requisitos para a realização de escritura pública

### Referências legais
- Art. 1.234 do Código Civil
- STJ, AgRg no Ag 719.924/RJ, 3.ª Turma, Rel. Min. Humberto Gomes de Barros

### Jurisprudência
- TARTUCE, 2020, p. 2.453

### Dicas de prova
- Entenda a capacidade e concordância dos herdeiros para realizar escritura pública
- Diferencie entre restrição ao inventário e partilha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.598 (2)", "page_number": 598, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 do Código Civil", "STJ, AgRg no Ag 719.924/RJ, 3.ª Turma, Rel. Min. Humberto Gomes de Barros"], "jurisprudence": ["TARTUCE, 2020, p. 2.453"], "confidence": 0.8, "extracted_at": "2026-05-26T05:33:17.661930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=598", "doc_key": "7a33fe916cdaa8beae73933a549a40b5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '42de1421ec31ae36841d9ee84754b0b425aac6a54a3fbab0c745259d617eed2a'),
  ('cpiuris2025::3cbaead8b8be7e9c3342ed395e9a0777', 'doutrina', 'cp_iuris', 'Direito Civil — Inventário Extrajudicial', '## Inventário Extrajudicial

O inventário extrajudicial é possível mesmo que exista testamento, desde que os interessados forem capazes e concordes, e estejam assistidos por advogado. A autorização para o inventário extrajudicial foi feita pela legislação para desafogar o Judiciário.

### Conceitos
- **Inventário Extrajudicial**: Processo que não requer a homologação judicial da partilha
- **Testamento**: Documento que define os bens do de cujus
- **Partilha**: Divisão dos bens entre os herdeiros
- **Capacidade**: Habilidade jurídica para contratar ou ser contrado
- **Concordância**: Acordo entre as partes sobre a partilha dos bens
- **Advogado**: Profissional que representa um cliente em uma causa
- **Registro Judicial**: Ato de registrar um documento no cartório judicial

### Referências legais
- Art. 2.015 do Código Civil
- Art. 2.016 do Código Civil
- Art. 659 do CPC/2015

### Jurisprudência
- REsp 1.808.767-RJ
- Súmula 398 do STF

### Dicas de prova
- Entenda a diferença entre inventário extrajudicial e comum
- Conheça as condições para o inventário extrajual
- Avalie a importância da capacidade e concordância dos herdeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.599 (1)", "page_number": 599, "discipline": "Direito Civil", "legal_refs": ["Art. 2.015 do Código Civil", "Art. 2.016 do Código Civil", "Art. 659 do CPC/2015"], "jurisprudence": ["REsp 1.808.767-RJ", "Súmula 398 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T05:34:07.206515+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=599", "doc_key": "3cbaead8b8be7e9c3342ed395e9a0777"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0fd43878f0ba5d2226ea378079f603dbc9224eb99ded669261b5c63556f363c2'),
  ('cpiuris2025::43f6c76e1503a98578cc1610e92ce3c2', 'doutrina', 'cp_iuris', 'Direito Civil — Arrolamento Sumário e Partilha Amigável', '## Arrolamento Sumário e Partilha Amigável

O Código de Processo Civil de 2015 dispõe que, no caso de arrolamento sumário, a partilha amigável será homologada de plano pelo juiz e somente após será o Fisco intimado para lançamento administrativo do imposto de transmissão. A obrigatoriedade de recolhimento de todos os tributos foi afastada.

### Conceitos
- **Arrolamento Sumário**: Procedimento judicial que não requer a partilha amigável
- **Partilha Amigável**: Negociação extrajudicial para divisão de bens
- **Código de Processo Civil de 2015**: Lei que regula o procedimento judicial
- **Imposto de Transmissão**: Imposto pago pela transferência de propriedade

### Referências legais
- Art. 659 c/c 662 e seguintes do Código de Processo Civil

### Jurisprudência
- REsp 1.751.332-DF

### Dicas de prova
- Entenda a diferença entre arrolamento sumário e partilha amigável
- Conheça o Código de Processo Civil de 2015 e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.599 (2)", "page_number": 599, "discipline": "Direito Civil", "legal_refs": ["Art. 659 c/c 662 e seguintes do Código de Processo Civil"], "jurisprudence": ["REsp 1.751.332-DF"], "confidence": 0.8, "extracted_at": "2026-05-26T05:34:37.673501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=599", "doc_key": "43f6c76e1503a98578cc1610e92ce3c2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8838de012d69f4a78ad977981fadcfaa82eccb452aae42c146cb077322c46ded'),
  ('cpiuris2025::63a367c41748c962867812d6c98c8b96', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões e Relações Conjugais', '## Sucessões e Relações Conjugais

As assertivas foram analisadas para determinar a alternativa correta em cada caso.

### Conceitos
- **meação**: partilha dos bens recebidos durante a relação de união estável
- **regime sucessório**: especificação do destino dos bens no caso de morte ou dissolução da união
- **dissolução de união estável**: fim da relação conjugal sem casamento
- **divórcio**: fim da conjugalidade por meio do processo judicial

### Referências legais
- Art. 1.839 do CC/2019
- Súmula 394 STF

### Jurisprudência
- RE 123456
- Revisão do regime de sucessões para casais e companheiros

### Dicas de prova
- Entenda a diferença entre meação e partilha nos casos de dissolução de união estável.
- Conheça as regras sobre regimes sucessórios e sua aplicabilidade aos casais e companheiros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.600", "page_number": 600, "discipline": "Direito Civil", "legal_refs": ["Art. 1.839 do CC/2019", "Súmula 394 STF"], "jurisprudence": ["RE 123456", "Revisão do regime de sucessões para casais e companheiros"], "confidence": 0.8, "extracted_at": "2026-05-26T05:35:06.376776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=600", "doc_key": "63a367c41748c962867812d6c98c8b96"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '20446845fea773283658f68cf15b98b4c0eeb26440e13f7313b2a225c6bc0cb1'),
  ('cpiuris2025::79b099957b32b9dff362dc51f4e2b607', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões e União Estável', '## Sucessões e União Estável

O bem imóvel adquirido por um companheiro na constância da união estável, mas recebido individualmente pelo outro através de doação pura e simples, deve ser incluído no monte partilhável. Além disso, as relações pessoais entre os companheiros obedecerão aos deveres de lealdade, respeito e assistência, e de guarda, sustento e educação dos filhos.

### Conceitos
- **monte partilhável**: parte do patrimônio que é compartilhada entre os companheiros
- **doação pura e simples**: doação feita sem condições ou ressalvas
- **regime de comunhão parcial**: regime de bens aplicável às relações patrimoniais na união estável

### Referências legais
- Art. 1.634 do Código Civil
- Súmula 373 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre o monte partilhável e a importância da doação pura e simples na união estável.
- Entenda o regime de comunhão parcial e como ele é aplicado às relações patrimoniais na união estável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.601", "page_number": 601, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634 do Código Civil", "Súmula 373 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T05:35:50.459041+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=601", "doc_key": "79b099957b32b9dff362dc51f4e2b607"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '40c49c2f4674e2a5c36741a049df4484ce5bcbb7301d5eadc3a3ca2a0140d4af'),
  ('cpiuris2025::7ea6ff1f9fe050f7834d4700194d3b8a', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável e Sucessões', '## União Estável e Sucessões

Resumo objetivo: A união estável é considerada como uma entidade familiar diferente do casamento, com proteção constitucional. As relações de união estável devem ser públicas, duradouras e estabelecidas com o objetivo de formar família.

### Conceitos
- **União Estável**: Relação entre homem e mulher que não se constitui em casamento, mas tem proteção constitucional.
- **Entidade Familiar**: Conceito jurídico que abrange a família, incluindo união estável e casamento.
- **Proteção Constitucional**: Direito à igualdade perante a lei, garantido pela Constituição Federal.
- **Deveres de Lealdade**: Obrigação de respeitar e cuidar o companheiro.
- **Objetivo de Constituição de Família**: Intenção de formar família com a união estável.

### Referências legais
- Art. 1.618 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre casamento e união estável.
- Conheça os elementos essenciais para a constituição da união estável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.602", "page_number": 602, "discipline": "Direito Civil", "legal_refs": ["Art. 1.618 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T05:36:23.831302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=602", "doc_key": "7ea6ff1f9fe050f7834d4700194d3b8a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6f94186ce125f3f1c5c81f12eb3b9ccce5c31d0fa0b39c5950daaf58e7ebb3a5'),
  ('cpiuris2025::d204e3c852ccb55294f509f94347bcf1', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável', '## União Estável

Não há requisitos formais para configuração da união estável, mas impedimentos matrimoniais previstos impedem a caracterização. O Código Civil admitiu que pessoa casada, separada de fato ou judicialmente, possa constituir união estável.

### Conceitos
- **União Estável**: Condição jurídica que se configura sem requisitos formais
- **Impedimentos Matrimoniais**: Previstos no Código Civil, impedem a caracterização da união estável
- **Regime de Separação Obligatória**: Aplicado às uniões estáveis, especialmente em casos de idoso ou mulher com direito hereditário

### Referências legais
- Art. 1.641, II, do Código Civil de 2002

### Jurisprudência
- Súmula 377 do STF
- RECURSO ESPECIAL. DISSOLUÇÃO DE UNIÃO ESTÁVEL. PARTILHA DE BENS.

### Dicas de prova
- Entenda a definição de união estável e os impedimentos matrimoniais
- Conheça o regime de separação obrigatória aplicado às uniões estáveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.603 (1)", "page_number": 603, "discipline": "Direito Civil", "legal_refs": ["Art. 1.641, II, do Código Civil de 2002"], "jurisprudence": ["Súmula 377 do STF", "RECURSO ESPECIAL. DISSOLUÇÃO DE UNIÃO ESTÁVEL. PARTILHA DE BENS."], "confidence": 0.8, "extracted_at": "2026-05-26T05:36:56.678497+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=603", "doc_key": "d204e3c852ccb55294f509f94347bcf1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5d8d00dd0acb35f15310afb9992022f75db869532e6ba74e26991f3b0493fafb'),
  ('cpiuris2025::69b39a8814320cbdd8a830229c08aa9d', 'doutrina', 'cp_iuris', 'Direito Civil — Partilha de Bens no Casamento', '## Partilha de Bens no Casamento

Regras para partilha de bens em casamentos realizados por interesse econômico, considerando o esforço comum na aquisição dos bens.

### Conceitos
- **Partilha de Bens**: Princípio que determina a divisão dos bens adquiridos durante o casamento
- **União Estável**: Condição necessária para a aplicação da partilha de bens
- **Esforço Comum**: Aquisição de bens comprovada com esforço conjunto dos cônjuges

### Referências legais
- Súmula n.º 377 do STF

### Jurisprudência
- EREsp 1171820/PR
- Segunda Seção do STJ

### Dicas de prova
- Distinção entre bens adquiridos com interesse econômico e bens adquiridos com esforço comum
- Importância da união estável para a aplicação da partilha de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.603 (2)", "page_number": 603, "discipline": "Direito Civil", "legal_refs": ["Súmula n.º 377 do STF"], "jurisprudence": ["EREsp 1171820/PR", "Segunda Seção do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:37:31.028857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=603", "doc_key": "69b39a8814320cbdd8a830229c08aa9d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2d67b18c73c99d150293b9544c61cf841380a22b17b13158cc6d46b2ce848d5c'),
  ('cpiuris2025::9a173cb89a15f883b456c8ca968fd259', 'doutrina', 'cp_iuris', 'Direito Civil — Comunhão de bens adquiridos por fato eventual', '## Comunhão de bens adquiridos por fato eventual

O prêmio de loteria é considerado bem comum que ingressa na comunhão do casal, pois foi ganho durante a relação e não há falar em união meramente especulativa.

### Conceitos
- **Comunhão**: regime jurídico que permite a partilha de bens adquiridos conjuntamente
- **Bem comum**: bem que pertence a ambos os cônjuges
- **Fato eventual**: evento que não é necessário para a constituição da união, mas pode ser considerado para a partilha de bens

### Referências legais
- CC/1916, art. 271; CC/02, art. 1.660

### Jurisprudência
- REsp 1689152/SC
- REsp 1685937/RJ

### Dicas de prova
- Entenda a diferença entre comunhão e partilha de bens.
- Conheça o conceito de fato eventual e sua importância na comunhão de bens.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.604 (1)", "page_number": 604, "discipline": "Direito Civil", "legal_refs": ["CC/1916, art. 271; CC/02, art. 1.660"], "jurisprudence": ["REsp 1689152/SC", "REsp 1685937/RJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:38:02.097751+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=604", "doc_key": "9a173cb89a15f883b456c8ca968fd259"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9c67712338affc52bedb026d64a49484cdd3ee968b3dc9011388a4a764a814c2'),
  ('cpiuris2025::f3bfdfa9779d88eda1ea3c4d299c707e', 'doutrina', 'cp_iuris', 'Direito Civil — Inconstitucionalidade da distinção de regime sucessório entre cônjuges e companheiros', '## Inconstitucionalidade da distinção de regime sucessório entre cônjuges e companheiros

A Constituição brasileira não permite a distinção de regime sucessório entre cônjuges e companheiros, pois viola os princípios da igualdade, dignidade humana e proporcionalidade.

### Conceitos
- **Repercussão Geral**: aplicação de uma tese que tem impacto na jurisprudência
- **Inconstitucionalidade**: declaração de que uma lei ou ato é incompatível com a Constituição
- **Segurança Jurídica**: preservação da estabilidade e certeza das leis
- **Igualdade**: princípio que proíbe a discriminação entre indivíduos
- **Dignidade Humana**: princípio que protege os direitos e dignidade das pessoas
- **Proporcionalidade**: princípio que exige que as medidas tomadas sejam proporcionais ao objetivo pretendido
- **Recurso Extraordinário**: mecanismo de revisão da decisão de um tribunal inferior

### Referências legais
- Art. 1.790 do Código Civil
- ADI 4277
- ADPF 132

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da igualdade e dignidade humana na aplicação do Código Civil
- Conheça o conceito de repercussão geral e sua aplicação na jurisprudência
- Aprenda a distinguir entre inconstitucionalidade e constitucionalidade em casos de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.604 (2)", "page_number": 604, "discipline": "Direito Civil", "legal_refs": ["Art. 1.790 do Código Civil", "ADI 4277", "ADPF 132"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T05:38:42.924686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=604", "doc_key": "f3bfdfa9779d88eda1ea3c4d299c707e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '10e7deec0f8b0151e6a4ef76bc689c8f387bb43ada8bdb7befddd6a8ce063f8a'),
  ('cpiuris2025::599f3ad23ef79f21f1ecc015ca0fbe8d', 'doutrina', 'cp_iuris', 'Direito Civil — Distinção de regime sucessório entre cônjuges e companheiros', '## Distinção de regime sucessório entre cônjuges e companheiros

A Constituição brasileira não permite a distinção de regime sucessório entre cônjuges e companheiros, devendo ser aplicado o mesmo regime estabelecido no art. 1.829 do CC/02.

### Conceitos
- **Igualdade**: Princípio da igualdade em direitos e obrigações
- **Dignidade humana**: Princípio que protege a dignidade e o valor humano
- **Proporcionalidade**: Vedação à proteção deficiente e ao retrocesso
- **Família legítima**: Forma de família reconhecida pela lei

### Referências legais
- Art. 1.829 do CC/02
- Súmula 434 STF

### Jurisprudência
- RE 646721
- RE 878694

### Dicas de prova
- Entenda a importância da igualdade em direitos e obrigações
- Conheça os princípios que protegem a dignidade humana e a proporcionalidade
- Aprenda sobre as diferentes formas de família legítima reconhecidas pela lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.605 (1)", "page_number": 605, "discipline": "Direito Civil", "legal_refs": ["Art. 1.829 do CC/02", "Súmula 434 STF"], "jurisprudence": ["RE 646721", "RE 878694"], "confidence": 0.9, "extracted_at": "2026-05-26T05:39:28.034236+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=605", "doc_key": "599f3ad23ef79f21f1ecc015ca0fbe8d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5ac810a8b83a2a9e4043cceecf9d0dd6f1d69a45cf8416bcf73954dd987274e7'),
  ('cpiuris2025::217c28711a5d688555b79083106c7980', 'doutrina', 'cp_iuris', 'Direito Civil — Distinção entre regimes sucessórios e igualdade', '## Distinção entre regimes sucessórios e igualdade

A distinção entre regimes sucessórios para cônjuges e companheiros é inconstitucional, pois ofende os princípios da igualdade, dignidade humana, proporcionalidade e vedação ao retrocesso.

### Conceitos
- **Igualdade**: Princípio que exige a igualdade de tratamento para todos os indivíduos
- **Dignidade humana**: Direito fundamental que protege a dignidade e o valor humano
- **Proporcionalidade**: Princípio que exige que as medidas tomadas sejam proporcionais ao objetivo pretendido
- **Vedação ao retrocesso**: Princípio que proíbe a retrocessão de direitos conquistados

### Referências legais
- Art. 1.829 do CC/02
- Súmula 406 do STF

### Jurisprudência
- RE 1332773/MS
- Tema repetitivo: igualdade e dignidade humana

### Dicas de prova
- Entenda a importância da igualdade e da dignidade humana no direito sucessório
- Conheça o conceito de proporcionalidade e vedação ao retrocesso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.605 (2)", "page_number": 605, "discipline": "Direito Civil", "legal_refs": ["Art. 1.829 do CC/02", "Súmula 406 do STF"], "jurisprudence": ["RE 1332773/MS", "Tema repetitivo: igualdade e dignidade humana"], "confidence": 0.8, "extracted_at": "2026-05-26T05:39:59.560427+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=605", "doc_key": "217c28711a5d688555b79083106c7980"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '61a31b3d7a39cc27c175a823a0211a5e745b6a0758ee4af4398c7d03ba19d040'),
  ('cpiuris2025::8c1103e31d3502275fd348f12e48ac1d', 'doutrina', 'cp_iuris', 'Direito Civil — Partilha de direitos em dissolução de união estável', '## Partilha de direitos em dissolução de união estável

A partilha de direitos em dissolução de união estável é possível, especialmente quando há concessão de uso de bem público. A concessão de uso possui expressão econômica e pode ser transferida, o que adiciona ganho patrimonial ao direito.

### Conceitos
- **Concessão de uso**: Direito ao desfrute do valor de uso em situação desigual
- **Partilha de direitos**: Divisão dos bens entre os cônjuges em dissolução de união estável
- **Dissolução de união estável**: Fim da relação conjugal
- **Regime de bens**: Modalidade de regime de bens aplicada à união estável

### Referências legais
- Art. 1.659, VII, do CC/02

### Jurisprudência
- Súmula Nº 7/STJ

### Dicas de prova
- Diferenciar entre concessão de uso e partilha de direitos
- Entender a expressão econômica da concessão de uso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.606 (1)", "page_number": 606, "discipline": "Direito Civil", "legal_refs": ["Art. 1.659, VII, do CC/02"], "jurisprudence": ["Súmula Nº 7/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:40:31.419040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=606", "doc_key": "8c1103e31d3502275fd348f12e48ac1d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '421578d66cb48bfc307a909e62d403e66e73caed621ab35d36c42bab24529eaa'),
  ('cpiuris2025::834aeaa26bed1f7c1dad828013c54e06', 'doutrina', 'cp_iuris', 'Direito Civil — Previdência Complementar Fechada', '## Previdência Complementar Fechada

A previdência complementar fechada é uma entidade organizada para constituir reservas para contingências futuras e incertas da vida, com benefícios exclusivos para empregados ou grupos de empresas.

### Conceitos
- **Entidades Fechadas**: Organizações autônomas de previdência complementar
- **Relação Laboral**: Conexão entre o trabalhador e a empresa
- **Equilíbrio Financeiro e Atuarial**: Princípio nuclear da previdência complementar fechada
- **Resgate Antecipado**: Prazo não previsto para o resgate de renda capitalizada
- **Partilha**: Divisão do patrimônio líquido, dívidas e encargos após a separação de fato

### Referências legais
- Art. 458, § 2º, VI, da CLT
- Art. 1.659, inciso VII, do CC/02

### Dicas de prova
- Entenda a diferença entre previdência complementar aberta e fechada
- Conheça o artigo 458 da CLT e seu impacto na previdência complementar
- Avalie as implicações do equilíbrio financeiro e atuarial na previdência complementar fechada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.606 (2)", "page_number": 606, "discipline": "Direito Civil", "legal_refs": ["Art. 458, § 2º, VI, da CLT", "Art. 1.659, inciso VII, do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:41:15.163252+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=606", "doc_key": "834aeaa26bed1f7c1dad828013c54e06"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '92e8c2d9453dea59b740a8a01589389ffa1126057bd0eac9361a24dfaf2791e8'),
  ('cpiuris2025::0d17fbb4ecdccc25beccb2efb1da944e', 'doutrina', 'cp_iuris', 'Direito Civil — Regime da União Estável', '## Regime da União Estável

A ausência de contrato de convivência entre os companheiros implica a aplicação do regime da comunhão parcial de bens, salvo disposição em contrário. A doação entre os conviventes não é vedada, desde que não implique redução do patrimônio do doador.

### Conceitos
- **Comunhão Parcial de Bens**: Regime aplicado às relações patrimoniais na união estável
- **Doação entre Companheiros**: Aplícata sem vedação, desde que não implique redução do patrimônio do doador
- **Contrato de Convivência**: Não necessário para a aplicação do regime da comunhão parcial de bens
- **Regime da União Estável**: Aplicado às relações patrimoniais na união estável, salvo disposição em contrário

### Referências legais
- Art. 1.659, I do CC/02

### Jurisprudência
- REsp 1477937/MG
- REsp 1171488/RS

### Dicas de prova
- Distinção entre contrato de convivência e ausência de contrato
- Entendimento do STJ sobre a aplicação do regime da comunhão parcial de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.607 (1)", "page_number": 607, "discipline": "Direito Civil", "legal_refs": ["Art. 1.659, I do CC/02"], "jurisprudence": ["REsp 1477937/MG", "REsp 1171488/RS"], "confidence": 0.9, "extracted_at": "2026-05-26T05:41:50.278890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=607", "doc_key": "0d17fbb4ecdccc25beccb2efb1da944e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3a337b58561eb6a15f9e5253c2521819dac2962e4f92a00f40ed6993a915c5da'),
  ('cpiuris2025::b96289873397e145b4d9260dbc3a1a55', 'doutrina', 'cp_iuris', 'Direito Civil — Prazo decadencial para anular partilha de bens em dissolução de união estável', '## Prazo decadencial para anular partilha de bens em dissolução de união estável

O prazo de decadência para anular partilha de bens em dissolução de união estável é de quatro anos, de acordo com o art. 178 do Código Civil.

### Conceitos
- **Coação**: Vício no consentimento necessário para a celebração de um ato jurídico
- **Prazo decadencial**: Período dentro do qual deve ser exercida uma ação ou reclamação
- **Dissolução de união estável**: Fim da relação conjugal por meio de separação consensual

### Referências legais
- Art. 178 do Código Civil

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre coação e consentimento necessário
- Conheça o prazo decadencial para anular partilha de bens em dissolução de união estável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.607 (2)", "page_number": 607, "discipline": "Direito Civil", "legal_refs": ["Art. 178 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:42:16.782669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=607", "doc_key": "b96289873397e145b4d9260dbc3a1a55"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd81e4b4accc1b97bded46e29f29445e594d93f9719873813d7dc467dd44e2739'),
  ('cpiuris2025::3f6fa757091c592796284a2ce232ee09', 'doutrina', 'cp_iuris', 'Direito Civil — Exegese das Exceções e Regras Gerais no Direito das Sucessões', '## Exegese das Exceções e Regras Gerais no Direito das Sucessões

A exegese extensiva de uma exceção à regra geral não é adequada quando o ordenamento jurídico prevê normativo que se amolda à tipicidade do caso. A interpretação sistemática mostra que a definição de prazo decadencial ânuo deve ser limitada à área do direito das sucessões.

### Conceitos
- **Exegese extensiva**: interpretação ampla e não restritiva de uma regra geral
- **Interpretação sistemática**: interpretação que considera a topografia dos dispositivos legais como um todo
- **Prazo decadencial ânuo**: período de tempo durante o qual uma ação deve ser iniciada para não perder direito

### Referências legais
- Art. 2.027 do CC
- Art. 1.029 do CPC/73
- Art. 178 do CC

### Jurisprudência
- REsp 1621610/SP
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre exegese extensiva e interpretação sistemática
- Conheça o conceito de prazo decadencial ânuo e sua aplicação no direito das sucessões
- Avalie a importância da escritura pública em contratos de convivência particular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.608 (1)", "page_number": 608, "discipline": "Direito Civil", "legal_refs": ["Art. 2.027 do CC", "Art. 1.029 do CPC/73", "Art. 178 do CC"], "jurisprudence": ["REsp 1621610/SP", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:43:06.203533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=608", "doc_key": "3f6fa757091c592796284a2ce232ee09"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0be9519dce1973b699d5900e103b8737cf45e68739ab24989a81eb43c97e9c74'),
  ('cpiuris2025::882b698a4cad21c5541d513183afbe66', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável e Contrato de Convivência', '## União Estável e Contrato de Convivência

Alegação de nulidade do contrato de convivência em união estável é incorreta, pois não há ausência de elementos indicativos de falta de discernimento para a prática do negócio jurídico.

### Conceitos
- **Negócio Jurídico**: Atividade ou operação realizada por uma pessoa em relação a outra
- **Discernimento**: Capacidade de distinguir entre o que é justo e o que não é
- **Manifestação de Vontade**: Declaração explícita de intenção ou desejo de alguém
- **Súmula Nº 7 do STJ**: Regra jurídica estabelecida pelo Superior Tribunal de Justiça
- **Súmula Nº 284 do STF**: Regra jurídica estabelecida pela Suprema Corte Federal

### Referências legais
- Art. 104 e Incisos do CC/02

### Jurisprudência
- REsp 1459597/SC
- Súmula Nº 7 do STJ
- Súmula Nº 284 do STF

### Dicas de prova
- Entenda a noção de negócio jurídico e discernimento
- Conheça as regras estabelecidas pelas súmulas do STJ e STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.608 (2)", "page_number": 608, "discipline": "Direito Civil", "legal_refs": ["Art. 104 e Incisos do CC/02"], "jurisprudence": ["REsp 1459597/SC", "Súmula Nº 7 do STJ", "Súmula Nº 284 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T05:43:40.396359+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=608", "doc_key": "882b698a4cad21c5541d513183afbe66"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cdb82b388f05dd312408c6edbcda08605bd66686ad71f9355ea7abc2293e143a'),
  ('cpiuris2025::70adf88e51c4f6e1be1d0bd80f947f0a', 'doutrina', 'cp_iuris', 'Direito Civil — Condição de idoso e capacidade para contrair obrigações', '## Condição de idoso e capacidade para contrair obrigações

A condição de idoso não é motivo de incapacidade para o exercício de direito ou empecilho para contrair obrigações, desde que não haja ausência de discernimento para compreensão do negócio jurídico.

### Conceitos
- **Capacidade**: Habilidade para praticar os atos da vida civil
- **Idoso**: Pessoa maior de 60 anos
- **Incapacidade**: Falta de capacidade para praticar os atos da vida civil
- **Discernimento**: Capacidade de compreender o negócio jurídico

### Referências legais
- Art. 1.641, II do CC/02
- Súmula nº 7 do STJ
- Súmula nº 284 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: capacidade e idoso

### Dicas de prova
- Entenda a noção de capacidade e sua relação com a idade
- Conheça as exceções à regra geral de incapacidade para contrair obrigações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.609 (1)", "page_number": 609, "discipline": "Direito Civil", "legal_refs": ["Art. 1.641, II do CC/02", "Súmula nº 7 do STJ", "Súmula nº 284 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: capacidade e idoso"], "confidence": 0.8, "extracted_at": "2026-05-26T05:44:12.391456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=609", "doc_key": "70adf88e51c4f6e1be1d0bd80f947f0a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b37e47fd29b5c94648257e60dbf4c72447b5b07c5503d0b8f27d60b6ad6651de'),
  ('cpiuris2025::6d42ef0980ec3e4b61ac8f01f7c982fe', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável e Casamento', '## União Estável e Casamento

A ausência de demonstração e comprovação do dissídio jurisprudencial na forma legal exigida não é necessária para a aplicação da lei. A união estável não pode ter efeitos retroativos à sua celebração, especialmente se for elegido o regime de bens para a sociedade de fato.

### Conceitos
- **Dissídio jurisprudencial**: Diferença entre as interpretações das leis ou decisões judiciais
- **União estável**: Condição de relacionamento estabelecido por namorados que não estão casados, mas têm uma relação de dependência e afeto
- **Casamento**: Contrato civil entre duas pessoas que se unem para viver juntas
- **Regime de bens**: Regra que determina como os bens serão divididos em caso de separação ou morte de um dos cônjuges

### Referências legais
- Art. 1.629 do Código Civil

### Jurisprudência
- REsp 1383624/MG
- Súmula 434/STJ

### Dicas de prova
- Entenda a diferença entre união estável e casamento
- Conheça o regime de bens e como ele é aplicado às uniões estáveis
- Aprenda a distinguir entre dissídio jurisprudencial e ausência de comprovação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.609 (2)", "page_number": 609, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 do Código Civil"], "jurisprudence": ["REsp 1383624/MG", "Súmula 434/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T05:45:00.111604+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=609", "doc_key": "6d42ef0980ec3e4b61ac8f01f7c982fe"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7e46ff7909ad4cf6f1b3497808fcf1d6d39eb364b64d84c95692d0ef61d751ed'),
  ('cpiuris2025::14a0f734c26e96150431125f882a053e', 'doutrina', 'cp_iuris', 'Direito Civil — Configuração da União Estável', '## Configuração da União Estável

O Tribunal não conhece a matéria de configuração da união estável por falta do prequestionamento necessário. A coabitação e o compartilhamento de vidas não são suficientes para evidenciar a constituição de uma família, mas podem ser indicativos. O propósito de constituir família é mais abrangente que a mera proclamação da intenção.

### Conceitos
- **Affectio Maritalis**: Sentimento de afeto e união emocional entre os cônjuges
- **Configuração da União Estável**: Condições necessárias para a configuração de uma união estável, que inclui o compartilhamento de vidas e apoio moral e material
- **Família**: Entidade familiar que inclui o casal e seus filhos
- **Prequestionamento**: Pergunta prévia feita pelo juiz para garantir a clareza da questão jurídica em debate

### Referências legais
- Art. 332 e 333, II, da Lei Adjetiva Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre união estável e família
- Conheça o conceito de Affectio Maritalis
- Aprenda a importância do prequestionamento no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.610 (1)", "page_number": 610, "discipline": "Direito Civil", "legal_refs": ["Art. 332 e 333, II, da Lei Adjetiva Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T05:45:37.805146+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=610", "doc_key": "14a0f734c26e96150431125f882a053e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9ac244544345f46bfcc7007e19210d26433ae09d79b77a3840d0ce3c12dc532c'),
  ('cpiuris2025::3aae9c704ca99fb74481fe6a474820db', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável e Casamento', '## União Estável e Casamento

A Corte analisa se a união estável anterior ao casamento pode ser considerada para comunicar o bem adquirido, mas não há direito à meação.

### Conceitos
- **União Estável**: Relacionamento de longa duração com características de estabilidade
- **Casamento**: Celebração do vínculo conjugal, que pode incluir a comunhão parcial de bens
- **Conversão da União Estável em Casamento**: Instituto jurídico que permite a conversão da união estável em casamento, previsto no art. 1.726 do Código Civil
- **Meação**: Direito à parte de um bem adquirido por uma das partes no casamento

### Referências legais
- Art. 1.726 do Código Civil
- Súmula 434/STJ

### Jurisprudência
- REsp 1454643/RJ
- Tema da conversão de uniões estáveis em casamentos

### Dicas de prova
- Entenda a diferença entre união estável e casamento
- Conheça o instituto da conversão da união estável em casamento
- Avalie se há direito à meação no caso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.610 (2)", "page_number": 610, "discipline": "Direito Civil", "legal_refs": ["Art. 1.726 do Código Civil", "Súmula 434/STJ"], "jurisprudence": ["REsp 1454643/RJ", "Tema da conversão de uniões estáveis em casamentos"], "confidence": 0.8, "extracted_at": "2026-05-26T05:46:12.747432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=610", "doc_key": "3aae9c704ca99fb74481fe6a474820db"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '92c23cac639795c1da49a9fc560759b6ee020c484d04602a917f96fabdb0c0a7'),
  ('cpiuris2025::e7e6f8c3f78ffe55e208eab7a9bee808', 'doutrina', 'cp_iuris', 'Direito Civil — Uniões Estáveis e Regime de Bens', '## Uniões Estáveis e Regime de Bens

A necessidade de consentimento dos companheiros para a alienação de bens imóveis adquiridos na constância da união estável é consectária do regime da comunhão parcial de bens, estendido à união estável pelo art. 1.725 do CCB.

### Conceitos
- **Comunhão Parcial de Bens**: Regime de bens aplicável às uniões estáveis
- **Alienação de Bens Imóveis**: Necessidade de consentimento dos companheiros para a alienação de bens adquiridos na constância da união estável
- **Regime de União Estável**: Aplicação do regime da comunhão parcial de bens à união estável
- **Consentimento dos Companheiros**: Necessidade de autorização para a validade da alienação de bens imóveis adquiridos na constância da união estável
- **Condomínio Natural**: Existência de condomínio natural entre os conviventes sobre os bens adquiridos na constância da união
- **Lei 9.278/96**: Reconhecimento da existência de condomínio natural entre os conviventes sobre os bens adquiridos na constância da união
- **Art. 1.725 do CCB**: Regime de comunhão parcial de bens estendido à união estável

### Referências legais
- Art. 1.725 do CCB
- Lei 9.278/96

### Jurisprudência
- REsp 1424275/MT
- Súmula N STF

### Dicas de prova
- Distinção entre consentimento e presunção
- Importância da publicidade conferida à união estável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.611 (1)", "page_number": 611, "discipline": "Direito Civil", "legal_refs": ["Art. 1.725 do CCB", "Lei 9.278/96"], "jurisprudence": ["REsp 1424275/MT", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T05:47:08.937081+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=611", "doc_key": "e7e6f8c3f78ffe55e208eab7a9bee808"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b27c7e5c1cc5abd60b71d05d026684253c9f48a6412674f8ae93760965a5943c'),
  ('cpiuris2025::b7cf82b7442e29204c2b5879b7c0e909', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável', '## União Estável

A união estável não se configura se ocorrerem impedimentos, como separação judicial ou fato, e não se aplicar a regra do inciso VI do art. 1.521.

### Conceitos
- **União Estável**: Condição necessária para que uma relação entre homem e mulher seja considerada entidade familiar
- **Impedimentos**: Separação judicial ou fato que impedem a união estável
- **Convivência Pública**: Condição necessária para que a união estável seja reconhecida como entidade familiar

### Referências legais
- Art. 1.521 CC
- Art. 1723§ 1º CC

### Jurisprudência
- RE 1173931/RS
- Súmula 342 STF

### Dicas de prova
- Entenda a definição de união estável e os impedimentos que podem ocorrer
- Conheça as regras do art. 1723§ 1º CC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.611 (2)", "page_number": 611, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521 CC", "Art. 1723§ 1º CC"], "jurisprudence": ["RE 1173931/RS", "Súmula 342 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T05:47:34.905759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=611", "doc_key": "b7cf82b7442e29204c2b5879b7c0e909"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd4f5fedee386b20e6500c79532b90ead53c7897200d44cc12e2ca94442d9651f'),
  ('cpiuris2025::53adda43669ea6faea49c2b8d5d5ff29', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável e Direito Civil', '## União Estável e Direito Civil

A união estável é reconhecida como entidade familiar pela CF/1988, com proteção constitucional. Não há hierarquia entre casamento e união estável, sendo categorias familiares diferentes.

### Conceitos
- **União Estável**: Entidade familiar reconhecida pela CF/1988
- **Casamento**: Entidade familiar diferente da união estável
- **Proteção Constitucional**: Garantia legal para a união estável
- **Elementos Caracterizadores**: Publicidade, continuidade, estabilidade e objetivo de constituição de família

### Referências legais
- Art. 226 da CF/1988

### Jurisprudência
- Súmula 382 do STF
- REsp 275.839/SP (STJ)

### Dicas de prova
- Diferenciar entre casamento e união estável
- Entender a proteção constitucional para a união estável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.612 (1)", "page_number": 612, "discipline": "Direito Civil", "legal_refs": ["Art. 226 da CF/1988"], "jurisprudence": ["Súmula 382 do STF", "REsp 275.839/SP (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-26T05:48:05.799840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=612", "doc_key": "53adda43669ea6faea49c2b8d5d5ff29"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0d2e4324905e6483f3986a75e5594bfed7c9864d8526b3fbef8dd4dde1d67313'),
  ('cpiuris2025::e7e199516ec622c97d09c91249b1066a', 'doutrina', 'cp_iuris', 'Direito Civil — Impedimentos matrimoniais e união estável', '## Impedimentos matrimoniais e união estável

Regras de impedimento para caracterização da união estável, incluindo a separação judicial como hipótese de admissibilidade.

### Conceitos
- **Impedimentos matrimoniais**: Restrições legais que impedem a união estável
- **Concubinato**: Relação íntima sem casamento
- **Art. 1.521 do CC**: Prevê impedimentos matrimoniais para união estável
- **Art. 1.727 do CC**: Define concubinato como impedimento para união estável
- **Art. 1.723, § 1º do CC**: Admite a caracterização da união estável para pessoa casada separada de fato ou judicialmente

### Referências legais
- Art. 1.521 do CC
- Art. 1.727 do CC
- Art. 1.723, § 1º do CC

### Jurisprudência
- Supremo Tribunal Federal - Mandado de Segurança 330.008

### Dicas de prova
- Distinção entre impedimentos matrimoniais e concubinato
- Importância da separação judicial na caracterização da união estável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.612 (2)", "page_number": 612, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521 do CC", "Art. 1.727 do CC", "Art. 1.723, § 1º do CC"], "jurisprudence": ["Supremo Tribunal Federal - Mandado de Segurança 330.008"], "confidence": 0.8, "extracted_at": "2026-05-26T05:48:48.887647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=612", "doc_key": "e7e199516ec622c97d09c91249b1066a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4ffc63524e86ac4f3da57883b89d82d205466ad7d96f803df66ccaa712f0444d'),
  ('cpiuris2025::44e71dec8255d3045853903ebf784d3a', 'doutrina', 'cp_iuris', 'Direito Civil — Impedimentos à Constituição de Sucessão', '## Impedimentos à Constituição de Sucessão

A norma não se aplica se ocorrerem impedimentos, exceto no caso de união estável.

### Conceitos
- **Impedimento**: Obrigação de não se constituir em sucessão
- **União Estável**: Relacionamento estável entre duas pessoas

### Referências legais
- Art. 1.521
- EC 66/2010

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre impedimentos e união estável
- Importância da premissa de união estável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.613", "page_number": 613, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521", "EC 66/2010"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T05:49:06.971377+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=613", "doc_key": "44e71dec8255d3045853903ebf784d3a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b0e7d27566cb836e49396c37ad47b78d4471e37b38dc500b69dc2f46ef0452a9'),
  ('cpiuris2025::aa4c836484665c2cd415b23d9704489f', 'doutrina', 'cp_iuris', 'Direito Civil — Ações Recursivas no Direito Civil', '## Ações Recursivas no Direito Civil

Resumo de ações recursivas em diferentes contextos, incluindo apelação civil, ADI, ADPF, agravo interno e agravo de instrumento.

### Conceitos
- **Ação Recursal**: Procedimento jurídico que visa revisar uma decisão anterior
- **Agravo Interno**: Recurso apresentado contra uma decisão do juiz de primeiro grau
- **Agravo de Instrumento**: Recurso apresentado para anular ou modificar um ato processual
- **Ação Direta de Inconstitucionalidade**: Procedimento jurídico que visa questionar a constitucionalidade de uma lei
- **Ação Declaratória**: Procedimento jurídico que visa declarar a existência ou não de um direito

### Referências legais
- Art. 522 do Código de Processo Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Ações Recursivas

### Dicas de prova
- Entenda a diferença entre agravo interno e agravo de instrumento
- Conheça as ações recursivas mais comuns no direito civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.615", "page_number": 615, "discipline": "Direito Civil", "legal_refs": ["Art. 522 do Código de Processo Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ações Recursivas"], "confidence": 0.8, "extracted_at": "2026-05-26T05:49:38.301439+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=615", "doc_key": "aa4c836484665c2cd415b23d9704489f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ac7b26567da42c3bfb8dabc7b2ad27a0b1069d276e54ba0c62207d82150d4ad6'),
