  ('cpiuris2025::7f5125f3793550fa09113ba7fa1e90e6', 'doutrina', 'cp_iuris', 'Direito Civil — Classificação de Processos e Recursos', '## Classificação de Processos e Recursos

Lista de processos e recursos com classificação (Habeas Corpus, Embargos, Agravos, Informativos, Leis) e números de casos e decisões.

### Conceitos
- **Embargos**: Recurso apresentado em processo de recurso especial
- **Agravos**: Recurso apresentado em processo de recurso ordinário
- **Habeas Corpus**: Processo que visa a garantia da liberdade individual
- **Informativo**: Comunicação oficial sobre jurisprudência ou decisões do STJ e STF

### Referências legais
- Art. 1.159, § 3º, do Código de Processo Civil
- Súmula 762/STJ
- Súmula 755/STJ
- Lei nº 4.657/1942

### Jurisprudência
- RE 1.559.348/DF
- RE 1.866.844/SP
- EREsp 1125139-PR
- Habeas Corpus nº 568.021/CE
- Habeas Corpus nº 363.573/SP

### Dicas de prova
