  ('cpiuris2025::440bf24212d509c4354bc63fa301aa61', 'doutrina', 'cp_iuris', 'Direito Constitucional — Importância do Estudo da Constituição e da Jurisprudência nos Conursos Públicos', '## Importância do Estudo da Constituição e da Jurisprudência nos Conursos Públicos

O material foi elaborado para fornecer um conhecimento completo e objetivo sobre a Constituição, com base nas últimas provas de concurso público, destacando temas doutrinários e jurisprudenciais relevantes.

### Conceitos
- **Constitucionalismo Ecológico**: Teoria que busca integrar a proteção ambiental à Constituição
- **Constitucionalismo Democrático**: Enfoque que prioriza a democracia e os direitos humanos na Constituição
- **Subconstituições**: Classificação das constituições em subcategorias
- **Bootstrapping Constitucional**: Fenômeno do Poder Constituinte criando-se a si mesmo

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
