- Conheça os temas doutrinários recentemente cobrados em concursos
- Preparação para a segunda fase e a prova oral é fundamental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.4", "page_number": 4, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T05:58:30.854319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=4", "doc_key": "440bf24212d509c4354bc63fa301aa61"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4630bbcae010d98cd74c5e8b37761c4528475a78bd53457c7e0d0dfe6943ce01'),
  ('cpiuris2025::c55a5c7263ddedd922dbff02f7739369', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo', '## Constitucionalismo

O constitucionalismo é uma corrente teórica que se desenvolveu ao longo da história, abordando conceitos como o constitucionalismo antigo, medieval e moderno, além de neoconstitucionalismo e outros temas contemporâneos.

### Conceitos
- **Constitucionalismo Antigo**: Corrente teórica que se desenvolveu na Grécia Antiga
- **Constitucionalismo Medieval**: Corrente teórica que se desenvolveu durante a Idade Média
- **Constitucionalismo Moderno**: Corrente teórica que se desenvolveu na Europa moderna
- **Neoconstitucionalismo**: Corrente teórica contemporânea que aborda conceitos como a constituição e o Estado

### Referências legais
- Art. 60 da Constituição Brasileira

### Dicas de prova
- Entenda a evolução histórica do constitucionalismo
- Identifique as diferentes correntes do constitucionalismo contemporâneo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60 da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T05:58:57.652308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=5", "doc_key": "c55a5c7263ddedd922dbff02f7739369"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '654284ea359560609c8ba22820825ddf14567274d6b99582cfb6507d160db6ad'),
  ('cpiuris2025::140e04999e9c01b991f21b072afc9510', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Constituição', '## Teoria da Constituição

O capítulo aborda conceitos e categorias de constitucionalismo, bem como a definição e concepções tradicionais de constituição.

### Conceitos
- **Constitucionalismo Latino-Americano**: Forma de constitucionalismo característica do continente americano
- **Constitucionalismo Abusivo**: Forma de constitucionalismo que prioriza o poder do Estado sobre os direitos individuais
- **Constitucionalismo Whig ou Termidoriano/Girondino**: Forma de constitucionalismo inspirada na Revolução Francesa
- **Crowdsourced Constitution**: Constituição criada por meio de um processo participativo e colaborativo
- **Constitucionalismo Ecológico (Environmental Constitucionalism)**: Forma de constitucionalismo que prioriza a proteção do meio ambiente
- **Constitucionalismo Autoritário (Authoritarian Constitucionalism)**: Forma de constitucionalismo que prioriza o poder do Estado e restringe os direitos individuais
- **Constitucionalismo Digital**: Forma de constitucionalismo que se relaciona com a tecnologia e a informação
- **Constitucionalismo Teocrático (Theocratic Constitucionalism)**: Forma de constitucionalismo que prioriza a religião como fonte de direitos e deveres

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda as diferentes formas de constitucionalismo e suas características
- Conheça a definição e concepções tradicionais de constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T05:59:45.931174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=5", "doc_key": "140e04999e9c01b991f21b072afc9510"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2a38182dd5f6f31a505c89af1b8d7df1668533678a59682cde9e3b00e24c2a6b'),
  ('cpiuris2025::31fb28a6827df0b70c95c0c4641d6310', 'doutrina', 'cp_iuris', 'Direito Constitucional — Concepções contemporâneas da Constituição', '## Concepções contemporâneas da Constituição

Discute-se várias concepções contemporâneas sobre a Constituição, incluindo a de Canotilho, Hesse, Häberle e Luhman.

### Conceitos
- **Constitucionalismo moralmente reflexivo**: A ideia de que a Constituição deve ser uma reflexão da moralidade e dos valores sociais.
- **Ordem jurídica fundamental**: A ideia de que a Constituição é a base do sistema jurídico
- **Processo público**: A ideia de que a Constituição é um processo contínuo e dinâmico
- **Acoplamento estrutural**: A ideia de que a Constituição é um elemento que acopa os sistemas político e jurídico

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda as diferentes concepções contemporâneas sobre a Constituição
- Identifique a relação entre a Constituição e os sistemas político e jurídico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:00:21.895920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=5", "doc_key": "31fb28a6827df0b70c95c0c4641d6310"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c723561eca69fe540cd3e3cb19adff57669f9f8ec42a2c7bc447a01f52572b55'),
  ('cpiuris2025::a7e70fbfe543ab5c5c8e74aef5808c39', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constitutivo', '## Poder Constitutivo

O Poder Constitutivo é um conceito fundamental no Direito Constitucional, que se refere à capacidade do Estado de criar e alterar suas próprias leis. Ele é dividido em três categorias: Originário, Derivado e Difuso.

### Conceitos
- **Poder Constitutivo**: capacidade do Estado de criar e alterar suas próprias leis
- **Poder Constituinte Originário**: poder que cria a Constituição atual
- **Poder Constituinte Derivado**: poder que altera ou adiciona dispositivos da Constituição existente
- **Poder Constitutivo Difuso**: poder exercido por órgãos e autoridades do Estado em geral

### Referências legais
- Art. 5º, II, da CF
- Súmula 399/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Poder Constitutivo

