- Entenda a distinção entre Poder Constitutivo e Poder Constituinte.
- Conheça as três categorias do Poder Constitutivo: Originário, Derivado e Difuso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II, da CF", "Súmula 399/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Poder Constitutivo"], "confidence": 0.8, "extracted_at": "2026-05-26T06:00:51.922551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=6", "doc_key": "a7e70fbfe543ab5c5c8e74aef5808c39"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c3d712f5c9cf620b20c2d2e0bca915324cfbbf33148800c123e4e17ccdc465f3'),
  ('cpiuris2025::6e882c76f0c8a64fa4ea8aff791abe5e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Norma Constitucional e Hermeneutica Constitucional', '## Teoria da Norma Constitucional e Hermeneutica Constitucional

O texto aborda a teoria da norma constitucional, incluindo conceitos como sistema aberto de normas, conceito e características das normas constitucionais, regras e princípios, eficácia e aplicabilidade, além de hermenêutica constitucional e seus principios.

### Conceitos
- **Sistema Aberto de Normas**: Conceito que define a Constituição como um sistema dinâmico e aberto
- **Norma Constitucional**: Regra ou princípio que compõe o sistema constitucional
- **Eficácia das Normas Constitucionais**: Capacidade da norma constitucional de produzir efeitos jurídicos
- **Interpretação Constitucional**: Proceso pelo qual se busca entender o significado das normas constitucionais

### Referências legais
- Art. 5 da CF
- Súmula 397 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Hermeneutica Constitucional

### Dicas de prova
- Entenda o conceito de sistema aberto de normas e sua importância na teoria constitucional
- Conheça as diferentes formas de interpretação constitucional e seus princípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "Súmula 397 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Hermeneutica Constitucional"], "confidence": 0.8, "extracted_at": "2026-05-26T06:01:23.612394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=6", "doc_key": "6e882c76f0c8a64fa4ea8aff791abe5e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6c344791a86faaa98b147a78ad2876546e11fd592ec9fa9b3ca6ee4da9212abe'),
  ('cpiuris2025::1e942258da5818a3e8baf8b9eb54dc55', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios da Interpretação Constitucional', '## Princípios da Interpretação Constitucional

São apresentados vários princípios que regem a interpretação das normas constitucionais, incluindo o Efeito Integrador, Máxima Efetividade e Justeza ou Conformidade Funcional.

### Conceitos
- **Efeito Integrador**: Princípio que determina que as normas constitucionais devem ser interpretadas de forma a garantir a integridade e a coesão do sistema constitucional.
- **Máxima Efetividade**: Princípio que exige que as normas constitucionais sejam interpretadas de forma a alcançar o resultado mais eficaz possível.
- **Justeza ou Conformidade Funcional**: Princípio que determina que as normas constitucionais devem ser interpretadas de forma a garantir a justiça e a conformidade com a finalidade da lei.
- **Concordância Prática ou Harmonização**: Princípio que exige que as normas constitucionais sejam interpretadas de forma a promover a concordância prática e a harmonia entre as diferentes fontes do direito.
- **Força Normativa da Constituição**: Princípio que determina que as normas constitucionais devem ser interpretadas de forma a garantir a sua força normativa e a sua capacidade de influenciar o ordenamento jurídico.
- **Proporcionalidade ou Razoabilidade**: Princípio que exige que as normas constitucionais sejam interpretadas de forma a promover a proporcionalidade e a razoabilidade na aplicação da lei.
- **Presunção de Constitucionalidade das Leis**: Princípio que determina que as leis devem ser consideradas constitucionais se não forem expressamente excluídas pela Constituição.
- **Interpretação Conforme a Constituição**: Princípio que exige que as normas legais sejam interpretadas de forma a garantir a conformidade com a Constituição.

### Referências legais
- Art. 5º, § 2º da CF/88

### Dicas de prova
- Entenda o conceito de Efeito Integrador e como ele se relaciona com a Máxima Efetividade.
- Análise do Princípio da Justeza ou Conformidade Funcional e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:02:25.526282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=6", "doc_key": "1e942258da5818a3e8baf8b9eb54dc55"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0e194b9cefb7d6a293da7c3c4bf9f8a8a38808fa6f97b6d0bd21a524a4da3893'),
  ('cpiuris2025::ad43825555f3cb19a161469824e6d39c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais da República Federativa do Brasil', '## Princípios Fundamentais da República Federativa do Brasil

Descreve os principais princípios que fundamentam a República Federativa do Brasil, incluindo o republicanismo, federalismo, estado democrático de direito e soberania popular.

### Conceitos
- **Princípio Republicano**: Garante a existência de um Estado democrático de direito
- **Princípio Federativo**: Define a relação entre o Estado e os Municípios
- **Princípio do Estado Democrático de Direito**: Estabelece que o Estado deve ser um instrumento de bem-estar social
- **Princípio da Soberania Popular**: Garante a autoridade do povo sobre o Estado
- **Princípio da Separação dos Poderes**: Define a divisão de poderes entre os três Poderes do Estado

### Referências legais
- Art. 1º da Constituição Brasileira

### Dicas de prova
- Entenda o conceito de republicanismo e sua importância na Constituição
