  ('cpiuris2025::8af6e2ec4975d04314de391a7c12ad85', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria Geral dos Direitos Fundamentais', '## Teoria Geral dos Direitos Fundamentais

