### Conceitos
- **Direito à Propriedade Intelectual**: Direito que protege criações intelectuais
- **Herança**: Direito de sucessão
- **Defesa do Consumidor**: Direito que protege os consumidores
- **Poder Judicial**: Autoridade judiciária
- **Segurança Jurídica**: Conhecimento e previsibilidade das leis
- **Princípio do Júri Natural**: Direito ao julgamento pelo povo

### Referências legais
- Art. 5º da Constituição Brasileira
- Código de Defesa do Consumidor

