### Conceitos
- **Competência**: A capacidade do juiz de julgar um processo
- **Originária**: Relacionada à competência do juiz para julgar um processo
- **Recursal**: Relacionada à competência do juiz para apreciar recursos contra decisões de outros juízes
- **Legitimidade**: A qualidade de alguém que tem direito de agir em um processo

