- Entenda a finalidade da Ação Popular
- Conheça os requisitos para a legitimidade da Ação Popular
- Aprenda sobre a competência nos processos de Ação Popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.9 (3)", "page_number": 9, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Constituição Federal", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ação Popular e Direitos Sociais"], "confidence": 0.8, "extracted_at": "2026-05-26T06:06:59.230546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=9", "doc_key": "9d433d9a50f605f5a6838d7f75fbfbe9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8841b082d758589aae9badb32a2ee499fe1b0e380f318992b3e645a89faaaa81'),
  ('cpiuris2025::535550a55fa930913d4399eef739295a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conceitos Fundamentais de Direitos da Nacionalidade', '## Conceitos Fundamentais de Direitos da Nacionalidade

Discute-se a definição e os conceitos fundamentais de direitos da nacionalidade, destacando sua importância no ordenamento jurídico brasileiro.

### Conceitos
- **Direito da Nacionalidade**: direito que regula as relações entre o Estado e seus cidadãos
- **Cidadania Brasileira**: status jurídico conferido aos brasileiros

### Referências legais
- Art. 12 da Constituição de 1988

### Dicas de prova
- Entenda a definição de direito da nacionalidade e sua relação com a cidadania brasileira.
- Conheça os conceitos fundamentais que regem os direitos da nacionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.9 (4)", "page_number": 9, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12 da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:07:17.015581+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=9", "doc_key": "535550a55fa930913d4399eef739295a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '779cfb04d012f492669018a74949d39f0ae6e60463abcc2a41bd194e279bb6b2'),
  ('cpiuris2025::68837b30e3fcb86afc272cb8c09001f3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Nacionalidade Brasileira', '## Nacionalidade Brasileira

Descreve as espécies de nacionalidade, direitos políticos positivos e negativos, ação de impugnação de mandato eleitoral e princípio da anterioridade eleitoral.

### Conceitos
- **Nacionalidade Brasileira**: Condição de ser brasileiro
- **Brasileiro NATO**: Pessoa nascida no exterior, com pai brasileiro
- **Brasileiro Naturalizado**: Pessoa estrangeira naturalizada brasileira
- **Princípio da Reciprocidade**: Requisito para a concessão de nacionalidade

### Referências legais
- Art. 12 da Constituição Brasileira

### Dicas de prova
- Distinção entre nacionalidade nata e naturalizada
- Conceito de princípio da reciprocidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12 da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:07:52.295290+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=10", "doc_key": "68837b30e3fcb86afc272cb8c09001f3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5cd55994fb7b3c639cb05e58f755b45dc7b6f6205f3a48eac98ad26dd8755e68'),
  ('cpiuris2025::265850a4692f4e184e8a5abdf1efc80a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Formas de Estado e Regime de Governo', '## Formas de Estado e Regime de Governo

Descreve as formas de Estado (federado, unitário, confederação) e os regimes de governo (democrático, autocrático) no Brasil.

### Conceitos
- **Estado Federado**: Forma de Estado em que o poder é exercido por um governo central e pelos estados federados
- **Sistema Presidencialista**: Sistema de governo em que o presidente é o chefe do estado e da administração
- **Regime Democrático**: Forma de governo que prioriza a liberdade, igualdade e participação cívica
- **Confederação**: Forma de Estado em que os estados são soberanos e têm autonomia para governar-se

### Referências legais
- Art. 1 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a diferença entre sistema presidencialista e parlamentarista
- Conheça as características de um regime democrático e autocrático', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.6, "extracted_at": "2026-05-26T06:08:17.692253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=10", "doc_key": "265850a4692f4e184e8a5abdf1efc80a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0d896c4c25416376b2550de7c473fd17c38d8d2f9ea55d5a0e911ab64ff92779'),
  ('cpiuris2025::1ed627b25ece3d473998157a012856c6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Classificações do federalismo e Federação de equilíbrio', '## Classificações do federalismo e Federação de equilíbrio

A seção discute as classificações do federalismo, destacando a auto-organização, autogoverno, autoadministração, técnicas de repartição de competências entre os entes, federação de equilíbrio e garantias à federação.

### Conceitos
- **Auto-organização**: Processo pelo qual os entes federados se autogovernam e organizam suas relações internas.
- **Autogoverno**: Repartição de competências entre os entes federados para que cada um possa governar-se.
- **Autoadministração**: A capacidade dos entes federados de administrar suas próprias questões internas.
- **Técnicas de repartição de competências**: Métodos utilizados para dividir as competências entre os entes federados.
- **Federação de equilíbrio**: Repartição de competências que busca equilibrar as relações entre a União e os estados.
- **Garantias à federação**: Proteções constitucionais destinadas a garantir os direitos dos entes federados.
- **União**: Entidade política que representa o Estado brasileiro.

### Referências legais
- Art. 1 da Constituição de 1988

### Dicas de prova
- Entenda a importância das técnicas de repartição de competências.
- Reconheça as diferenças entre auto-organização e autogoverno.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.10 (3)", "page_number": 10, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:08:53.870196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=10", "doc_key": "1ed627b25ece3d473998157a012856c6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0364116dd60ff981e20d1f9ba54523ed514b27012ec2934d3148789e7901f246'),
  ('cpiuris2025::e42efbc9a9f5f9b3aa27e15f244c0783', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Federal', '## Intervenção Federal

Artigos que definem as formas de intervenção federal no Estado, suas características e requisitos.

### Conceitos
- **Intervenção Federal Espontânea**: ocorrência natural do interesse público
- **Intervenção Federal Provocada**: ação direta do Poder Executivo

### Referências legais
- Art. 24, § 1º, da CF/88

### Dicas de prova
- Diferenciar entre espontânea e provocada
- Entender o interesse público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.10 (4)", "page_number": 10, "discipline": "Direito Constitucional", "legal_refs": ["Art. 24, § 1º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:09:18.639139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=10", "doc_key": "e42efbc9a9f5f9b3aa27e15f244c0783"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7f18f8ce3a4de4115cb9c9f3c0e222c931d0426603be6192eb125c9f5739fe0b'),
  ('cpiuris2025::62ebfc4f5760849fd8199d70aa7f08de', 'doutrina', 'cp_iuris', 'Direito Constitucional — Administração Pública e Supremacia do Interesse Público', '## Administração Pública e Supremacia do Interesse Público

Discute os princípios que regem a Administração Pública, incluindo a supremacia do interesse público, indisponibilidade deste e os princípios da legalidade, impessoalidade, moralidade, publicidade, eficiência e organização do Serviço Público.

### Conceitos
- **Princípio da Legalidade**: O princípio que exige que as ações administrativas sejam previamente autorizadas por lei.
- **Impessoalidade**: A incompatibilidade entre o servidor público e os interesses de terceiros.
- **Moralidade**: O princípio que exige que as ações administrativas sejam feitas com integridade e honestidade.
- **Publicidade**: A transparência das ações administrativas, permitindo que os cidadãos tenham acesso a informações sobre o funcionamento do Estado.
- **Eficiência**: O princípio que exige que as ações administrativas sejam feitas de forma eficaz e econômica.
- **Organização Legal do Serviço Público Federal**: A estrutura organizacional do Serviço Público no âmbito federal.
- **Organização Legal do Serviço Público Estadual**: A estrutura organizacional do Serviço Público nos estados.

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a importância dos princípios da Administração Pública para responder às questões do exame.
- Não confunda os princípios com as normas legais, é fundamental entender a diferença entre eles.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:09:58.167551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=11", "doc_key": "62ebfc4f5760849fd8199d70aa7f08de"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9286a639e5cf36cc6d92c2584cca8c99375c92dbc0521b22d3c711ef0275853d'),
  ('cpiuris2025::6f294c217ff9e1206f3a87d9d524f3aa', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ingresso no Serviço Público e Regime Jurídico dos Agentes Públicos', '## Ingresso no Serviço Público e Regime Jurídico dos Agentes Públicos

Discute as regras para o ingresso no serviço público, incluindo cargos privativos de brasileiro nato, concurso público, prazo de validade do concurso e direito subjetivo ao cargo público.

### Conceitos
- **Cargos privativos**: Cargo que só pode ser ocupado por um brasileiro nato
- **Concurso público**: Mecanismo para seleção de candidatos para cargos públicos
- **Prazo de validade do concurso**: Período durante o qual o concurso está válido e pode ser realizado
- **Direito subjetivo ao cargo público**: Direito do servidor público de manter seu cargo após a aposentadoria ou demissão
- **Funções de confiança**: Cargo que não é de exclusiva competência da União, Estado ou Município
- **Contratação por tempo determinado**: Acordo entre o empregador e o empregado para um período específico

### Referências legais
- Art. 37, Caput, da Constituição Federal

### Dicas de prova
- Entenda a distinção entre cargos privativos e concurso público
- Conheça o prazo de validade do concurso público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:10:30.309841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=11", "doc_key": "6f294c217ff9e1206f3a87d9d524f3aa"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e16e35504457f251837c14b0ca2f9ee148137d795e0525281b1aeadc5c4bd327'),
  ('cpiuris2025::a83eaca8606fc8f77fb2cec0018a9ec1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Composição e Attribuições do Congresso Nacional', '## Composição e Attribuições do Congresso Nacional

Descreve a composição do Congresso Nacional, suas atribuições e órgãos, além de estatuto dos congressistas.

### Conceitos
- **Congresso Nacional**: órgão legislativo federal
- **Câmara dos Deputados**: casa baixa do Congresso Nacional
- **Senado Federal**: casa alta do Congresso Nacional
- **Órgãos do Congresso Nacional**: mesas diretoras, comissões e plenário
- **Atribuições do Congresso Nacional**: legislar, fiscalizar e controlar o Poder Executivo
- **Estatuto dos Congresistas**: rege as relações entre os membros do Congresso Nacional

### Referências legais
- Art. 29 da Constituição de 1988

### Dicas de prova
- Entenda a composição e as atribuições do Congresso Nacional
- Conheça os órgãos que compõem o Congresso Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.11 (3)", "page_number": 11, "discipline": "Direito Constitucional", "legal_refs": ["Art. 29 da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:11:08.019636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=11", "doc_key": "a83eaca8606fc8f77fb2cec0018a9ec1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '40db1253e2b8d9ed3c06afeb203ce9ace1b9773662165404056b45cac6537554'),
  ('cpiuris2025::b659c4ace001c757d830d42d7f45095c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Renúncia ao mandato', '## Renúncia ao mandato

A renúncia ao mandato é a decisão do eleito para não assumir o cargo, sendo um direito dos membros do Congresso Nacional e do Senado Federal.

### Conceitos
- **renúncia ao mandato**: Decisão do eleito para não assumir o cargo
- **direito dos membros do Congresso Nacional e do Senado Federal**: Direito que lhe confere a capacidade de renunciar ao mandato

### Referências legais
- Art. 60, § 4º da CF

### Dicas de prova
- Distinção entre renúncia e abdicação
- Conhecimento do artigo que regula a renúncia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.11 (4)", "page_number": 11, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, § 4º da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:11:26.509875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=11", "doc_key": "b659c4ace001c757d830d42d7f45095c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '67e961cc318475c0e32aa3e527c0f30df46fe472b13195fc4d1ab825a58d13f9'),
  ('cpiuris2025::a268fc41255b48523b2ce1e276465c1c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo', '## Processo Legislativo

Descreve as fases e espécies de normas do processo legislativo, incluindo a classificação em ordinário e sumário.

### Conceitos
- **Processo Legislativo**: O conjunto de atos e procedimentos necessários para a elaboração e aprovação de leis.
- **Lei Ordinária**: Lei que tem origem em um projeto de lei apresentado pelo Congresso Nacional.
- **Lei Complementar**: Lei que complementa a Constituição Federal ou uma das suas leis.
- **Emenda à Constituição**: Modificação da Constituição Federal por meio de um processo legislativo específico.
- **Lei Delegada**: Lei que delega poderes a outro ente para emitir leis ou regulamentos.
- **Fase do Processo Legislativo Ordinário**: O processo de elaboração e aprovação de uma lei, incluindo as fases de apresentação, discussão e votação.
- **Fase do Processo Legislativo Sumário**: O processo de elaboração e aprovação de uma lei em um prazo mais curto do que o ordinário.
- **Classificação do Processo Legislativo**: A classificação do processo legislativo em ordinário e sumário, com base na forma de organização política e no rito.

### Referências legais
- Art. 58 da Constituição Federal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a classificação do processo legislativo em ordinário e sumário.
- Conheça as fases do processo legislativo, incluindo a apresentação, discussão e votação da lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:12:11.776037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=12", "doc_key": "a268fc41255b48523b2ce1e276465c1c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'be4ab05d57436b88ab2f0bfb390c255ab50278f95ea2bfd937ba74827d3049fc'),
  ('cpiuris2025::64375ca4b75f1b614aa4ee6dd6b3827c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo e Poder Executivo', '## Processo Legislativo e Poder Executivo

Descreve as diferentes espécies normativas, processos legislativos e controle judicial do poder executivo.

### Conceitos
- **Decretos Legislativos**: Lei aprovada pelo Congresso Nacional
- **Resoluções**: Decisão tomada por órgãos legislativos
- **Processo Legislativo**: Procedimento para aprovação de leis
- **Poder Executivo**: Unidade do Estado que exerce a autoridade política e administrativa
- **Investidura**: Ato pelo qual o presidente é eleito ou nomeado
- **Impedimentos e Vacâncias**: Procedimento para remover o presidente da função

### Referências legais
- Art. 58 da CF/88
- Súmula 822 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Processo Legislativo

### Dicas de prova
- Entenda a hierarquia entre as espécies normativas
- Conheça o processo legislativo e o poder executivo
- Identifique os impedimentos e vacâncias no presidente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da CF/88", "Súmula 822 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Processo Legislativo"], "confidence": 0.8, "extracted_at": "2026-05-26T06:12:51.280345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=12", "doc_key": "64375ca4b75f1b614aa4ee6dd6b3827c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bdd26fa022102bce432c792f704d1a8017cfcb5e830a10589d547b2914bb4531'),
  ('cpiuris2025::6e1086318cf611084e01035ae5db003e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Atribuições do Presidente da República e outros órgãos do Poder Executivo', '## Atribuições do Presidente da República e outros órgãos do Poder Executivo

Descreve as atribuições do Presidente da República, Vice-Presidente da República, Ministros de Estado, Órgãos Consultivos e Responsabilidade do Presidente da República.

### Conceitos
- **Atribuição**: Direito conferido a uma entidade ou pessoa para exercer um poder específico
- **Responsabilidade**: Obrigação de cumprir com uma tarefa ou dever
- **Crimes de responsabilidade**: Delitos cometidos por funcionários públicos em exercício de mandato
- **Órgãos Consultivos**: Entidades que consultam o Presidente da República sobre questões específicas
- **Poder Executivo**: Unidade do Estado que exerce a autoridade política e administrativa

### Referências legais
- Art. 77, § 2º da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Atribuições do Presidente da República

### Dicas de prova
- Entenda a distinção entre crimes de responsabilidade e crimes comuns
