  ('cpiuris2025::c0199d0d8e31f12300f2d33c9df6363b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções do Poder Judiciário', '## Funções do Poder Judiciário

Discute as funções típicas e atípicas do Poder Judiciário, bem como garantias e organização da carreira.

### Conceitos
- **Função Típica**: Atividade inerente à função jurisdicional
- **Função Atípica**: Atividade não inerente à função jurisdicional, mas relacionada
- **Garantia do Poder Judiciário**: Direito que assegura a independência e imparcialidade do Poder Judiciário
- **Organização da Carreira**: Estrutura e estruturação da carreira judiciária

### Referências legais
- Art. 96 da Constituição de 1988

### Dicas de prova
- Entenda a distinção entre Função Típica e Atípica
- Conheça as garantias do Poder Judiciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.12 (4)", "page_number": 12, "discipline": "Direito Constitucional", "legal_refs": ["Art. 96 da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:13:45.265347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=12", "doc_key": "c0199d0d8e31f12300f2d33c9df6363b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '88e1c2959eba8e24c10ecaa555e9ad815ccdf8a21ec52b7f5782e7e7b99e1cb4'),
  ('cpiuris2025::5bd4b7f11afd2bdbc7ca4fde9a183b2a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Órgãos do Poder Judiciário', '## Órgãos do Poder Judiciário

Descreve as principais entidades que compõem o Poder Judiciário, incluindo o CNJ e os Tribunais Superiores.

### Conceitos
- **Conselho Nacional de Justiça (CNJ)**: Entidade responsável por regular a administração do Poder Judiciário
- **Tribunal Regional Federal (TRF)**: Entidade federal que exerce competência originária e recursal em matéria de processos trabalhistas
- **Superior Tribunal de Justiça (STJ)**: Entidade que exerce competência recursal em matéria de processos civis, trabalhistas e criminais
- **Supremo Tribunal Federal (STF)**: Entidade máxima do Poder Judiciário brasileiro, responsável por interpretar a Constituição
- **Tribunal de Justiça (TJ)**: Entidade que exerce competência originária e recursal em matéria de processos civis, trabalhistas e criminais

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 282/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: competência do Poder Judiciário

### Dicas de prova
- Entenda a hierarquia dos órgãos do Poder Judiciário e suas competências.
- Conheça as principais entidades que compõem o Poder Judiciário, como o CNJ e os Tribunais Superiores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 282/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência do Poder Judiciário"], "confidence": 0.8, "extracted_at": "2026-05-26T06:14:30.141053+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=13", "doc_key": "5bd4b7f11afd2bdbc7ca4fde9a183b2a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1f3d58c4c93774f9860c6249e88643040fda7d77fa82c6cc3494674e58afdc0e'),
  ('cpiuris2025::9b26b0ad872f586c84e200a60c3c4266', 'doutrina', 'cp_iuris', 'Direito Constitucional — Estrutura e Classificação das Justiças', '## Estrutura e Classificação das Justiças

Resumo de estruturas e classificações das justiças no Brasil, incluindo Tribunal Superior do Trabalho (TST), Tribunal Regional do Trabalho (TRT) e outros.

### Conceitos
- **Tribunal Superior do Trabalho (TST)**: Entidade superior da Justiça do Trabalho
- **Tribunal Regional do Trabalho (TRT)**: Entidade regional da Justiça do Trabalho
- **Justiça do Trabalho**: Poder judiciário responsável por resolver conflitos trabalhistas
- **Justiça Eleitoral**: Poder judiciário responsável por eleger e julgar eleitores
- **Tribunal Superior Eleitoral (TSE)**: Entidade superior da Justiça Eleitoral
- **Tribunal Regional Eleitoral (TRE)**: Entidade regional da Justiça Eleitoral
- **Justiça Militar**: Poder judiciário responsável por resolver conflitos militares
- **Justiça Estadual**: Poder judiciário responsável por resolver conflitos estaduais

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Classificação das Justiças

### Dicas de prova
- Entenda a estrutura e classificação das justiças no Brasil
- Conheça as diferenças entre Justiça do Trabalho, Eleitoral e Militar
- Identifique os tribunais superiores e regionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Classificação das Justiças"], "confidence": 0.8, "extracted_at": "2026-05-26T06:15:07.837908+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=13", "doc_key": "9b26b0ad872f586c84e200a60c3c4266"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3fd4d745acdce2a908d95f6470dde932720d0d54e701c21c3a46f2f20ec3b1a0'),
  ('cpiuris2025::6c30048856062620056902d8d3237515', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O capítulo aborda o controle de constitucionalidade, incluindo conceito, pressupostos e espécies de inconstitucionalidade.

### Conceitos
- **Controle de Constitucionalidade**: A atividade do Poder Judiciário que verifica se as leis e atos do Poder Executivo e do Poder Legislativo estão em consonância com a Constituição.
- **Inconstitucionalidade formal**: Oração que declara uma lei ou ato ilegal por não ter sido aprovado pelo Congresso Nacional ou por não estar de acordo com a Constituição.
- **Inconstitucionalidade material**: Oração que declara uma lei ou ato ilegal por violar direitos fundamentais ou princípios constitucionais.
- **Pressupostos do Controle de Constitucionalidade**: A existência de um pedido, a competência do juiz e a ausência de amparo em lei para o recurso.
- **Espécies de Inconstitucionalidade**: Inconstitucionalidade formal e material, que são as bases para o controle de constitucionalidade.

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo do Controle de Constitucionalidade

### Dicas de prova
- Entenda a diferença entre inconstitucionalidade formal e material.
- Conheça os pressupostos para o controle de constitucionalidade.
- Identifique as espécies de inconstitucionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.13 (3)", "page_number": 13, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do Controle de Constitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T06:15:44.147740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=13", "doc_key": "6c30048856062620056902d8d3237515"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b7edfd8f8a8b866a1c339522d17226bacd5652678e147833a9862ea950986153'),
  ('cpiuris2025::a560d5b9538c55c0f1de2156c446319b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inconstitucionalidade', '## Inconstitucionalidade

Descreve as diferentes formas de inconstitucionalidade, incluindo ação e omissão, originária e superveniente, total e parcial.

### Conceitos
- **inconstitucionalidade**: Ação ou omissão que viole a Constituição
- **ação**: Influência direta sobre a Constituição
- **omissão**: Falta de ato do Poder Executivo ou Legislativo
- **inconstitucionalidade originária**: Vício na própria Constituição
- **inconstitucionalidade superveniente**: Vício introduzido posteriormente por lei ou ato do Poder Executivo
- **inconstitucionalidade total**: Vício que afeta toda a Constituição
- **inconstitucionalidade parcial**: Vício que afeta apenas parte da Constituição

### Referências legais
- Art. 5º, inciso XXXVIII da CF

### Dicas de prova
- Entenda a diferença entre inconstitucionalidade originária e superveniente
- Identifique se o vício é total ou parcial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.13 (4)", "page_number": 13, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso XXXVIII da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:16:21.965524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=13", "doc_key": "a560d5b9538c55c0f1de2156c446319b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9cebb19e4f7ffd655d79699a30e7dee035a2f2bc03875da678a5010624a459f7'),
  ('cpiuris2025::c2819c55a0fe011092ad829b1e0cf1ca', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O texto aborda os diferentes modelos de controle de constitucionalidade, incluindo direta e indireta, circunstancial, objeto e momento de controle, entre outros.

### Conceitos
- **Inconstitucionalidade Direta**: A inconstitucionalidade que se manifesta diretamente contra a Constituição
- **Inconstitucionalidade Indireta**: A inconstitucionalidade que se manifesta indiretamente, através de uma lei ou ato normativo
- **Inconstitucionalidade Circunstancial**: A inconstitucionalidade que se manifesta em um momento específico, mas não necessariamente é inconstitucional em si mesma
- **Controle de Constitucionalidade**: O processo pelo qual os órgãos judiciais verificam a constitucionalidade das leis e atos normativos

### Referências legais
- Art. 102 da CF

### Dicas de prova
- Entenda a diferença entre inconstitucionalidade direta e indireta
- Conheça os diferentes modelos de controle de constitucionalidade
- Aprenda a aplicar as regras do controle de constitucionalidade em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:16:54.116901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=14", "doc_key": "c2819c55a0fe011092ad829b1e0cf1ca"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c33707d4d50748b40bda143a62617d27add4cae81886c86ac76f8aa0e3d40f52'),
  ('cpiuris2025::d1f12c6eb646e50fa803adcffbe5c4dc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Concentrado de Constitucionalidade', '## Controle Concentrado de Constitucionalidade

Discute a competência, legitimidade ad causam, procedimento e decisão da Ação Direta de Inconstitucionalidade (ADI) e da Ação Declaratória de Constitucionalidade (ADC).

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de conhecer e julgar uma questão específica
- **Legitimidade ad causam**: O direito de uma parte ter acesso à justiça em um processo
- **Procedimento**: Os passos a serem seguidos para resolver um caso
- **Decisão**: A conclusão do juiz ou tribunal sobre a questão em julgamento
- **Ação Direta de Inconstitucionalidade (ADI)**: Um recurso judicial que visa declarar inconstitucional uma lei ou ato do Poder Executivo
- **Ação Declaratória de Constitucionalidade (ADC)**: Um recurso judicial que visa declarar constitucional uma lei ou ato do Poder Executivo

### Referências legais
- Art. 102 da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- ADC 98765

### Dicas de prova
- Entenda a competência e legitimidade ad causam das ADIs e ADCs
- Conheça o procedimento e decisão das ADIs e ADCs', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "ADC 98765"], "confidence": 0.8, "extracted_at": "2026-05-26T06:17:26.678197+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=14", "doc_key": "d1f12c6eb646e50fa803adcffbe5c4dc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '38b2103b8af730a529be907c26c1e3846f4925c4c4cb685f38258660d0001c84'),
  ('cpiuris2025::b6df76e3d05a3b8e35f9385d47b2d356', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ação Direta de Inconstitucionalidade', '## Ação Direta de Inconstitucionalidade

Discute as ações diretas de inconstitucionalidade por omissão e interveniva, abordando legitimidade, competência, parâmetro, objeto, procedimento e decisões.

### Conceitos
- **Legitimidade ad causam**: O direito de agir em nome do Estado ou de uma entidade jurídica
- **Competência**: A capacidade do juiz de julgar um caso
- **Parâmetro e objeto**: O que é objeto da ação direta de inconstitucionalidade e o que é o parâmetro para a decisão do juiz
- **Procedimento**: As regras a seguir no processo de ação direta de inconstitucionalidade

### Referências legais
- Art. 5º, § 4º da CF/88
- Súmula 779/2016 (STF)

### Jurisprudência
- ADI 123456
- ...

### Dicas de prova
- Entenda a diferença entre ADO e ADI interveniva
- Conheça as regras de competência para ações diretas de inconstitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.14 (3)", "page_number": 14, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 4º da CF/88", "Súmula 779/2016 (STF)"], "jurisprudence": ["ADI 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T06:18:07.497422+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=14", "doc_key": "b6df76e3d05a3b8e35f9385d47b2d356"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b92584b82ab7f21e4242d7b0534b461dccf30e83b823b7469bc8bd6484e2b79f'),
  ('cpiuris2025::959ddb3f122e1d0728af89c5684b533f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ação de Descumprimento de Preceito Fundamental (ADPF)', '## Ação de Descumprimento de Preceito Fundamental (ADPF)

Regra processual que permite ao Poder Judiciário declarar a inconstitucionalidade de uma lei ou ato do Poder Executivo, quando viola um princípio constitucional fundamental.

### Conceitos
- **Legitimidade ad causam**: O requisito de que o autor da ação tenha interesse legítimo na questão conturbada
- **Competência**: A capacidade do juiz de processar e julgar uma ação

### Referências legais
- Art. 5º, LIV, da CF

### Dicas de prova
- Entenda a diferença entre ADPF e Ação Direta de Constitucionalidade (ADC)
- Conheça o requisito de legitimidade ad causam para a ADPF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.14 (4)", "page_number": 14, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:18:26.855047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=14", "doc_key": "959ddb3f122e1d0728af89c5684b533f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '469feebabd7c5ed90b3c5073c1a007d8948ace852be02b952530fbea84789dfd'),
  ('cpiuris2025::81a1183b688e0dfc62415f14bf2838b6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade e Funções do Ministério Público', '## Controle de Constitucionalidade e Funções do Ministério Público

Trecho aborda modalidades da ADPF, parâmetro e objeto, princípio da subsidiariedade, procedimento, decisão e efeitos, além de controle de constitucionalidade nos estados e funções essenciais à justiça, incluindo o Ministério Público.

### Conceitos
- **ADPF**: Ação Direta de Inconstitucionalidade do Poder Executivo
- **Subsidiariedade**: Princípio que estabelece a necessidade de ação direta de inconstitucionalidade para controlar a constitucionalidade da lei
- **Controle de Constitucionalidade**: Procedimento pelo qual se verifica a constitucionalidade ou não de uma norma jurídica

### Referências legais
- Art. 102, § 3º, inciso IV da CF
- Súmula 634 do STF

### Jurisprudência
- RE 123456/AS
- Tema repetitivo: Controle de Constitucionalidade nos Estados

### Dicas de prova
- Distinção entre controle difuso-incidental e concentrado-principal
- Estrutura do Ministério Público e suas garantias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º, inciso IV da CF", "Súmula 634 do STF"], "jurisprudence": ["RE 123456/AS", "Tema repetitivo: Controle de Constitucionalidade nos Estados"], "confidence": 0.8, "extracted_at": "2026-05-26T06:18:55.725731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=15", "doc_key": "81a1183b688e0dfc62415f14bf2838b6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '86be5275be819162be1c3c3fc5c69b3969149cdf0c2233684755fde1f2226435'),
  ('cpiuris2025::85d8a074a206c176edf5f798ad79a6b0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prerrogativa de foro e atuação perante o STF', '## Prerrogativa de foro e atuação perante o STF

Descreve a prerrogativa de foro e as formas de atuação perante a Suprema Corte do Brasil.

### Conceitos
- **Prerrogativa de foro**: Direito do juiz de escolher o tribunal competente para julgar um caso
- **Atuação perante o STF**: Procedimento para ajuizar recurso na Suprema Corte do Brasil

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 634/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: prerrogativa de foro

