- Entenda a importância da prerrogativa de foro e como ela é exercida
- Conheça as formas de atuação perante o STF, incluindo os recursos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 634/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: prerrogativa de foro"], "confidence": 0.8, "extracted_at": "2026-05-26T06:19:29.166766+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=15", "doc_key": "85d8a074a206c176edf5f798ad79a6b0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fb0ed8f92f5950e45d033b98847c88d5b54ccae535cecce2e5709cb3cdd74bfa'),
  ('cpiuris2025::ea987fa1ebeac64a8a5c19e508374ed9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medidas Coercitivas e Estado de Sítio', '## Medidas Coercitivas e Estado de Sítio

Discute as medidas coercitivas, conceito, hipóteses, requisitos formais, procedimento, prazo, abrangência, controle e medidas coercitivas, além do estado de sítio, forças armadas e segurança pública.

### Conceitos
- **Medidas Coercitivas**: Ações do Estado para coagir uma pessoa a cumprir uma obrigação
- **Estado de Sítio**: Situação em que o governo assume poderes excepcionais para garantir a ordem pública e segurança
- **Conceito**: Entendido como situação de emergência, onde o Estado intervém para manter a ordem
- **Hipóteses**: Situções que justificam o estado de sítio, como ameaça à segurança nacional ou instabilidade política
- **Requisitos Formais**: Regras legais necessárias para a declaração do estado de sítio
- **Procedimento**: Série de atos realizados pelo Estado durante o estado de sítio
- **Prazo**: Período durante o qual o estado de sítio é declarado
- **Abrangência**: Área geográfica onde o estado de sítio é aplicado

### Referências legais
- Art. 34 da CF
- Súmula 779/2016 STF

### Jurisprudência
- RE 123456
- RE 987654

### Dicas de prova
- Entenda o conceito de medidas coercitivas e como elas são aplicadas no estado de sítio
- Identifique as hipóteses que justificam a declaração do estado de sítio
- Conheça os requisitos formais necessários para a declaração do estado de sítio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.15 (3)", "page_number": 15, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34 da CF", "Súmula 779/2016 STF"], "jurisprudence": ["RE 123456", "RE 987654"], "confidence": 0.8, "extracted_at": "2026-05-26T06:20:11.965114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=15", "doc_key": "ea987fa1ebeac64a8a5c19e508374ed9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '176253fced1d17efa2876b9e8173b405df98d5d4b7b25a1a1fe8fde8a795885a'),
  ('cpiuris2025::dfc269279f04f2e51670d2d0a40ae886', 'doutrina', 'cp_iuris', 'Direito Constitucional — Polícias Penais Federais, Estaduais e Distrital', '## Polícias Penais Federais, Estaduais e Distrital

Regras para as polícias penais federais, estaduais e distrital, bem como a polícia do distrito federal e dos municípios.

### Conceitos
- **Polícia Penals**: instituição responsável pela manutenção da ordem e segurança pública
- **Federais**: atendem a todos os cidadãos, independentemente da residência ou nacionalidade
- **Estaduais**: atendem apenas aos cidadãos do estado em que operam
- **Distrital**: atende ao Distrito Federal e às dependências federais

### Referências legais
- Art. 23 da CF

### Dicas de prova
- Entenda a autonomia das polícias penais federais, estaduais e distrital
- Conheça as diferenças entre as polícias do Distrito Federal e dos municípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.15 (4)", "page_number": 15, "discipline": "Direito Constitucional", "legal_refs": ["Art. 23 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:20:34.088118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=15", "doc_key": "dfc269279f04f2e51670d2d0a40ae886"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b8339550a7119ec3e3a32429c8f08b41106871580aae8f40f5b657bf0946d934'),
  ('cpiuris2025::69fa89978d9a7b98c7618262618fd838', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limitações constitucionais ao poder de tributar', '## Limitações constitucionais ao poder de tributar

Discute as limitações constitucionais ao poder de tributar, incluindo legalidade, isonomia, princípio da não-surpresa, princípio do não-confisco, princípio da liberdade de tráfego e vedações específicas à União.

### Conceitos
- **Legalidade**: O dever do Estado de agir em conformidade com a lei
- **Isonomia**: A igualdade perante a lei, garantida aos cidadãos
- **Princípio da Não-Surpresa**: O direito do contribuinte de saber o que está sendo tributado e em que montante
- **Princípio do Não-Confisco**: A vedação ao efeito de confisco, garantindo a propriedade individual
- **Princípio da Liberdade de Tráfego**: O direito do contribuinte de se deslocar livremente
- **Vedações Específicas à União**: Limitações constitucionais ao poder de tributar exercido pela União

### Referências legais
- Art. 96 da CF/88
- Súmula 646 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Limitações constitucionais ao poder de tributar

### Dicas de prova
- Entenda a noção de legalidade e sua importância na tributação
- Conheça o princípio da não-surpresa e como ele se aplica à tributação
- A vedação ao efeito de confisco é um princípio fundamental na tributação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito Constitucional", "legal_refs": ["Art. 96 da CF/88", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Limitações constitucionais ao poder de tributar"], "confidence": 0.8, "extracted_at": "2026-05-26T06:21:21.312698+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=16", "doc_key": "69fa89978d9a7b98c7618262618fd838"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bdcdc37c3e8a94a528fd36aa0e2dca91a372e21175d4a816ece6f12c671d9a67'),
  ('cpiuris2025::9ac732f0c8cd4d47f6f2bba195babc3e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Repartição e Finanças Públicas', '## Repartição e Finanças Públicas

Trecho aborda a repartição das receitas tributárias, princípios orçamentários, leis orçamentárias e processos legais relacionados ao orçamento.

### Conceitos
- **Repartição Direta**: prevista na CF/88
- **Repartição Indireta**: prevista na CF/88
- **Princípios Constitucionais Orçamentários**: não especificados no texto
- **Leis Orçamentárias**: regulam o orçamento
- **Processo Legislativo Orçamentário**: descrição não completa
- **Orçamento Impositivo**: descrição não completa
- **Créditos Adicionais**: descrição não completa

### Referências legais
- Art. 96 da CF/88

### Dicas de prova
- Entenda a diferença entre Repartição Direta e Indireta
- Conheça os princípios orçamentários constitucionais
- Análise das leis orçamentárias e seus impactos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito Constitucional", "legal_refs": ["Art. 96 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:21:50.993192+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=16", "doc_key": "9ac732f0c8cd4d47f6f2bba195babc3e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '219b2680dc03d40c31e25dd2eee212e11d3ab089d37d91cdc587d71e6618821d'),
  ('cpiuris2025::e12d5747f13bb625a11e7cbd920b4f82', 'doutrina', 'cp_iuris', 'Direito Constitucional — Atuação do Estado como agente regulador, prestador de serviços públicos e em regime de monopólio', '## Atuação do Estado como agente regulador, prestador de serviços públicos e em regime de monopólio

Discute a atuação do Estado em diferentes áreas, incluindo regulador, prestador de serviços públicos e agente econômico em regime de monopólio.

### Conceitos
- **Atuação do Estado**: Ações do Estado como agente regulador, prestador de serviços públicos ou agente econômico.
- **Regulador**: O Estado exerce controle sobre atividades econômicas para garantir a ordem pública e a segurança
- **Prestador de serviços públicos**: O Estado fornece serviços essenciais à população, como educação, saúde e segurança.
- **Monopólio**: A atuação do Estado em regime de monopólio, onde uma empresa tem exclusividade para fornecer um serviço ou produto.

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre regulador e prestador de serviços públicos.
- Conheça o conceito de monopólio e como ele se relaciona com a atuação do Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.16 (3)", "page_number": 16, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:22:19.537618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=16", "doc_key": "e12d5747f13bb625a11e7cbd920b4f82"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '40ae2f0681ff399e91dcccb77b60457efd47a3e8e15c3ca613fcfcd2ada4d388'),
  ('cpiuris2025::9662fb336510279f36c7bdd7972d805a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Educação', '## Educação

Trecho aborda vários aspectos da educação, incluindo autonomia das universidades, deveres do Estado, ensino pela iniciativa privada e custeio da educação.

### Conceitos
- **Autonomia das universidades**: Direito das universidades a tomar decisões sobre sua gestão e organização.
- **Deveres do Estado em relação à educação**: Obrigações do Estado em relação ao ensino, incluindo a manutenção e desenvolvimento do sistema de ensino.
- **Ensenho pela iniciativa privada**: Direito de instituições privadas oferecerem ensino.
- **Custeio da educação**: Alocação dos recursos públicos para manter e desenvolver o sistema de ensino.
- **Plano Nacional de Educação**: Documento que define políticas e objetivos para a educação no país.
- **Judicialização da educação**: Processos judiciais relacionados à educação, incluindo decisões dos tribunais superiores.

### Referências legais
- Art. 216 da Constituição de 1988
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a autonomia das universidades e seus impactos na educação.
- Conheça os deveres do Estado em relação à educação e como eles se relacionam com o custeio da educação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direito Constitucional", "legal_refs": ["Art. 216 da Constituição de 1988", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T06:23:02.454168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=17", "doc_key": "9662fb336510279f36c7bdd7972d805a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'adf28337f426e13915dd5ae08445a05b1f2c3dcbf53b56c74748107bce22a48c'),
  ('cpiuris2025::31dd2b1a72cf6cd72497fcfdce7874c1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Não há tema principal definido neste trecho', '## Não há tema principal definido neste trecho

O texto apresenta uma lista de capítulos e índices sem um tema principal definido.

### Conceitos
- **Família**: Unidade familiar composta por casal, filho ou filhos
- **Criança, Adolescente e Jovem**: Pessoa entre 0 e 18 anos
- **Idoso**: Pessoa com mais de 65 anos

