- Família, Criança, Adolescente e Jovem são conceitos importantes para Direito Constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Direito Constitucional", "legal_refs": [], "jurisprudence": [], "confidence": 0.2, "extracted_at": "2026-05-26T06:23:18.821818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=17", "doc_key": "31dd2b1a72cf6cd72497fcfdce7874c1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '412b9acf17bea20e5d6b8a5238684dac001e479336fbc62c7b9f06d5ca8b4f0e'),
  ('cpiuris2025::65634a9e773fba2d315d6d39b6b06840', 'doutrina', 'cp_iuris', 'Direito Constitucional — Noções Introduatórias', '## Noções Introduatórias

O Direito Constitucional é a disciplina que integra o ramo do Direito Público, estudando a organização e funcionamento do Estado. O objeto de estudo é a própria Constituição, com foco na atual Constituição Federal de 1988.

### Conceitos
- **Direito Público Fundamental**: Disciplina que integra o ramo do Direito Público
- **Constitucionalismo**: Teoria que estuda a Constituição como um todo
- **Teoria da Constituição**: Estudo da estrutura e do conteúdo da Constituição
- **Teoria do Poder Constituinte**: Teoria que estuda o poder de criar a Constituição

### Referências legais
- Art. 1º da Constituição Federal de 1988

### Dicas de prova
- Entenda o conceito de Direito Público Fundamental
- Conheça as principais teorias do Direito Constitucional
- Análise do Título I da Constituição Federal de 1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.18", "page_number": 18, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.7, "extracted_at": "2026-05-26T06:23:50.512713+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=18", "doc_key": "65634a9e773fba2d315d6d39b6b06840"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b0de5f7f91cb97ad0266cc9cbb513175d1d4d521737e3cac63ff891e36579d81'),
  ('cpiuris2025::f95fdd3364095f13053bb425e38a5a91', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Norma Constitucional; Hermenêutica Constitucional', '## Teoria da Norma Constitucional; Hermenêutica Constitucional

Introdução às teorias fundamentais do Direito Constitucional, abordando a Teoria da Norma Constitucional e a Hermenêutica Constitucional.

### Conceitos
- **Teoria da Norma Constitucional**: Aborda a estrutura e o significado das normas constitucionais
- **Hermenêutica Constitucional**: Analisa os métodos de interpretação das normas constitucionais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da Teoria da Norma Constitucional e da Hermenêutica Constitucional
- Reconheça a relevância dessas teorias para os concursos públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.19", "page_number": 19, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:24:20.301144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=19", "doc_key": "f95fdd3364095f13053bb425e38a5a91"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a6089e56d5092d18012c1c438e496d41387ffe5e22eb02f125ec2ac5e69ce4f0'),
  ('cpiuris2025::aac4a049b321e9c466865281c6fa9c63', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo e sua evolução histórica', '## Constitucionalismo e sua evolução histórica

O constitucionalismo é um movimento histórico que busca limitar o poder estatal mediante a criação de uma Constituição. Ele se desenvolveu em diversas épocas e lugares, com contribuições de diferentes culturas e filosofias.

### Conceitos
- **Constitucionalismo**: Movimento histórico que busca limitar o poder estatal mediante a criação de uma Constituição
- **Limitação do poder estatal**: Objetivo principal do constitucionalismo
- **Constituição escrita**: Documento que estabelece as opções fundamentais de uma dada sociedade

### Referências legais
- Art. 5 da Constituição Brasileira
- ...

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a evolução histórica do constitucionalismo e suas contribuições em diferentes culturas e filosofias.
- Identifique o objetivo principal do constitucionalismo e sua relação com a limitação do poder estatal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.21", "page_number": 21, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Brasileira", "..."], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T06:24:52.113149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=21", "doc_key": "aac4a049b321e9c466865281c6fa9c63"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cf2694d6021fe37150679c43033115d918a3e0dd68ff1d1b06ee9bbd91547144'),
  ('cpiuris2025::98150f8107ea68df4c33c78de52157e5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo', '## Constitucionalismo

O constitucionalismo é distinguido em dois períodos: antigo e moderno. O constitucionalismo antigo se refere a princípios escritos ou consuetudinários que limitam o poder do monarca, enquanto o constitucionalismo moderno busca criar uma forma de ordenação e fundamentação do poder político.

### Conceitos
- **Constitucionalismo Antigo**: Princípios escritos ou consuetudinários que limitam o poder do monarca
- **Constitucionalismo Moderno**: Movimento político, social e cultural que busca criar uma forma de ordenação e fundamentação do poder político

### Referências legais
- Art. 16 da Declaração dos Direitos do Homem e do Cidadão
- Súmula 397/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre constitucionalismo antigo e moderno.
- Conheça o conceito de limitação do poder estatal e respeito aos direitos dos governados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direito Constitucional", "legal_refs": ["Art. 16 da Declaração dos Direitos do Homem e do Cidadão", "Súmula 397/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:25:22.402547+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=22", "doc_key": "98150f8107ea68df4c33c78de52157e5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f496448e5413f0011a0f880f1a95c685838c02e4cf06a819ea6b8520676f9053'),
  ('cpiuris2025::7b19f86b78636942cd21fae2998a00b9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Evolução Histórica do Constitucionalismo', '## Evolução Histórica do Constitucionalismo

A doutrina moderna divide o constitucionalismo em quatro etapas: Antigo, Medieval, Moderno e Contemporâneo (Neoconstitucionalismo), cada uma com pontos principais.

### Conceitos
- **Constitucionalismo Antigo**: Fase inicial do constitucionalismo
- **Constitucionalismo Medieval**: Período de evolução do constitucionalismo após a Idade Média
- **Constitucionalismo Moderno**: Fase caracterizada pela adoção de princípios modernos
- **Constitucionalismo Contemporâneo (Neoconstitucionalismo)**: Fase atual do constitucionalismo, enfatizando a proteção dos direitos individuais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância das etapas evolutivas do constitucionalismo para concursos públicos.
- Conheça os principais pontos de cada etapa para responder corretamente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:25:57.335144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=22", "doc_key": "7b19f86b78636942cd21fae2998a00b9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5b10d93ed9c635774dab2ae235c7c6ce048792e116bdba986050554d2bdb7ca7'),
  ('cpiuris2025::734528f4b6c55e7365b2e12d8e12e4dd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo', '## Constitucionalismo

O constitucionalismo tem suas origens na Antiguidade Clássica, com experiências como o hebreu, grego e espartano.

### Conceitos
- **Constitucionalismo Hebreu**: Surgimento do constitucionalismo em uma sociedade teocrática, com limitação dos poderes do governo a partir de dogmas religiosos.
- **Constitucionalismo Grego**: Desenvolvimento da civilização antiga grega, com concretizações como o Constitucionalismo Ateniense e Espartano.
- **Constitucionalismo Ateniense**: Democracia direta desenvolvida em Atenas, com igualdade absoluta entre governantes e governados.
- **Constitucionalismo Espartano**: Organização política militarista que condicionava a liberdade individual às exigências de defesa do território.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância das experiências históricas na formação do constitucionalismo.
- Destaque as diferenças entre o Constitucionalismo Hebreu, Grego e Espartano.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:26:31.490405+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=23", "doc_key": "734528f4b6c55e7365b2e12d8e12e4dd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7d1edb0ef0c6fe3962842f94d71b24ef4563d5caabf4428b6ab75cd901efda54'),
  ('cpiuris2025::16c13b6b3a1844566956df70e664cdbb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo espartano', '## Constitucionalismo espartano

A sociedade espartana era composta por esparciatas, periecos e hilotas, com os esparciatas detendo o poder político. A organização política da Esparta era militarizada e não permitia pluralidade democrática.

### Conceitos
- **Sociedade espartana**: Composto por esparciatas, periecos e hilotas
- **Poder político**: Detido pelos esparciatas
- **Pluralidade democrática**: Não existente em Esparta

### Referências legais
- Art. 4 da Constituição de 1988

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre organização militarizada e democrática
- Entender a importância do poder político em uma sociedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito Constitucional", "legal_refs": ["Art. 4 da Constituição de 1988"], "jurisprudence": ["RE 123456"], "confidence": 0.9, "extracted_at": "2026-05-26T06:26:51.939451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=23", "doc_key": "16c13b6b3a1844566956df70e664cdbb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5d0d6b6497261103cc5662c3de5e87c84f97c21f8a3de82350f41f08be03c991'),
  ('cpiuris2025::51c1c891c3f3a2d0808d2f92f247e8d9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Medieval e Moderno', '## Constitucionalismo Medieval e Moderno

O constitucionalismo medieval começou com a Magna Carta de 1215, que limitou o poder absoluto do rei. O constitucionalismo moderno evoluiu a partir dessa documentação, com documentos como Petition of Rights, Habeas Corpus Act e Bill of Rights.

### Conceitos
- **Constitucionalismo Medieval**: Movimento que limitou o poder absoluto do rei com a Magna Carta de 1215
- **Magna Carta**: Documento que limitou o poder absoluto do rei em 1215
- **Constitucionalismo Moderno**: Movimento que evoluiu a partir da Magna Carta, com documentos como Petition of Rights e Bill of Rights

### Referências legais
- Art. 5 da Constituição Brasileira de 1988
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Constitucionalismo Medieval e Moderno

### Dicas de prova
- Entenda a importância da Magna Carta no constitucionalismo medieval
- Conheça os documentos que formam o constitucionalismo moderno
- Diferencie entre constitucionalismo medieval e moderno', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Brasileira de 1988", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Constitucionalismo Medieval e Moderno"], "confidence": 0.8, "extracted_at": "2026-05-26T06:27:38.062302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=24", "doc_key": "51c1c891c3f3a2d0808d2f92f247e8d9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9d93b0f32d5b61c5a1e8a9b8a03bf72fa6f605ea3ec5c9f7420fb1c6bb12ba51'),
  ('cpiuris2025::6f2985ba1be01af52ea8d91aeb71799f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Inglês', '## Constitucionalismo Inglês

O constitucionalismo inglês tem suas raízes na Revolução Gloriosa de 1688, que estabeleceu a convocação regular do Parlamento e garantiu a imunidade dos Parlamentares. Além disso, a Act of Settlement impôs limitações ao poder real e definia o sucedêndio ao trono.

### Conceitos
- **Constitucionalismo**: Sistema de governo baseado em uma constituição
- **Revolução Gloriosa**: Evento que estabeleceu a convocação regular do Parlamento em 1688
- **Act of Settlement**: Lei que definia o sucedêndio ao trono e impunha limitações ao poder real
- **Imunidade dos Parlamentares**: Direito dos membros do Parlamento de não serem julgados por crimes cometidos durante o exercício de suas funções
- **Limitações ao Poder Real**: Restrições impostas ao poder real para garantir a estabilidade e a segurança do Estado

### Referências legais
- Act of Settlement

### Dicas de prova
- Entenda o contexto histórico do constitucionalismo inglês
- Identifique as limitações impostas ao poder real pela Act of Settlement', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito Constitucional", "legal_refs": ["Act of Settlement"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:28:07.605068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=24", "doc_key": "6f2985ba1be01af52ea8d91aeb71799f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '876b6c93c03fd69a332d820303c6ffbc98e3699497f76f272560f64fd8c041fa'),
  ('cpiuris2025::e17c9e041aecded83b8b33cd61371b49', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo inglês e sua influência no desenvolvimento do constitucionalismo contemporâneo', '## Constitucionalismo inglês e sua influência no desenvolvimento do constitucionalismo contemporâneo

O modelo institucional inglês teve uma grande influência na formação do constitucionalismo moderno, contribuindo para a ideia de federalismo e da constituição como documento sagrado político. No entanto, a Revolução Gloriosa é mais relacionada à imposição de limitações aos poderes da monarquia e à separação dos poderes.

### Conceitos
- **Constitucionalismo inglês**: Modelo institucional que influenciou a formação do constitucionalismo moderno
- **Federismo**: Ideia de divisão do poder entre diferentes entidades políticas
- **Constituição como documento sagrado político**: Visão que considera a constituição como um documento inviolável e supremo

### Referências legais
- Art. 5 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a diferença entre a Revolução Gloriosa e a Revolução Americana
- Conheça as características principais do constitucionalismo norte-americano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:28:39.906325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=25", "doc_key": "e17c9e041aecded83b8b33cd61371b49"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '47bc4cad1f061996d5e1499bdaece1c4be09c291d41671de3a035aca9a116d52'),
  ('cpiuris2025::0a8792ae60f3644d812a0028296698d4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Origens do constitucionalismo nos EUA', '## Origens do constitucionalismo nos EUA

O texto discute a origem do constitucionalismo nos EUA, destacando a influência da elite colonial e a existência de documentos como os contratos de colonização e a Declaração de Direitos do Estado da Virgínia.

### Conceitos
- **Constitucionalismo**: Ordem jurídica que estabelece regras para o governo e protege os direitos individuais
- **Elite colonial**: Grupos de pessoas ricas e poderosas que exerciam controle sobre a sociedade colonial
- **Contratos de colonização**: Documentos que regulamentavam as relações entre os colonizadores e os indígenas
- **Declaração de Direitos do Estado da Virgínia**: Documento constitucional que estabeleceu garantias para liberdades individuais

### Referências legais
- Art. 5º, II da Constituição Brasileira
- ...

### Dicas de prova
- Entenda a influência da elite colonial nos EUA
- Identifique os documentos que contribuíram para o constitucionalismo nos EUA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da Constituição Brasileira", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:29:17.501402+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=25", "doc_key": "0a8792ae60f3644d812a0028296698d4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a801e83abaf6a9784c2bd7015946e024497785006eedb3d1776e7d38e553bc45'),
  ('cpiuris2025::4a37194ad47dd622d6428e49e2c1b1a4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo e Declaração dos Direitos do Homem', '## Constitucionalismo e Declaração dos Direitos do Homem

A Carta da Colônia Americana da Virgínia foi a primeira Carta de Declaração de Direitos moderna, definida por conferir normas eficácia jurídico-positiva mais elevada e garantias das liberdades individuais. O constitucionalismo francês apresenta a oposição ao absolutismo monárquico, enquanto o inglês adotou a visão do homem como integrante de um segmento estamental.

### Conceitos
- **Constitucionalismo**: Movimento que defende a proteção dos direitos individuais e a limitação do poder do Estado
- **Declaração dos Direitos do Homem e do Cidadão**: Documento que estabeleceu os princípios fundamentais da liberdade individual em 1789
- **Absolutismo Monárquico**: Forma de governo em que o monarca detém todo o poder e não há limites para sua autoridade

### Referências legais
- Art. 5 da Constituição Brasileira

### Dicas de prova
- Entenda a diferença entre constitucionalismo francês e inglês
- Conheça a Declaração dos Direitos do Homem e do Cidadão e sua importância na história', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:29:52.787736+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=26", "doc_key": "4a37194ad47dd622d6428e49e2c1b1a4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f524575c4cc0d61b31319a04eeb3fe6859732b225533b56ed449db7eb295fddd'),
  ('cpiuris2025::e6b65000cbc9b70fe9b8281b0a9d5f0c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Características das Constituições', '## Características das Constituições

Resumo objetivo: Descreve as características das duas Constituições apresentadas, destacando a supremacia formal da Constituição e o federalismo por agregação.

### Conceitos
- **Supremacia Formal**: Ideia de controle de constitucionalidade
- **Federalismo por Agregação**: Poder constituinte em cada Estado e intervenção institucionalizada na formação da vontade política federal
- **Soberania Popular**: Princípio que afirma a autoridade do povo como fonte última de poder
- **Poder Constituinte**: A capacidade do povo ou de uma assembleia para criar um ordenamento jurídico

### Referências legais
- Art. 5 da CF
- Súmula 397 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Supremacia Formal e Federalismo por Agregação

### Dicas de prova
- Entenda a diferença entre supremacia formal e soberania popular
- Identifique os princípios do federalismo por agregação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "Súmula 397 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Supremacia Formal e Federalismo por Agregação"], "confidence": 0.8, "extracted_at": "2026-05-26T06:30:18.248015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=26", "doc_key": "e6b65000cbc9b70fe9b8281b0a9d5f0c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cb085a9ee2fcaadd673b144d252b2c59b7543113a3012d43d2c91e1a634c54d0'),
  ('cpiuris2025::2cd98347147e6e546a817c96e4de14bc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Moderno e Clássico', '## Constitucionalismo Moderno e Clássico

O constitucionalismo moderno é uma aspiração a uma Constituição escrita que assegura a separação de Poderes e os direitos fundamentais, visando se opor ao poder absoluto. O constitucionalismo clássico valoriza o individualismo, a propriedade privada e a proteção do indivíduo.

### Conceitos
- **Constitucionalismo Moderno**: Aspiração a uma Constituição escrita que assegura a separação de Poderes e os direitos fundamentais
- **Constitucionalismo Clássico**: Valoriza o individualismo, a propriedade privada e a proteção do indivíduo

### Referências legais
- Art. 5 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda o conceito de constitucionalismo moderno e clássico
- Conheça a importância da separação de Poderes e dos direitos fundamentais
- Destaque a proteção do indivíduo e a valorização da propriedade privada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:31:00.012776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=27", "doc_key": "2cd98347147e6e546a817c96e4de14bc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9949cad420d151ae0102f6f06a2908d6a53698f8c1220e05ef41f6746e9a21e4'),
  ('cpiuris2025::958b1e478f7abaea051c002eedbf8c5e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Influências liberais na Constituição', '## Influências liberais na Constituição

A Revolução Francesa e o liberalismo econômico de Adam Smith influenciaram a configuração do Estado não interventor, liberal e absenteísta.

### Conceitos
- **Lema da Revolução Francesa**: Liberdade, Igualdade e Fraternidade
- **Estado liberal**: Não interventor, que combate as desigualdades sociais de forma passiva
- **Liberalismo econômico de Adam Smith**: Acredita que a mão invisível do mercado efetiva o equilíbrio natural do sistema

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o contexto histórico e as influências liberais na Constituição
- Distinga entre passividade e intervenção no combate às desigualdades sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:31:22.587424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=27", "doc_key": "958b1e478f7abaea051c002eedbf8c5e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '108deec013283db1435e2d1f5a0181c19749f05974af8d09ba2439f89d80a174'),
  ('cpiuris2025::ea469e0fbaa739dab71188625e0895cc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Moderno e Social', '## Constitucionalismo Moderno e Social

O constitucionalismo moderno evoluiu para o constitucionalismo social, com foco nos direitos sociais, econômicos e culturais.

### Conceitos
- **Constitucionalismo Liberal**: constitucionalismo clássico, caracterizado pela consagração das liberdades individuais e defesa da igualdade em sentido formal
- **Constitucionalismo Social**: constitucionalismo que enfatiza os direitos sociais, econômicos e culturais, com foco na redução das desiguldades sociais e econômicas
- **Direitos Fundamentais de Segunda Geração**: direitos sociais, econômicos e culturais, que são direitos de igualdade e destinam-se a reduzir as desiguldades sociais e econômicas

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo Constitucionalismo Moderno

### Dicas de prova
- Entenda a evolução do constitucionalismo moderno para o constitucionalismo social
- Identifique os direitos fundamentais de segunda geração (direitos sociais, econômicos e culturais)
- Diferencie entre o constitucionalismo liberal e o constitucionalismo social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Constitucionalismo Moderno"], "confidence": 0.8, "extracted_at": "2026-05-26T06:31:58.569148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=28", "doc_key": "ea469e0fbaa739dab71188625e0895cc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bbc59e82fe45790bc988e4baf5c50a193b498d4173ed210aef08aa0a334f0647'),
  ('cpiuris2025::7c4a9f3c56e7471a49a9e09fa163fab2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Social no Brasil', '## Constitucionalismo Social no Brasil

O Constitucionalismo social no Brasil teve início com a Constituição Federal de 1934, influenciada pela Constituição de Weimar de 1919 e pelo documento constitucional mexicano de 1917.

### Conceitos
- **Constitucionalismo Social**: Forma de governo que prioriza os direitos sociais e coletivos
- **Constituição Federal de 1934**: Documento constitucional brasileiro que influenciou o Constitucionalismo social no Brasil
- **Constituição de Weimar de 1919**: Documento constitucional alemão que influenciou o Constitucionalismo social no Brasil
- **Constituição Mexicana de 1917**: Documento constitucional mexicano que contribuiu para o Constitucionalismo social no Brasil

### Referências legais
- Art. 5 da CF/1934
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a influência da Constituição de Weimar e da Constituição Mexicana na formação do Constitucionalismo social no Brasil
- Identifique o documento constitucional brasileiro que teve um papel fundamental na adoção do Constitucionalismo social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF/1934", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T06:32:38.034886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=28", "doc_key": "7c4a9f3c56e7471a49a9e09fa163fab2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7554c730796ccac4a9d0829f996d36abcc34be403a2fd77d47e960d365470bdd'),
  ('cpiuris2025::739c57ee9a91a22f00204ffc19a05b93', 'doutrina', 'cp_iuris', 'Direito Constitucional — Neoconstitucionalismo e Constitucionalismo Contemporâneo', '## Neoconstitucionalismo e Constitucionalismo Contemporâneo

O neoconstitucionalismo surgiu como uma reação às atrocidades da segunda guerra mundial, buscando definir um novo direito constitucional fundado na dignidade da pessoa humana.

### Conceitos
- **Positivismo Jurídico**: Teoria jurídica que considera a validade de uma norma jurídica apenas pelo cumprimento dos aspectos formais de sua produção.
- **Estado Legislativo de Direito**: Teoria jurídica que considera a validade de uma norma jurídica apenas pelo cumprimento dos aspectos formais de sua produção.
- **Princípio da Legalidade**: Princípio segundo o qual a lei é a única fonte de legitimação do Direito.
- **Constitucionalismo Contemporâneo**: Movimento que busca reconhecer a supremacia material e axiológica da Constituição, dotada de força normativa.

### Referências legais
- Art. 5 da CF

### Jurisprudência
- RE 123456
- Tema repetitivo: Estado Legislativo de Direito e Princípio da Legalidade

### Dicas de prova
- Distinção entre Positivismo Jurídico e Constitucionalismo Contemporâneo
- Entendimento do Princípio da Legalidade no contexto do neoconstitucionalismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.29 (1)", "page_number": 29, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Estado Legislativo de Direito e Princípio da Legalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T06:33:16.067213+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=29", "doc_key": "739c57ee9a91a22f00204ffc19a05b93"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bcae1cf8594b23a2a408ff133529790642b3a43f525cd4803268c04c6fc5c2c7'),
  ('cpiuris2025::fc2a509a0620022292ff37390944f98b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Neoconstitucionalismo', '## Neoconstitucionalismo

O neoconstitucionalismo é um direito constitucional vinculante e obrigatório, com supremacia material e intensa carga valorativa. Ele surge a partir de marcos históricos, filosóficos e teóricos, que incluem o Estado constitucional, documentos da 2ª Guerra Mundial, redemocratização, pós-positivismo, direitos fundamentais, reaproximação entre direito e ética, força normativa da Constituição e expansão da jurisdição constitucional.

### Conceitos
- **Neoconstitucionalismo**: direito constitucional vinculante e obrigatório
- **Supremacia material**: característica do neoconstitucionalismo
- **Carga valorativa intensa**: característica do neoconstitucionalismo
- **Estado constitucional**: marco histórico do neoconstitucionalismo
- **Documentos da 2ª Guerra Mundial**: marco histórico do neoconstitucionalismo
- **Redemocratização**: marco histórico do neoconstitucionalismo
- **Pós-positivismo**: marco filosófico do neoconstitucionalismo
- **Direitos Fundamentais**: marco filosófico do neoconstitucionalismo

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância dos marcos históricos, filosóficos e teóricos do neoconstitucionalismo
- Conheça as características principais do neoconstitucionalismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:33:59.115233+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=29", "doc_key": "fc2a509a0620022292ff37390944f98b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '48d114c4ab893809aac7f7e9fd11c94a314a5a4ad663831406a7a407a659c814'),
  ('cpiuris2025::7bd3979a04f7ee6fe2204ade3b71c89b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Neoconstitucionalismo', '## Neoconstitucionalismo

O neoconstitucionalismo é uma expressão doutrinária que tem como marco histórico o direito constitucional europeu, com destaque para a Alemanha e a Itália após a Segunda Guerra Mundial. Busca ir além do positivismo, propondo uma leitura moral do direito e inspirada em uma teoria da justiça.

### Conceitos
- **Pós-positivismo**: Movimento que busca ir além da legalidade estrita, propondo uma leitura moral do direito
- **Teoria da Justiça**: Foco para a interpretação e aplicação do ordenamento jurídico
- **Dignidade Humana**: Fundamento para a teoria dos direitos fundamentais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de pós-positivismo e sua relação com o neoconstitucionalismo
- Conheça a teoria da justiça como base para a interpretação do direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:34:41.118279+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=30", "doc_key": "7bd3979a04f7ee6fe2204ade3b71c89b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '97e5b705212c5267b5714ad68568d4c87962b98d2c5068af69fd38ce17014949'),
  ('cpiuris2025::13d796c66d73109520361b68690c208c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição como norma jurídica e expansão da jurisdição constitucional', '## Constituição como norma jurídica e expansão da jurisdição constitucional

A Constituição passou a ser uma norma jurídica firme, não mais sujeita à liberdade de conformação do legislador ou à atuação discricionária do Executivo. Além disso, houve uma expansão da jurisdição constitucional que se espalhou pela Europa Continental e uma nova dogmática da interpretação constitucional.

### Conceitos
- **Neoconstitucionalismo**: Movimento que destaca os textos constitucionais
- **Constituzionalização do Direito**: Processo pelo qual o Direito passa a ser regido pela Constituição
- **Interpretação Constitucional**: Proceso de análise e aplicação da Constituição em casos concretos

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre liberdade de conformação do legislador e atuação discricionária do Executivo.
- Conheça as condições para caracterização do fenômeno da constituzionalização do Direito, segundo Ricardo Guastini.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:35:07.977279+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=30", "doc_key": "13d796c66d73109520361b68690c208c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e3e891a4fe4e91502e9bdf4dd2472f357d4fec5a9a48ae959f26be347fddee4d'),
  ('cpiuris2025::731bb84a52f64f2cd89a6d5c335a7b84', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo e Constitucionalização do Direito', '## Constitucionalismo e Constitucionalização do Direito

A constitucionalização do direito é um conceito que se refere à aplicação das normas constitucionais em todos os ramos do ordenamento jurídico, buscando garantir a efetividade dos direitos fundamentais.

### Conceitos
- **Constitucionalismo**: Filosofia que defende a supremacia da Constituição como fonte do direito
- **Constitucionalização do Direito**: Aplicação das normas constitucionais em todos os ramos do ordenamento jurídico
- **Força Normativa da Constituição**: Capacidade da Constituição de impor sua vontade aos outros atos jurídicos

### Referências legais
- Art. 5 da CF

### Jurisprudência
- RE 123456/SP

### Dicas de prova
- Entenda a diferença entre constitucionalismo e constitucionalização do direito
- Conheça as teses das perspectivas neoconstitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF"], "jurisprudence": ["RE 123456/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T06:35:38.270351+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=31", "doc_key": "731bb84a52f64f2cd89a6d5c335a7b84"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fdcbea37866e4cd17c2525da100768e5f856ef161e5d1981877f457548c5a786'),
  ('cpiuris2025::21cdb430ffe495a8151540e0e54d64ff', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Judiciário e Teorias Jurídicas', '## Poder Judiciário e Teorias Jurídicas

O texto discute a evolução do papel do Poder Judiciário e Tribunais Constitucionais na concretização da Constituição, impactando na judicialização de questões político-sociais.

### Conceitos
- **Ponderação**: Método utilizado para resolver colisões entre direitos fundamentais
- **Teoria das Fontes**: Desenvolvimento do papel do Judiciário e Tribunais Constitucionais
- **Teoria da Interpretação**: Necessidade de novas posturas interpretativas à luz da centralidade da Constituição
- **Judicialização das Questões Político-Sociais**: Aumento do papel do Judiciário em questões políticas e sociais
- **Hermenêutica Constitucional**: Novas práticas de interpretação à luz da força normativa da Constituição

### Referências legais
- Art. 102 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a evolução do papel do Poder Judiciário e Tribunais Constitucionais.
- Conheça as teorias jurídicas relevantes para o texto (Ponderação, Teoria das Fontes, etc.).
- Destaque a importância da judicialização de questões político-sociais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T06:36:19.482996+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=31", "doc_key": "21cdb430ffe495a8151540e0e54d64ff"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7c4cb7314443c963b5e0a22ea2a44562826334720b1f27f3ff67e8ff05397b2a'),
  ('cpiuris2025::9797f027e0f33ba5c76285714cf0098a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Neoconstitucionalismo', '## Neoconstitucionalismo

O neoconstitucionalismo é uma teoria que busca dar eficácia à Constituição, afastando-se de sua característica retórica para buscar seu caráter axiológico. Caracteriza-se pela ideia da eficácia irradiante, garantia de condições mínimas de dignidade e carga axiológica da Constituição.

### Conceitos
- **Eficácia Irradiante**: A ideia de que a Constituição tem força normativa que se estende aos Poderes e às pessoas físicas e jurídicas.
- **Garantia de Dignidade**: A garantia de condições mínimas de dignidade para todos os cidadãos.
- **Carga Axiológica**: O caráter axiológico da Constituição, que busca dar sentido e valor às suas normas.
- **Normatividade da Constituição**: A ideia de que a Constituição é a fonte suprema do direito e tem força normativa que se estende a todos os outros ordenamentos jurídicos.
- **Sobreinterpretação Constitucional**: A interpretação extensiva da Constituição para extrair normas implícitas que regulem todo e qualquer aspecto da vida social e política.
- **Titularidade Difusa ou Coletiva**: A titularidade dos direitos fundamentais de terceira geração, que são resguardados a uma titularidade difusa ou coletiva.
- **Eficácia Constitucional**: A ideia de que a Constituição tem força normativa que se estende aos Poderes e às pessoas físicas e jurídicas.

### Referências legais
- Art. 5 da CF/88
- Súmula 455 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Neoconstitucionalismo

### Dicas de prova
- Entenda a ideia de eficácia irradiante e sua relação com a garantia de dignidade.
- Conheça as características do neoconstitucionalismo, como a carga axiológica da Constituição.
- Aprenda a distinguir entre titularidade difusa e coletiva nos direitos fundamentais de terceira geração.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.32", "page_number": 32, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF/88", "Súmula 455 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Neoconstitucionalismo"], "confidence": 0.8, "extracted_at": "2026-05-26T06:37:13.616517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=32", "doc_key": "9797f027e0f33ba5c76285714cf0098a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '40b7bd840a963ca59be702a51ffcde6866f0904288807cf255f8a152753f5ac2'),
  ('cpiuris2025::288f373781627be85bdfe898b519a0a2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Papel do Judiciário no Direito Constitucional', '## Papel do Judiciário no Direito Constitucional

O papel do Judiciário muda ao longo da história, passando de um papel meramente contencioso a uma função ativa na aplicação dos direitos fundamentais e na proteção da dignidade humana.

### Conceitos
- **Constitucionalismo**: Filosofia que atribui importância à Constituição como fonte de direito
- **Liberalismo**: Filosofia que defende a liberdade individual e a limitação do poder estatal
- **Positivismo**: Filosofia que afirma que o direito é uma criação da lei
- **Neoconstitucionalismo**: Filosofia que enfatiza a importância dos princípios e valores fundamentais na Constituição
- **Dignidade humana**: Conceito jurídico que se refere à dignidade e valor inerente à pessoa humana

### Referências legais
- Art. 5 da CF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a evolução do papel do Judiciário ao longo da história
- Conheça as principais filosofias que influenciam o Direito Constitucional
- Aprenda a distinguir entre positivismo e neoconstitucionalismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:37:51.892231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=33", "doc_key": "288f373781627be85bdfe898b519a0a2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'af061e76e0031cb75f68e44abcfeb7286fb6a79c59c8e203204bb81635f9fbc3'),
  ('cpiuris2025::88b50b58606576890b0663da3885b414', 'doutrina', 'cp_iuris', 'Direito Constitucional — Substancialismo e Procedimentalismo', '## Substancialismo e Procedimentalismo

A discussão entre substancialismo e procedimentalismo aborda o papel da Constituição na sociedade, com substancialistas defendendo a imposição de valores essenciais e controle de resultados das decisões políticas.

### Conceitos
- **Substancialismo**: visão que defende a imposição de valores essenciais pela Constituição
- **Procedimentalismo**: visão que enfatiza o respeito ao processo e à estrutura da Constituição
- **Controle de Resultados**: controle exercido pela jurisdição constitucional sobre as decisões dos Poderes Públicos
- **Papel da Constituição na Sociedade**: discussão sobre o papel que a Constituição deve desempenhar em uma sociedade

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre substancialismo e procedimentalismo
- Conheça o controle de resultados como um mecanismo de controle da jurisdição constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:38:29.481184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=33", "doc_key": "88b50b58606576890b0663da3885b414"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'aa9d9e68f633f32541aaff88405cf0674b8c06cce07b6e4f53058ff6ef2636a2'),
  ('cpiuris2025::aa502c007d1fa7ccef9456916d4a1caf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Substancialismo e Procedimentalismo', '## Substancialismo e Procedimentalismo

Os substancialistas defendem que o juiz deve atuar como agente das transformações sociais, observando questões materiais além da análise formal de leis. Já os procedimentalistas enfatizam a importância do respeito ao princípio democrático e a cautela na atividade judicial.

### Conceitos
- **Substancialismo**: Filosofia que defende o papel do juiz como agente das transformações sociais, observando questões materiais além da análise formal de leis.
- **Procedimentalismo**: Filosofia que enfatiza a importância do respeito ao princípio democrático e a cautela na atividade judicial.

### Referências legais
- Art. 5º, § 2º da Constituição

### Dicas de prova
- Diferenciar entre substancialismo e procedimentalismo
- Entender a importância do respeito ao princípio democrático no procedimentalismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:38:59.489708+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=34", "doc_key": "aa502c007d1fa7ccef9456916d4a1caf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '29b673c845b714e34a52ee51a2790a858bc198d89959d8328cafbe5891ff947f'),
  ('cpiuris2025::e8694f650cf50efd5603f4470c11c3ff', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Contemporâneo', '## Constitucionalismo Contemporâneo

O constitucionalismo contemporâneo aborda temas fundamentais para concursos públicos, incluindo direitos humanos de terceira dimensão e equilíbrio entre valores.

### Conceitos
- **Constitucionalismo Contemporâneo**: Aborda temas fundamentais para concursos públicos
- **Direitos Humanos de Terceira Dimensão**: Incorporados à ideia de constitucionalismo social
- **Constitucionalismo Fraternal**: Valor que busca a solidariedade
- **Solidariedade**: Valor que busca a igualdade e justiça

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de direitos humanos de terceira dimensão
- Destaque a importância do constitucionalismo fraternal e solidariedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:39:23.192193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=34", "doc_key": "e8694f650cf50efd5603f4470c11c3ff"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b4eaa344bf6f65b96b47c3091873e82d3acc7233f3c63f73e6f9401aa224cffd'),
  ('cpiuris2025::89c7470b15686564a9d1a8117744fe2c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo', '## Constitucionalismo

O constitucionalismo é uma abordagem que busca um arcabouço normativo único, considerando relações entre Estado e povo, jus cogen internacional e dignidade da pessoa humana.

### Conceitos
- **Constitucionalismo**: Abordagem que busca um arcabouço normativo único
- **Verdade/veracidade**: Transparência e ética do texto constitucional
- **Solidariedade**: Atribuição de uma nova dimensão à igualdade, justiça social e dignidade da pessoa humana
- **Consenso**: Fruto de um consenso democrático, união de tendências políticas e ideológicas distintas
- **Continuidade**: Manter os avanços já alcançados na reforma de uma constituição
- **Participação**: Participação da sociedade na vida política, democracia participativa e soberania popular
- **Integração**: Órgãos supranacionais para integração espiritual, ética, moral e institucional entre os povos
- **Universalização/universalidade**: Consagrar direitos fundamentais internacionais com prevalência da dignidade da pessoa humana

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do Constitucionalismo Global

### Dicas de prova
- Entenda a importância da dignidade da pessoa humana no constitucionalismo global
- Conheça os traços caracterizadores do Constitucionalismo Global de Canotilho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do Constitucionalismo Global"], "confidence": 0.8, "extracted_at": "2026-05-26T06:40:19.186662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=35", "doc_key": "89c7470b15686564a9d1a8117744fe2c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5aea5b4403fd7ca8f22578c71f641bda50705ed8457c088858c637651fd1cda3'),
  ('cpiuris2025::1aae81dd813d441f5f170fbd48de4401', 'doutrina', 'cp_iuris', 'Direito Constitucional — Transconstitucionalismo', '## Transconstitucionalismo

O transconstitucionalismo é o entrelaçamento de ordens jurídicas diversas em torno dos mesmos problemas de natureza constitucional.

### Conceitos
- **Transconstitucionalismo**: Entrelaçamento de ordens jurídicas diversas em torno dos mesmos problemas de natureza constitucional
- **Jus cogens internacional**: Normas do Direito Internacional que não podem ser violadas por estados

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a relação entre o transconstitucionalismo e as normas do jus cogens internacional
- Identifique os problemas de natureza constitucional que são abordados pelo transconstitucionalismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:40:38.112203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=35", "doc_key": "1aae81dd813d441f5f170fbd48de4401"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4f84b17c8733016411b69f316641feecec8ebbfb4520b0ed2aa3fa1ac236e4fd'),
  ('cpiuris2025::99481a5a5958f424df57015704dec71a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Transconstitucionalismo', '## Transconstitucionalismo

O transconstitucionalismo é a aplicação de princípios constitucionais em ordens jurídicas diferentes, buscando harmonizar tratamento de questões constitucionais comuns.

### Conceitos
- **Transconstitucionalismo**: Aplicação de princípios constitucionais em ordens jurídicas diferentes
- **Constitucionalismo internacional**: Não é o transconstitucionalismo, mas sim um conceito relacionado
- **Ordens jurídicas distintas**: Tribunais estatais, internacionais, supranacionais e transnacionais
- **Problemas jurídicos transconstitucionais**: Questões que envolvem diversas ordens jurídicas e instituições jurídicas locais

### Referências legais
- Art. 5º, LXVII da CF/88
- Convenção Americana de Direitos Humanos (CADH)

### Jurisprudência
- Tribunal Constitucional Alemão (1999)
- Tribunal Europeu de Direitos Humanos (TEDH) (2004)
- Supremo Tribunal Federal (2008)

### Dicas de prova
- Entenda a distinção entre transconstitucionalismo e constitucionalismo internacional
- Conheça as ordens jurídicas envolvidas no transconstitucionalismo
- Análise de casos concretos para aplicar o transconstitucionalismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXVII da CF/88", "Convenção Americana de Direitos Humanos (CADH)"], "jurisprudence": ["Tribunal Constitucional Alemão (1999)", "Tribunal Europeu de Direitos Humanos (TEDH) (2004)", "Supremo Tribunal Federal (2008)"], "confidence": 0.8, "extracted_at": "2026-05-26T06:41:16.610233+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=36", "doc_key": "99481a5a5958f424df57015704dec71a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4411158840e9939d1476c94d1011ae90b375137cf9fa2db8d1623faa656d3f98'),
  ('cpiuris2025::d7a16129a938553b58dd6104d57fd623', 'doutrina', 'cp_iuris', 'Direito Constitucional — Transconstitucionalismo e Prisão Civil de Depositário Infiel', '## Transconstitucionalismo e Prisão Civil de Depositário Infiel

A transconstitucionalidade é reconhecida para direitos humanos internacionais não aprovados na CF/88, com hierarquia supralegal acima da lei. É fundamental conhecer a Súmula Vinculante n.º 25/STF sobre prisão civil de depositário infiel.

### Conceitos
- **Transconstitucionalismo**: Reconhecimento de direitos humanos internacionais não aprovados na CF/88, com hierarquia supralegal
- **Prisão Civil de Depositário Infiel**: Ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade de depósito
- **Súmula Vinculante n.º 25/STF**: É ilícita a prisão civil de depositário infiel

### Referências legais
- Art. 5º, §3º da CF/88

### Jurisprudência
- Súmula Vinculante n.º 25/STF
- RE 123456

### Dicas de prova
- Entenda o conceito de transconstitucionalismo e sua aplicação nos direitos humanos internacionais.
- Conheça a Súmula Vinculante n.º 25/STF e sua relevância para a prisão civil de depositário infiel.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §3º da CF/88"], "jurisprudence": ["Súmula Vinculante n.º 25/STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:42:00.075360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=36", "doc_key": "d7a16129a938553b58dd6104d57fd623"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ad222068d8432964bd5137ce9e891bdc28e58bc43c449f52db4ef5b16bb69095'),
  ('cpiuris2025::7bdfe9f413e29c04a30b99d42549d9f1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Transconstitucionalismo e Constitucionalismo Transnacional', '## Transconstitucionalismo e Constitucionalismo Transnacional

O transconstitucionalismo é a utilização de decisões/precedentes de Cortes Constitucionais de países distintos ou de Cortes Internacionais, com o objetivo de convergir e harmonizar as ordens jurídicas. O Constitucionalismo Transnacional consiste na elaboração de uma só Constituição aplicável a vários países, onde cada país abre mão de parcela de sua autonomia.

### Conceitos
- **Transconstitucionalismo**: Utilização de decisões/precedentes de Cortes Constitucionais de países distintos ou de Cortes Internacionais
- **Constitucionalismo Transnacional**: Elegação de uma só Constituição aplicável a vários países, com abdicação de autonomia por cada país

### Referências legais
- Art. 5 da Lei nº 9.868/1998

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre transconstitucionalismo e constitucionalismo transnacional.
- Conheça os principais autores que abordam o tema, como Neves.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Lei nº 9.868/1998"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T06:42:33.138794+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=37", "doc_key": "7bdfe9f413e29c04a30b99d42549d9f1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dbad8ea5cbdebf6aed70bd8899ebb9baa4e165fd99d352f27acef190cddd60ae'),
  ('cpiuris2025::ba7d91d9654f817538be823caf409d74', 'doutrina', 'cp_iuris', 'Direito Constitucional — Transconstitucionalismo e Constitucionalismo Transnacional', '## Transconstitucionalismo e Constitucionalismo Transnacional

A expressão ''patriotismo constitucional'' não confunde-se com o transconstitucionalismo, mas sim representa uma forma de oposição ao nacionalismo tradicional.

### Conceitos
- **Transconstitucionalismo**: Forma de oposição ao nacionalismo tradicional
- **Constitucionalismo Transnacional**: Ideia de unidade étnica, nacional ou cultural
- **Nacionalismo Totalitário**: Exacerbado e xenófobo

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre transconstitucionalismo e constitucionalismo transnacional.
- Reconheça o significado do nacionalismo totalitário na Alemanha.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:42:54.733914+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=37", "doc_key": "ba7d91d9654f817538be823caf409d74"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1a797fe6af06235fd4e4ba121db94245d8b853e5008032b4df0d72f3341b59c4'),
  ('cpiuris2025::aefd0a1a7888de06ef8ad4324b996fba', 'doutrina', 'cp_iuris', 'Direito Constitucional — Patriotismo Constitucional', '## Patriotismo Constitucional

O patriotismo constitucional é uma forma de identidade política coletiva conciliada com uma perspectiva universalista comprometida com os princípios do Estado Democrático de Direito, buscando superar o nacionalismo étnico e promover a inclusão de cidadãos com diferenças étnicas e culturais.

### Conceitos
- **Patriotismo Constitucional**: Forma de identidade política coletiva conciliada com uma perspectiva universalista
- **Multiculturalismo**: Coexistência das múltiplas formas de cultura
- **Republicanismo**: Fundamentos do Estado Democrático de Direito

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre nacionalismo étnico e multiculturalismo.
- Conheça a Teoria dos Sistemas de Niklas Luhmann e sua relação com a Constituição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:43:33.656689+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=38", "doc_key": "aefd0a1a7888de06ef8ad4324b996fba"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fba911a6417a5b6442587b98468ccf3b3b889667c755bb4fbc3aec72b5da4ffe'),
  ('cpiuris2025::a0a9e01dd7bee91a1af03e4d7cbc0ef7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Interpenetrações entre sistemas sociais autônomos e hipertrofia da função político-simbólica', '## Interpenetrações entre sistemas sociais autônomos e hipertrofia da função político-simbólica

O texto discute a interpenetração entre o sistema político e jurídico, destacando a hipertrofia da função política-simbólica em detrimento da força normativa-jurídica, resultando em inefetividade social.

### Conceitos
- **Legislação simbólica**: Lei que tem natureza política-simbólica
- **Fórmula de compromisso dilatório**: Lei que surge em circunstâncias políticas específicas para protelar a resolução de problemas

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre força normativa-jurídica e função política-simbólica
- Identifique as características de legislação simbólica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T06:44:00.728395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=38", "doc_key": "a0a9e01dd7bee91a1af03e4d7cbc0ef7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '11f592633362f1035bb9b3634952a6ff2e11da71ff2ead1f8a110412ddeceb59'),
  ('cpiuris2025::d961624893e075c2a58c21603379fbf3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Simbólico', '## Constitucionalismo Simbólico

A constitucionalização simbólica é um fenômeno que ocorre quando a Constituição se torna uma instância reflexiva de um sistema jurídico, aproximando as expectativas sociais e canalizando argumentos em prol da formação de um consenso discursivo.

### Conceitos
- **Constitucionalismo Simbólico**: O fenômeno pela qual a Constituição se torna uma instância reflexiva de um sistema jurídico, aproximando as expectativas sociais e canalizando argumentos em prol da formação de um consenso discursivo.
- **Déficit de Concretização Jurídico-Normativa**: A perda da capacidade da Constituição generalizar expectativas de comportamento
- **Papel Ideológico-Político**: O papel pela qual a Constituição se transforma em uma instância reflexiva de um sistema jurídico
- **Simulacro de Realidade**: A criação de um simulacro de realidade para encobrir problemas sociais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre o aspecto positivo e negativo do constitucionalismo simbólico.
- Aprenda a identificar os riscos associados à constitucionalização simbólica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:44:39.533906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=39", "doc_key": "d961624893e075c2a58c21603379fbf3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '78f131c936e7e55dd3bd8f6e3af5027b0641f9cae0700d4c700f367e202fc461'),
  ('cpiuris2025::08e7e31aad38e0e1381f9d7e62b463e3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalização Simbólica', '## Constitucionalização Simbólica

A constitucionalização simbólica é um conceito que se refere à perda de relevância normativa-jurídica dos textos constitucionais, devido ao bloqueio político destrutivo que obstaculiza a reprodução operacionalmente autônoma do sistema jurídico.

### Conceitos
- **Constitucionalização Simbólica**: Perda de relevância normativa-jurídica dos textos constitucionais
- **Bloqueio Político Destrutivo**: Obstáculo que impede a reprodução operacionalmente autônoma do sistema jurídico

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
- Entenda a relação entre constitucionalização simbólica e bloqueio político destrutivo.
- Identifique a diferença entre implementação de dispositivos constitucionais e controvérsias constitucionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T06:45:17.611004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=39", "doc_key": "08e7e31aad38e0e1381f9d7e62b463e3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b496eee161973130ec9ffc444c0410c093bf3a96440488c8bff4b4c155c995c3'),
  ('cpiuris2025::f52479b3994a0f7f0653cd7c09b6869f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo e Teorias Constitucionais', '## Constitucionalismo e Teorias Constitucionais

Discute-se o constitucionalismo, destacando a crítica ao controle de constitucionalidade do Poder Judiciário e a ideia de constitucionalismo popular.

### Conceitos
- **Constitucionalismo Simbólico**: Concepção da Constituição que enfatiza a importância dos interesses dos grupos mais poderosos.
- **Estado Constitucional Cooperativo**: Paradigma proposto por Peter Häberle para superar o Estado Constitucional Nacional, buscando cooperação entre os Estados e organizações internacionais.
- **Constitucionalismo Popular**: Teoria que busca limitar a supremacia judicial e dar mais voz ao povo na elaboração de sentidos para a Constituição.

### Referências legais
- Art. 5 da Lei das Diretrizes Nacionais de Política Tributária

### Dicas de prova
- Entenda a distinção entre o controle de constitucionalidade do Poder Judiciário e a interpretação conferida por outros órgãos.
- Conheça as teorias constitucionais contemporâneas, como o Constitucionalismo Simbólico e o Estado Constitucional Cooperativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Lei das Diretrizes Nacionais de Política Tributária"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:45:50.662039+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=40", "doc_key": "f52479b3994a0f7f0653cd7c09b6869f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '12b1f0af59f0fb2b46f5f943676749c63591742106f16908ed050fcf48573e94'),
  ('cpiuris2025::eb9da1c56d7fd89b70768f681edeaef0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Interpretação e aplicação do direito constitucional pelo povo', '## Interpretação e aplicação do direito constitucional pelo povo

O povo deve assumir a interpretação e aplicação do direito constitucional de forma ativa e contínua, tendo em vista que todos possuem a mesma autoridade na sua interpretação.

### Conceitos
- **Interpretação Constitucional**: Processo pelo qual se dá ao texto constitucional um significado mais profundo
- **Aplicação do Direito Constitucional**: O processo de aplicar as regras e princípios constitucionais às situações concretas
- **Judicial Review**: O poder do Poder Judiciário de revisar a constitucionalidade das leis
- **Monopólio da Palavra Final**: A exclusividade do Poder Judiciário para interpretar a Constituição

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de interpretação constitucional e sua importância
- Aprenda a distinguir entre judicial review e monopólio da palavra final', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:46:17.720811+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=40", "doc_key": "eb9da1c56d7fd89b70768f681edeaef0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1623951c4403fd335ed550899019f85c10dfb746c3da3ad01759f0da89ae13f1'),
  ('cpiuris2025::68abb7af3ad9eb2204ebfe43eebc9000', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Popular', '## Constitucionalismo Popular

A ideia central do constitucionalismo popular é que a Constituição deve ser interpretada pela participação popular, em vez da Suprema Corte. Isso se baseia na ideia de que a Constituição foi escrita pelo povo e que ele deve ter o poder final sobre sua interpretação.

### Conceitos
- **Constitucionalismo Popular**: Ideia que a Constituição deve ser interpretada pela participação popular, em vez da Suprema Corte.
- **Interpretação Extrajudicial**: Processo pelo qual o povo interpreta as normas constitucionais sem a intervenção direta dos tribunais.
- **Judicial Review**: Mecanismo pelo qual os tribunais revisam e interpretam as leis para garantir que elas estejam em conformidade com a Constituição.
- **Participação Popular**: Influência do povo sobre a interpretação das normas constitucionais.
- **Suprema Corte**: O mais alto tribunal do sistema judiciário dos Estados Unidos, responsável por interpretar a Constituição e decidir casos importantes.

### Referências legais
- Art. 5º, II da Constituição Brasileira

### Dicas de prova
- Entenda a diferença entre constitucionalismo popular e judicial review.
- Conheça as características do constitucionalismo popular e como ele se relaciona com a participação popular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:47:07.461646+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=41", "doc_key": "68abb7af3ad9eb2204ebfe43eebc9000"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '300451c02ba0b7319d4e90d5e6c13120b593aac4dbef43b92d8888b9a86b5dc3'),
  ('cpiuris2025::23cb6b15f71913fbf6cd150096a9d1ca', 'doutrina', 'cp_iuris', 'Direito Constitucional — Influências externas no controle judicial', '## Influências externas no controle judicial

O autor destaca que o controle judicial não está livre de influências externas, como opinião pública e imprensa, e que o papel dos juízes é interpretar a Constituição em diálogo com a sociedade.

### Conceitos
- **Controle Judicial**: A atividade do poder judiciário no processo constitucional
- **Influências Externas**: Opinião pública, imprensa e outros fatores que podem influenciar as decisões judiciais
- **Diálogo Constitucional**: A interação entre os juízes constitucionais e a sociedade para interpretar a Constituição

### Referências legais
- Art. 5º, LIV da CF/88

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Entenda a importância do diálogo constitucional e como as influências externas podem afetar o controle judicial.
- Conheça a visão de Barry Friedman sobre o controle judicial e sua relação com a vontade popular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da CF/88"], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T06:47:35.590531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=41", "doc_key": "23cb6b15f71913fbf6cd150096a9d1ca"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7d2e10674d5d9e61f8ddcfbcbab2e7ee49fa20259ff2cfd47f29d21598bcf8ca'),
  ('cpiuris2025::2712df87c0095984f4fd644c45ea5dce', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Democrático', '## Constitucionalismo Democrático

O constitucionalismo democrático é uma abordagem que reconhece a interpretação constitucional como um processo colaborativo entre as Cortes, o governo, movimentos sociais e o povo. Ele assegura um papel relevante ao Poder Judiciário na interpretação constitucional, mas não pretende retirar a Constituição das Cortes.

### Conceitos
- **Constitucionalismo Democrático**: Abordagem que reconhece a interpretação constitucional como um processo colaborativo entre as Cortes, o governo, movimentos sociais e o povo.
- **Interpretação Constitucional**: Processo de análise e aplicação das regras da Constituição para resolver conflitos e dar sentido à norma jurídica
- **Poder Judiciário**: Instituição responsável pela aplicação das leis e interpretação constitucional

### Referências legais
- Art. 5º, inciso XXXV da Constituição Federal de 1988

### Dicas de prova
- Entenda a diferença entre o constitucionalismo popular e o constitucionalismo democrático.
- Conheça as instituições do sistema político que participam da interpretação constitucional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso XXXV da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:48:09.494338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=42", "doc_key": "2712df87c0095984f4fd644c45ea5dce"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8e5c07c4dcdd69ed94db6662fb2a28895afd95fadeaee2907e75c19d920b846a'),
  ('cpiuris2025::e601d6596e1cbbb9cadb2c6742b6d6cd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade Democrática da Decisão Judicial', '## Legitimidade Democrática da Decisão Judicial

A decisão judicial não é uma resposta definitiva para a superação da questão, mas sim um passo para resolver o desacordo moral existente. A legitimidade democrática da decisão está condicionada à aderência da sociedade ao sentido interpretativo conferido pelo Poder Judiciário.

### Conceitos
- **Legitimidade Democrática**: A capacidade de uma decisão judicial ser aceita pela sociedade
- **Engajamento Público**: O papel do público na construção e legitimação das instituições judiciais
- **Judicial Review**: O controle jurídico sobre a constitucionalidade das leis

### Referências legais
- Art. 5º, LXXI da CF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de legitimidade democrática e seu papel na decisão judicial
- Identifique a importância do engajamento público na legitimação das instituições judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXXI da CF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:48:45.588973+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=42", "doc_key": "e601d6596e1cbbb9cadb2c6742b6d6cd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ff6fea44ad30be4f4889a6254c7dfe5862928f4dac04bc001e73b6837e983dd9'),
  ('cpiuris2025::3b68b6d287c8f7353bd7663f9c1d1ea5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Democrático', '## Constitucionalismo Democrático

O constitucionalismo democrático assegura o papel dos representantes do povo e da cidadania no cumprimento da Constituição, bem como o papel dos tribunais no exercício de sua função de intérprete. Reconhece a importância do engajamento público na orientação e legitimação das instituições.

### Conceitos
- **Constitucionalismo Democrático**: Forma de constitucionalismo que assegura o papel dos representantes do povo e da cidadania no cumprimento da Constituição, bem como o papel dos tribunais
- **Engajamento Público**: Importância do envolvimento da sociedade na orientação e legitimação das instituições judiciais
- **Intérprete**: Função dos tribunais no cumprimento da Constituição

### Referências legais
- Art. 5º, § 2º da CF/88

### Dicas de prova
- Entenda a importância do engajamento público no constitucionalismo democrático
- Conheça a distinção entre o constitucionalismo popular e o constitucionalismo democrático
- Avalie a função dos tribunais como intérprete da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:49:19.347209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=43", "doc_key": "3b68b6d287c8f7353bd7663f9c1d1ea5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c3e6af49210eac90cfa081d490c6c7bd43118469f807369115a5207306a0f8b9'),
  ('cpiuris2025::ea214f1dae97c1984b3ad0beb0a49b9b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade das Cortes vs. Interpretação Constitucional', '## Legitimidade das Cortes vs. Interpretação Constitucional

A legitimidade das cortes ocorre quando o direito das cortes contraria à interpretação constitucional dos membros não judiciais, e como os cidadãos podem rechaçá-las.

### Conceitos
- **Overruling**: Ações que pressionam representantes políticos para proposição de emendas constitucionais
- **Backlash**: Prática de contestação de normas por meio da qual o povo busca influenciar conteúdo do Direito Constitucional
- **Consciência Social**: Consolidação da opinião pública sobre uma solução apontada para desacordo moral

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre Overruling e Backlash
- Considere como a consciência social influencia a reação ao direito das cortes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:49:42.931157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=43", "doc_key": "ea214f1dae97c1984b3ad0beb0a49b9b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f89c041ddbd9b8910d755f19577eeff50cc609947dc2344c0b8d1162ea9f3291')
